export const SPRINT_PAPERS = [{"id":"xiaosimen-daode-1","group":"道德与法治","subject":"道德与法治","term":"七年级上册","title":"道德与法治 · 七年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":0,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年北京中考·道德与法治第2题","stem":"某班开展“我的自画像”活动，两位同学交流了他们的想法。一位同学说：“每个人都不一样，我关注自己的特点，记录内心活动和情绪表现，‘画’出独特的我。”另一位同学说：“旁观者清，我主动倾听别人的意见，结合具体情况，‘画’出全面的我。”以上对话告诉我们（ ）","options":[{"key":"A","text":"生命是独特的，要关心身边每一个人"},{"key":"B","text":"可通过自我评价和他人评价认识自己"},{"key":"C","text":"要加强沟通，以同学们的意见为标尺"},{"key":"D","text":"情绪会相互感染，要用恰当方式表达"}],"answer":"B","explanation":"“我关注自己的特点，记录内心活动和情绪表现”属于自我评价；“我主动倾听别人的意见，结合具体情况，‘画’出全面的我”属于通过他人评价认识自己，B概括全面。材料没有体现生命的独特性，A排除；“以同学们的意见为标尺”的表述错误，我们重视他人评价，但他人评价不是标尺，C排除；材料没有强调表达的方式，D排除。故本题选B。"},{"type":"choice","tag":"Claude 精选","source":"2018年黑龙江齐齐哈尔中考真题","stem":"下列关于终身学习理解错误的是（ ）。","options":[{"key":"A","text":"当今社会，终身学习已经成为一种生活方式"},{"key":"B","text":"终身学习能使我们克服工作中的困难，解决工作中的一切问题"},{"key":"C","text":"终身学习是个人可持续发展的要求"},{"key":"D","text":"终身学习是社会发展的必然要求"}],"answer":"B","explanation":"终身学习能满足我们生存和发展的需要，使我们得到更大的发展空间，但不能解决工作中的一切问题，B项片面夸大了终身学习的作用。本题是逆向选择，选错误的项。"},{"type":"choice","tag":"Claude 精选","source":"2018年湖南遂宁中考真题","stem":"俗话说：“理想是丰满的，现实是骨感的；理想是美好的，现实是残酷的。”理想与现实的关系表述正确的是（ ）①理想和现实是既对立又统一的 ②现实来源于理想，理想是现实的升华 ③现实孕育着理想，是理想的基础 ④在一定条件下，理想可以转化为现实","options":[{"key":"A","text":"②③④"},{"key":"B","text":"①③④"},{"key":"C","text":"①②③"},{"key":"D","text":"①②④"}],"answer":"B","explanation":"理想来源于现实，是现实的升华；现实孕育着理想，是理想的基础；在一定条件下，理想可以转化为现实。②把二者的关系说反了。"},{"type":"choice","tag":"Claude 精选","source":"2018年贵州黔西南州中考真题","stem":"俗话说，行行出状元。山东淄博农民工赵有喜，把贴瓷砖这项普通瓦工活干出了新名堂，从一名小瓦工成长为“全国劳动模范”。赵有喜发自内心地说：“干建筑看上去是个粗活，要想取得成绩必须付出比别人更多的汗水，任何成功的背后都离不开艰辛的劳动和付出。”下列说法不符合题意的是（ ）。","options":[{"key":"A","text":"我们的梦想都是时刻变换的"},{"key":"B","text":"梦想的实现需要一点一滴的积累"},{"key":"C","text":"梦想激励我们不断超越自己"},{"key":"D","text":"梦想的实现需要坚持不懈的努力"}],"answer":"A","explanation":"少年的梦想不是空想，把梦想变成现实，需要付出努力、一点一滴积累、长期坚持不懈。A项错误，梦想并非都是时刻变换的，它具有一定的稳定性。本题是逆向选择。"},{"type":"choice","tag":"Claude 精选","source":"2018年河南中考真题","stem":"近年来，宝典、高参、秘笈等考场速查资料在一些初中开卷考试中受到部分学生追捧。这些价格不菲的资料号称“考题全中”“有我在手，考试必胜”，实则内容庞杂，粗制滥造，急功近利，误人子弟。部分学生听信宣传，抱着侥幸、投机心理，考试时，妄想按图索骥，照抄答案，结果耗时费力，事与愿违。这告诉我们（ ）。","options":[{"key":"A","text":"速查资料就是好，试题答案全找到"},{"key":"B","text":"学会学习最重要，增强实力是正道"},{"key":"C","text":"开卷考试就让抄，使用速查效率高"},{"key":"D","text":"考场速查很流行，略有瑕疵当宽容"}],"answer":"B","explanation":"部分学生抱着侥幸、投机心理照抄答案，结果耗时费力、事与愿违，这告诉我们学会学习最重要，增强自己的实力才是正道。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·道德与法治第9题","stem":"下列是课堂学习的一个环节：议题：深深浅浅话友谊。情境：小闽与小福是形影不离的好朋友，他们彼此分享，互相帮助。有一次，他俩一起参加校园歌手选拔赛，只有小闽被选上，小福依然对小闽表示真诚的祝贺。活动：阅读情境，小组讨论交流。任务：从情境中获得的对友谊的正确认识。同学们的发言要点：①友谊是一种亲密的关系 ②新朋友不如老朋友 ③友谊需要一方迁就包容 ④竞争并不必然伤害友谊。以上同学们的发言要点符合任务要求的是（ ）","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"①友谊是一种亲密的关系，符合友谊的特征；④小福落选后仍真诚祝贺小闽，说明竞争并不必然伤害友谊，符合情境。②“新朋友不如老朋友”错误，新老朋友都值得珍惜；③友谊需要平等、相互尊重，而不是一方迁就包容。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第7题","stem":"与友同行，需要智慧。下列行为能体现交友智慧的是（ ）①朋友有了新的伙伴，我会因为失落而疏远他 ②朋友犯错时，我会隐瞒事实帮助他逃避责任 ③朋友不愿诉说心事时，我会把握界限和分寸 ④与朋友同台竞技，我失败后会衷心地祝贺他","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"D","explanation":"③朋友不愿诉说心事时把握界限和分寸，是尊重朋友隐私、给对方空间的智慧；④竞技失败后衷心祝贺朋友，说明能正确对待竞争、不让竞争伤害友谊。①因失落而疏远朋友是狭隘、嫉妒的表现；②帮朋友隐瞒错误、逃避责任是讲“义气”不讲原则。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽中考·道德与法治第2题","stem":"近年来，我国儿童青少年超重肥胖率呈上升趋势。国家卫健委持续推进体重管理年行动，发布《儿童青少年肥胖食养指南（2024年版）》，普及健康生活方式。下列属于体重管理的正确方法是（ ）①合理膳食 ②接纳自己 ③适量运动 ④讲究卫生","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"A","explanation":"合理膳食能有效控制热量摄入，是体重管理的基础（①）；适量运动可消耗多余热量、增强体质，是体重管理的重要方式（③）。②接纳自己是心理健康的表现，但并非直接针对体重管理；④讲究卫生主要预防疾病传播，与体重管理无直接关联。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津中考·道德与法治第3题","stem":"小玲体谅父母的辛苦，经常帮父母做家务。她说：“劳动很光荣，这是我应该做的。”她的言行告诉我们要（ ）","options":[{"key":"A","text":"听取教导，理解父母"},{"key":"B","text":"孝亲敬长，服从安排"},{"key":"C","text":"推己及人，化解矛盾"},{"key":"D","text":"感恩父母，热爱劳动"}],"answer":"D","explanation":"小玲通过做家务表达对父母的感恩，并肯定劳动的价值。A题干强调主动承担家务劳动，而非单纯听取教导；B“服从安排”侧重被动接受，而小玲是主动体谅父母并劳动；C题干未涉及人际矛盾。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2018年湖北黄冈中考·道德与法治第1题","stem":"“牵妈妈的手”戳中了多少游子的愧疚心理，牵动了多少子女的感恩之情，也秀出了佳节团聚的幸福味道。百善孝为先，那个叫做“家”的人生开始的地方，始终是让我们倍感欣慰的温暖港湾；那双“妈妈的手”，永远是给我们力量的精神支撑。人生中，唯有爱与孝敬不能等待。“牵妈妈的手”引发网友的强烈共鸣。这启示我们应（ ）①体会父母为抚养我们付出的辛劳 ②继承和弘扬中华民族孝亲敬长的传统美德 ③亲近父母，理解体谅父母的一片苦心 ④当与父母发生“爱的冲突”时，要“得理不让人”，彰显自己的个性","options":[{"key":"A","text":"①②④"},{"key":"B","text":"①②③"},{"key":"C","text":"①③④"},{"key":"D","text":"①②③④"}],"answer":"B","explanation":"“牵妈妈的手”启示我们要弘扬孝亲敬长的传统美德，孝敬父母、亲近父母，体会父母为抚养我们付出的辛劳，①②③正确且符合题意。与父母发生冲突时，不要“得理不让人”，必要时做出适当的让步，有利于与父母的交往，④说法错误。故本题选B。"},{"type":"choice","tag":"Claude 精选","source":"2022年湖北十堰中考·道德与法治第1题","stem":"生活中难免有挫折。下列属于正确面对挫折的是（ ）","options":[{"key":"A","text":"一味沉浸在负面情绪中，消沉、焦虑"},{"key":"B","text":"失败一次，便自暴自弃"},{"key":"C","text":"保持乐观，在逆境中拼搏进取"},{"key":"D","text":"迁怒他人，对好朋友乱发脾气"}],"answer":"C","explanation":"面对挫折，我们可能会感到失落、焦虑、难过、愤怒、不满等，产生这些负面情绪感受是很正常的，但如果一味沉浸在负面情绪中，我们就容易消沉，甚至做出不恰当的行为。我们需要及时调整自己，正确看待挫折，保持乐观，在逆境中拼搏进取。故本题选C。"},{"type":"choice","tag":"Claude 精选","source":"2024年江西省中考·道德与法治第4题","stem":"下边古训印证了（ ）孝悌也者，其为仁之本欤！——《论语·学而》 夫孝者，天之经、地之义、民之行也。——《圣谕广训》①中华优秀“孝”文化源远流长 ②孝亲敬长是中华传统美德 ③尽孝就要采纳父母全部意见 ④孝亲敬长是公民的法定义务","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"A","explanation":"两则古训都讲“孝”，印证了中华优秀“孝”文化源远流长、孝亲敬长是中华传统美德，①②正确；③“采纳父母全部意见”错误，尽孝不等于盲从；④孝亲敬长是传统美德，赡养父母才是公民的法定义务，④说法不准确。故选A。"},{"type":"choice","tag":"Claude 精选","source":"改编自2024年广东省中考·道德与法治第3题（原题为图题，此处将图中的比赛项目转写为文字：初中组项目有插花、收纳行李、拆洗电风扇，小学组项目有包饺子、清洗碗碟、铺床套被子；知识点、选项与答案未改）","stem":"某校举办了一场家务劳动比赛，初中组项目有插花、收纳行李、拆洗电风扇，小学组项目有包饺子、清洗碗碟、铺床套被子。此举旨在（ ）","options":[{"key":"A","text":"教育大家正确认识友谊与竞争"},{"key":"B","text":"传承扶危济困的中华传统美德"},{"key":"C","text":"引导学生尊重劳动和热爱生活"},{"key":"D","text":"减轻家长们的经济负担和压力"}],"answer":"C","explanation":"家务劳动比赛让学生亲身感受劳动的过程和成果，体会劳动的价值和意义，从而学会尊重劳动和热爱生活，C正确；A、B、D均不符合题意。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2024年山西省中考·道德与法治第1题","stem":"青春的生命在解决困惑中不断成长。对小健同学的下列困惑回应正确的是（ ）","options":[{"key":"A","text":"接纳自己，包括接纳自己的不完美吗？——不包括，接纳自己是指接纳自己的优点"},{"key":"B","text":"班里制定班级公约，我可以提建议吗？——不需要，这是班主任和班干部的事"},{"key":"C","text":"挫折带给我们的影响都是消极的吗？——不是的，挫折可以磨砺意志，增强生命的韧性"},{"key":"D","text":"陌生网友询问我的家庭住址等个人重要信息，要不要说？——要，交网友也需要坦诚相待"}],"answer":"C","explanation":"A错误，接纳自己应该是全方位的，包括优点和不完美；B错误，班级公约的制定应该是全体班级成员共同参与的过程；C正确，挫折可以磨砺意志、增强生命的韧性；D错误，在网络交往中要保护个人隐私，不能向陌生网友透露家庭住址等重要信息。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京大兴区初三二模·道德与法治第12题","stem":"中华优秀传统文化闪烁着智慧的光芒。下列名言警句有助于我们学会学习的是（ ）①苟日新，日日新，又日新。——《礼记》 ②独学而无友，则孤陋而寡闻。——《礼记》 ③交友投分，切磨箴规。——《千字文》 ④穷则独善其身，达则兼济天下。——《孟子》","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"A","explanation":"①'苟日新，日日新，又日新'强调不断更新、不断学习；②'独学而无友，则孤陋而寡闻'强调与人交流合作学习。③讲交友，④讲处世，都与学会学习无关。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-self-knowledge","stem":"小林在周记里反思自己做事拖拉，又听到同学夸他“很有耐心”。他把两方面对照事实，定下了改进计划。这说明认识自己可以","options":[{"key":"A","text":"把自我评价和他人评价结合起来"},{"key":"B","text":"只依靠自我评价"},{"key":"C","text":"他人的评价一定准确，照单全收"},{"key":"D","text":"认识自己一次就能完成"}],"answer":"A","explanation":"认识自己既要自我反思，也要听取他人评价，并对照事实作出判断；他人评价也需要分析。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-friendship","stem":"好朋友考试作弊被发现，请你帮他向老师隐瞒。你应该","options":[{"key":"A","text":"在班级群里公开这件事"},{"key":"B","text":"提醒他主动承认错误，并在他改正时给予帮助"},{"key":"C","text":"为了友谊帮他隐瞒"},{"key":"D","text":"从此和他绝交"}],"answer":"B","explanation":"友谊不是无原则的。为朋友掩盖错误会妨碍他承担责任，恰当的做法是提醒、劝止，并支持他改正。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-collective-goal","stem":"班级把“唱出团结”定为合唱比赛目标，同学们分工练声、设计服装、排练伴奏，最终获奖。这体现了","options":[{"key":"A","text":"个人特长在集体中没有作用"},{"key":"B","text":"集体成绩与个人努力无关"},{"key":"C","text":"共同目标把个人努力汇聚成集体力量"},{"key":"D","text":"集体就是个人的简单相加"}],"answer":"C","explanation":"共同目标指明方向，成员分工配合、发挥特长，个人努力才能汇成集体成果。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-family-dialogue","stem":"妈妈不同意小雨周末独自去远处玩。小雨先了解到妈妈担心安全，再说明同行同学和返回时间，妈妈同意了。这启示我们与父母沟通要","options":[{"key":"A","text":"坚持己见，绝不让步"},{"key":"B","text":"回避矛盾，什么都不说"},{"key":"C","text":"认为父母的意见永远正确"},{"key":"D","text":"先理解父母的担心，再表达自己的想法"}],"answer":"D","explanation":"遇到分歧时，先了解家人在担心什么，再说自己的想法，更容易达成理解。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-meaningful-life","stem":"一位乡村医生几十年坚守山村，为村民看病。他的事迹告诉我们","options":[{"key":"A","text":"在平凡中持续付出、关怀他人，也能创造生命的价值"},{"key":"B","text":"只有做惊天动地的大事，人生才有意义"},{"key":"C","text":"生命的价值由职业的高低决定"},{"key":"D","text":"关爱生命只是珍惜自己的生命"}],"answer":"A","explanation":"关爱生命既包括珍视自己，也包括关怀他人；把力所能及的事持续做好，人生同样有意义。"}]},{"title":"二、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"判断说理","source":"2025年福建中考·道德与法治第26题(2)（参考答案按教材整理）","kind":"判断说理","material":"小敏：最近，小明总是喜欢用不雅语言和别人开玩笑，让人感到很不舒服。\n小文：我也发现了。我建议，作为他的好朋友，我们应该规劝他。","stem":"判断小文的建议是否正确，并说明理由。（4分）","points":[{"text":"判断：✓","score":1},{"text":"友谊不能没有原则，对朋友的不良行为不能纵容","score":1},{"text":"帮助朋友改正缺点是真诚的表现，是对朋友负责，体现友谊的力量","score":1},{"text":"有利于小明成长和维护良好的同学关系","score":1}],"score":4,"sample":"","explanation":"七年级“友谊的天空”：友谊是一种道德承诺，不能以牺牲原则为代价；朋友犯错时真诚规劝才是真正的友谊。"},{"type":"essay","tag":"材料分析题","source":"2025年福建中考·道德与法治第28题(1)（参考答案按教材整理）","kind":"材料分析题","material":"【沉睡千年的家书】在湖北省云梦县博物馆内陈列着“黑夫木牍”的家书复制品。经考证，这是战国时期秦国士兵“黑夫”和“惊”写给兄长“衷”的信，是迄今我国发现的最早家书实物。短短527字的家书，一声声别来无恙的问候，至今读来依然令人动容。木牍内容节选：“二月辛巳，黑夫、惊敢再拜问衷，母毋恙也？黑夫、惊毋恙也……”","stem":"根据材料，运用所学知识，分析家书中一声声别来无恙的问候为何至今依然令人动容。（6分）","points":[{"text":"家是情感的港湾，亲情是人间最真挚的情感，家书承载着浓浓的亲情","score":2},{"text":"问候体现了孝亲敬长的中华传统美德","score":2},{"text":"中华家书文化、家国情怀源远流长，凝结着中华民族共同的价值追求，历久弥新","score":2}],"score":6,"sample":"","explanation":"对应“亲情之爱”“中华优秀传统文化”。问候母亲“毋恙也”，是孝亲；“至今动容”是因为情感和价值观跨越时空。"}]}]},{"id":"xiaosimen-daode-2","group":"道德与法治","subject":"道德与法治","term":"七年级下册","title":"道德与法治 · 七年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年黑龙江牡丹江中考·道德与法治第7题","stem":"2023年5月20日，在羽毛球苏迪曼杯半决赛中，中国队在大比分落后的情况下，团结一心，奋勇拼搏，实现超级大逆转，战胜日本队挺进决赛，并在随后的决赛中战胜韩国队，第十三次捧得苏迪曼杯。中国羽毛球队的胜利表明（ ）","options":[{"key":"A","text":"团结的集体可以战胜一切对手"},{"key":"B","text":"集体的胜利要凭天赋和运气"},{"key":"C","text":"优秀的集体需要牺牲个人利益"},{"key":"D","text":"集体的力量来源于团结协作"}],"answer":"D","explanation":"中国队在大比分落后的情况下团结一心、奋勇拼搏，实现超级大逆转，表明集体的力量来源于团结协作。“可以战胜一切对手”“要凭天赋和运气”“需要牺牲个人利益”的表述都错误。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2024年天津中考真题","stem":"青春，需要我们去经历、去体验、去反思。做好青春选择，过好青春生活，需要（ ）①明辨是非，行己有耻 ②自傲自负，敢于尝试 ③自我省察，止于至善 ④自立自强，我行我素","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"做好青春选择，需要明辨是非、行己有耻，自我省察、止于至善。自傲自负是不良心态，“我行我素”会忽视他人感受和社会规则，故②④错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年山西中考真题","stem":"社团活动总结会上，小德说：“加入‘小主持人社团’后，在老师和同学的鼓励下，我跟大家一起学习、主持、表演，现在的我变得很自信！”小德的发言启示我们要（ ）。","options":[{"key":"A","text":"尊重不同风格的老师"},{"key":"B","text":"涵养正直的良好品格"},{"key":"C","text":"积极参与集体活动，完善自己的个性"},{"key":"D","text":"增强自我保护意识，谨慎结交新朋友"}],"answer":"C","explanation":"小德通过参与社团活动，在集体中学习、实践，完善了自身个性（如自信），说明集体生活有助于我们不断提升和完善自己。"},{"type":"choice","tag":"Claude 精选","source":"2024年黑龙江齐齐哈尔中考真题","stem":"《未成年人网络保护条例》自2024年1月1日起施行，条例规定网络产品和服务提供者应当建立健全防沉迷制度。此规定（ ）。","options":[{"key":"A","text":"限制了未成年人的权利和自由"},{"key":"B","text":"解决了未成年人沉迷网络的问题"},{"key":"C","text":"体现了对未成年人的网络保护"},{"key":"D","text":"赋予了未成年人使用网络的特权"}],"answer":"C","explanation":"《未成年人网络保护条例》规定网络产品和服务提供者建立健全防沉迷制度，体现了对未成年人的网络保护。这不是限制权利自由，也不能完全解决沉迷问题，更不是赋予特权。"},{"type":"choice","tag":"Claude 精选","source":"2024年湖北中考真题","stem":"奋斗是青春最亮丽的底色，行动是青年最有效的磨砺。新时代青年应挺膺担当，用坚持与努力描绘属于自己的绚丽画卷。这启迪我们在强国建设中要（ ）","options":[{"key":"A","text":"展现青春作为，贡献青春力量"},{"key":"B","text":"编织人生梦想，注重个人利益"},{"key":"C","text":"努力张扬个性，享受青春激情"},{"key":"D","text":"正确认识自己，接纳自身变化"}],"answer":"A","explanation":"新时代青年挺膺担当、坚持努力，启示我们在强国建设中展现青春作为、贡献青春力量。B只注重个人利益，C是享乐主义，D与强国建设主题联系不紧密。"},{"type":"choice","tag":"Claude 精选","source":"2024年江苏徐州中考真题","stem":"有人说，个人的努力是加法，团队的努力是乘法。对此观点理解正确的是（ ）","options":[{"key":"A","text":"集体为个人搭建了交往的平台"},{"key":"B","text":"维护集体利益必须放弃个人利益"},{"key":"C","text":"集体成员之间的相互竞争是集体发展的动力"},{"key":"D","text":"个人的力量是有限的，集体的力量是强大的"}],"answer":"D","explanation":"个人的努力是加法、团队的努力是乘法，体现了个人的力量是有限的，集体力量是强大的。A题干未涉及交往平台；B“必须放弃”说法绝对；C题干未涉及竞争。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·道德与法治第13题","stem":"空军航空兵某团飞行二大队以维护国家主权和领土完整为使命，他们从单打独斗到成体系作战，快速成长为我军一支重要的空中力量。由此可见，他们的快速成长得益于（ ）①拥有辉煌的战绩 ②具有团结协作的精神 ③拥有共同的愿景 ④具有鲜明的个性特点","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"C","explanation":"从“单打独斗”到“成体系作战”，体现了团结协作的精神（②）；以维护国家主权和领土完整为使命，体现了共同的愿景引领集体成员奋进（③）。①辉煌战绩是成长的结果而非原因；④鲜明个性与集体快速成长无直接关系，集体力量靠的是团结与共同目标。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第9题","stem":"“刘老庄连”是诞生于抗日烽火的英雄连队。八十多年来，“有我在，连旗不倒”的铿锵誓言激励着一批批官兵争当强军先锋，出色完成各项重大任务。2025年，连队被授予“时代楷模”称号。材料表明（ ）①共同的愿景引领集体成员开拓进取 ②集体生活可以提升人际交往的能力 ③集体的荣誉是成员共同奋斗的结果 ④集体的规则需要集体成员共同制定","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"“有我在，连旗不倒”的誓言是连队共同的愿景，激励一代代官兵开拓进取（①）；“时代楷模”的荣誉是一批批官兵共同奋斗的结果（③）。②集体生活确实能提升交往能力，但材料讲的是誓言激励与荣誉，不在讨论交往能力；④材料未涉及集体规则的制定。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年重庆中考·道德与法治第1题","stem":"健康是个人的财富，也是家庭幸福的支撑。为了促进身心和谐、保持身心健康，中学生李华与家人共同商议制订“健康家庭行动方案”。以下商议内容科学合理的是（ ）①拟定家庭健身计划，一起科学健身 ②了解家庭急救知识，关注家人健康 ③回避家庭问题，避免产生消极情绪 ④参观画展，在艺术熏陶中滋养心灵","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"B","explanation":"科学健身、了解急救知识、艺术熏陶滋养心灵都有利于身心健康（①②④）；③回避家庭问题不是解决办法，消极情绪需要正视和转化，回避只会积累矛盾。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年安徽中考·道德与法治第3题（原题为表格题，此处将表格内容转写为文字叙述；知识点、选项与答案未改）","stem":"青春期是身体发育和心理发展的加速期。七年级男生小刚在生活中遇到了烦恼。以下解答正确的是（ ）①喜欢和女生开玩笑，想表现自己，却引起反感——把握好交往尺度，言谈得当，举止得体 ②看到同学长高长壮，自己还这么瘦小——追求内在美，不必在意外在形象 ③已经长大了，妈妈还是对我什么事都要管——加强沟通，相互理解 ④总是否定别人，很多同学不喜欢我——求同存异，善于发现别人的闪光点","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"C","explanation":"①异性交往需把握分寸，言谈举止得体有助于建立良好关系；③与父母加强沟通能化解矛盾，促进相互理解；④学会欣赏他人优点、求同存异是人际交往的重要原则。②青春期应接纳身体变化，追求内在美不等于完全忽略外在形象，故②说法错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津中考·道德与法治第7题","stem":"青春给我们插上了飞翔的翅膀，但也绝非是放纵不羁。这说明（ ）","options":[{"key":"A","text":"青春飞扬，自傲自负"},{"key":"B","text":"青春有格，行己有耻"},{"key":"C","text":"青春短暂，正视挫折"},{"key":"D","text":"青春美好，尝试一切"}],"answer":"B","explanation":"题干强调青春虽充满活力，但不可放纵，需有所节制。“行己有耻”指行事有底线，符合题干“不放纵”的要求。A“自傲自负”是负面态度；C“正视挫折”与题干中“约束行为”无直接关联；D“尝试一切”与“不放纵”矛盾。故本题选B。"},{"type":"choice","tag":"Claude 精选","source":"2024年天津中考·道德与法治第5题","stem":"2024年4月，天津市举行第38届青少年科技创新大赛，187项成果被推荐参加全国比赛。开展此项活动有利于青少年（ ）①走进科学，培养科学精神 ②敢于挑战，否定一切权威 ③勇于探索，开发创造潜力 ④独立思考，培养批判思维","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"C","explanation":"通过参与科技创新大赛，青少年能够更深入地接触科学知识和研究方法，培养对科学的热爱和尊重；竞赛鼓励青少年勇于尝试新的想法和方法，挖掘自身的创造潜能；在准备参赛作品的过程中，青少年需要独立思考问题，对现有知识和方法进行批判性的分析和改进，①③④正确。②“敢于挑战，否定一切权威”说法过于绝对和偏激，挑战权威应该是基于理性和证据，而不是盲目地否定一切。故本题选C。"},{"type":"choice","tag":"Claude 精选","source":"2024年黑龙江牡丹江中考·道德与法治第8题","stem":"看着像可乐罐的电子烟、五颜六色的跳跳糖、香甜可口的奶茶……这些看似常见的饮料、零食，有些竟然是伪装的毒品，引诱不明真相的年轻人落入陷阱。这警示我们未成年人要（ ）","options":[{"key":"A","text":"拒绝喝饮料和吃零食"},{"key":"B","text":"尽量避免与他人交往"},{"key":"C","text":"加大对毒品犯罪的打击力度"},{"key":"D","text":"提高辨别和拒绝不良诱惑的能力"}],"answer":"D","explanation":"我们要拒绝的是那些伪装成饮料和零食的毒品，而不是拒绝所有饮料和零食；加大对毒品犯罪的打击力度是国家的事，而不是未成年人；材料警示未成年人要提高辨别和拒绝不良诱惑的能力。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2024年江西省中考·道德与法治第13题","stem":"2024年4月26日，教育部会同公安部、国家消防救援局等部门召开全国中小学幼儿园安全工作视频会议。会议指出，要深入实施学生欺凌防治专项行动，对所有中小学校开展一次“起底式”大排查。材料体现出（ ）①我国完善未成年人保护的法律体系 ②多方协同能确保未成年人免受伤害 ③国家关心和重视未成年人健康成长 ④政府依法履行保护未成年人的职责","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"D","explanation":"多部门联合开展学生欺凌防治专项行动，体现了国家关心和重视未成年人健康成长，政府依法履行保护未成年人的职责，③④正确；①材料未涉及完善法律体系；②“确保”说法过于绝对，多方协同不能保证未成年人完全免受伤害。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京西城区初三二模·道德与法治第12题","stem":"针对以下同学的困惑，建议合理的是（ ）①脸上的痘痘越来越多，我真是太丑了——正视身体的变化，不因生理变化而自卑 ②我很内向，很羡慕那些开朗活泼的同学——全面认识自己，用乐观的心态接纳自己 ③我受了委屈，妈妈说哭是懦弱的表现——要学会合理地调节自己的情绪，不能哭 ④参加一些社会实践活动，耽误我的学习——学习是最为重要的，可以放弃参加实践","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"A","explanation":"①正视身体变化、不因生理变化而自卑是正确的；②全面认识自己、用乐观心态接纳自己是正确的；③“不能哭”是错误的，合理调节情绪不等于压抑情绪；④社会实践也是学习的重要途径，不能放弃。故选A。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-puberty-changes","stem":"小明因为个子比同学矮而苦恼。对此正确的认识是","options":[{"key":"A","text":"这种烦恼不能跟任何人说"},{"key":"B","text":"青春期发育存在个体差异，要接纳自己、发现自身长处"},{"key":"C","text":"个子矮说明发育不正常"},{"key":"D","text":"应该经常和同学比身高外貌"}],"answer":"B","explanation":"发育速度有个体差异。用身高外貌给自己打分，容易忽略个体差异和自身长处；可以通过运动、交流、求助来应对烦恼。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-emotion-and-feeling","stem":"下列属于较为稳定的“情感”，而不是一时“情绪”的是","options":[{"key":"A","text":"听到笑话哈哈大笑"},{"key":"B","text":"被误会时一阵委屈"},{"key":"C","text":"多年来对家乡深深的眷恋"},{"key":"D","text":"比赛前紧张得手心出汗"}],"answer":"C","explanation":"情绪随具体情境产生、变化较快；对家乡、亲人等长久积累形成的感受较为稳定，属于情感。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-minor-protection","stem":"某人民法院在审理涉及未成年人的案件时，安排心理疏导并注意保护其隐私。这属于","options":[{"key":"A","text":"家庭保护"},{"key":"B","text":"学校保护"},{"key":"C","text":"网络保护"},{"key":"D","text":"司法保护"}],"answer":"D","explanation":"判断六类保护先看谁在行动：人民法院在办案中保护未成年人合法权益，属于司法保护。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-legal-liability","stem":"张某在公共场所打架斗殴，被公安机关处以行政拘留 10 日。张某的行为属于","options":[{"key":"A","text":"一般违法行为，承担行政责任"},{"key":"B","text":"犯罪行为，承担刑事责任"},{"key":"C","text":"民事违法行为，承担民事责任"},{"key":"D","text":"不违法的行为"}],"answer":"A","explanation":"公安机关作出的行政拘留是行政处罚，对应行政违法、行政责任；犯罪要触犯刑法并应受刑罚处罚。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-culture-inheritance","stem":"某博物馆用数字技术“复活”古画，并配上原典讲解。对此认识正确的是","options":[{"key":"A","text":"数字技术会让传统文化失去价值"},{"key":"B","text":"用新形式传播传统文化，同时要保留它原有的文化内涵"},{"key":"C","text":"只要形式新，就一定做到了传承"},{"key":"D","text":"传统文化应原封不动锁在库房里"}],"answer":"B","explanation":"新形式能帮助传播；判断是否传承，还要看原有文化内涵是否得到保留和表达。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"法律由国家制定或认可，靠国家____保证实施，对全体社会成员具有____约束力。","answer":["强制力","普遍"],"explanation":"这是法律区别于道德、纪律等其他规范的特征。"},{"type":"blank","stem":"____是专门保护未成年人的法律；我国对未成年人给予家庭、学校、社会、网络、政府和____六大保护。","answer":["未成年人保护法","司法"],"explanation":"2020年修订《未成年人保护法》，增加了网络保护和政府保护。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据七年级下册“青春时光”编写","kind":"简答题","material":"","stem":"青春期的心理矛盾有哪些表现？我们应如何正确对待？（6分）","points":[{"text":"表现：反抗与依赖、闭锁与开放、勇敢与怯懦等","score":2},{"text":"正确对待：这些矛盾是成长的契机，要积极面对","score":2},{"text":"方法：参加集体活动、多与父母老师朋友交流、在实践中锻炼，调节情绪","score":2}],"score":6,"sample":"","explanation":"青春期是人生中充满活力的时期，要学会接纳和调控自己。"},{"type":"essay","tag":"简答题","source":"依据七年级下册“做情绪情感的主人”编写","kind":"简答题","material":"","stem":"调控情绪有哪些方法？请至少写出三种并简要说明。（6分）","points":[{"text":"改变认知评价（换个角度看问题）","score":2},{"text":"转移注意（做自己喜欢的事）","score":2},{"text":"合理宣泄（倾诉、运动、哭泣）；放松训练（深呼吸）","score":2}],"score":6,"sample":"","explanation":"合理宣泄要注意场合和方式，不能伤害自己和他人。"}]}]},{"id":"xiaosimen-daode-3","group":"道德与法治","subject":"道德与法治","term":"八年级上册","title":"道德与法治 · 八年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年北京中考·道德与法治第7题","stem":"健康生活理念深入人心，人们骑行和步行的需求日益增加。为让大家拥有更好的体验，不少公园将原有的混行路道，调整为自行车专用道和步行专用道，但个别人随意乱用，影响他人安全。对此，下列认识正确的是（ ）①随着社会生活的变化，公园改进完善规则 ②公园赋予骑行者和步行者平等的社会经济权利 ③专用道使用者应自觉遵守规则，加强自律 ④人们有使用道路的权利，可按个人意愿任意使用","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"公园将原有的混行路道调整为自行车专用道和步行专用道，说明随着社会生活的变化，公园改进完善规则，①符合题意；个别人随意乱用，影响他人安全，是没有遵守规则的行为，专用道使用者应自觉遵守规则、加强自律，③符合题意；材料没有体现社会经济权利，②排除；公园规划了自行车专用道和步行专用道，应分功能使用，“可按个人意愿任意使用”的表述错误，④排除。故本题选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津中考真题","stem":"我们在很多公共场所悬挂“静”字提示语的作用是（ ）。","options":[{"key":"A","text":"改进社会规则"},{"key":"B","text":"维护公共秩序"},{"key":"C","text":"限制人身自由"},{"key":"D","text":"扩大公民权利"}],"answer":"B","explanation":"很多公共场所悬挂“静”字、请勿大声喧哗，目的是维护社会秩序。规则的建立不是限制人身自由，必要的限制是公民享有自由的保障。"},{"type":"choice","tag":"Claude 精选","source":"2024年山东泰安中考真题","stem":"2023年12月2日是第十二个“全国交通安全日”，主题为“文明交通你我同行”，倡议社会各界协同共建文明交通，人人共享交通文明。下列说法正确的是（ ）。","options":[{"key":"A","text":"在道路上骑自行车必须年满12周岁"},{"key":"B","text":"可以在道路上骑独轮自行车或者2人以上骑行的自行车"},{"key":"C","text":"在道路上骑自行车可以双手离把、手中持物、扶身并行"},{"key":"D","text":"可以在道路上滑旱冰、玩滑板、嬉戏打闹"}],"answer":"A","explanation":"《道路交通安全法实施条例》规定，在道路上骑自行车必须年满12周岁。不得在道路上骑独轮自行车或2人以上骑行的自行车，不得双手离把、手中持物，行人不得在道路上使用滑板、旱冰鞋等滑行工具。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南中考真题","stem":"小明购买文具时，发现店主多找了钱后主动退还。小明的行为体现的美德是（ ）。","options":[{"key":"A","text":"勤俭节约"},{"key":"B","text":"诚实守信"},{"key":"C","text":"乐善好施"},{"key":"D","text":"敬业乐群"}],"answer":"B","explanation":"小明主动归还店主多找的钱，体现了不贪利、守诚信的品质。诚信是中华传统美德，也是个人安身立命之本。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川自贡中考真题","stem":"15岁少年张某是一名骑行爱好者，他经常把公共道路当“竞技场”，肆意竞速。作为朋友，你会劝告他（ ）①生命来之不易，珍爱生命 ②树立安全意识，做到安全文明骑行 ③遵守交通法规，敬畏规则 ④保持爱好，不断满足自己的征服欲","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"A","explanation":"公共道路竞速危及自身及他人生命安全，应劝告他珍爱生命、树立安全意识、安全文明骑行、遵守交通法规、敬畏规则。④保持危险爱好、满足征服欲会加剧安全隐患，错误。"},{"type":"choice","tag":"Claude 精选","source":"2024年四川成都中考真题","stem":"应急车道，是专门供工程救险、消防救援、医疗救护或民警执行紧急公务等处理应急事务车辆使用的车道，也被称为“生命通道”。我国法律明确规定侵占应急车道是违法行为，但在社会生活中，侵占应急车道的现象却屡禁不止。面对这一现象，我们呼吁（ ）①提高文明素养，坚持生命至上 ②制定法律法规，维护公共利益 ③增强安全意识，提升驾驶技能 ④自觉遵守规则，维护社会秩序","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"侵占应急车道就是侵占“生命通道”，应呼吁提高文明素养、坚持生命至上，自觉遵守规则、维护社会秩序。②我国已有法律规定侵占应急车道违法，应呼吁严格执法而非再立法；③侵占应急车道不是因为驾驶技能不高，而是缺乏生命意识和规则意识。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第5题","stem":"小闽准备参加“了解国防知识，筑牢国防意识”的主题演讲活动。下列时事适合用于本次演讲的是（ ）①截至2024年底，我国汽车产销总量连续16年稳居全球第一 ②2025年4月4日起，我国对7类中重稀土相关物项实施出口管制 ③2025年2月，我国印发《优化消费环境三年行动方案（2025—2027年）》 ④2024年12月27日，我国自主研制建造的大型战舰——四川舰成功下水","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"C","explanation":"演讲主题是国防知识：②对中重稀土相关物项实施出口管制，涉及国家安全与国防资源保护；④四川舰成功下水是我国国防装备建设的重大成就，都适合用于国防演讲。①汽车产销属于经济发展，③优化消费环境属于经济民生，与国防主题无关。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第13题","stem":"“中国好人”李培生是黄山风景区基层工作人员。20多年来，他在悬崖峭壁上捡拾垃圾和游客掉下的物品，累计放绳高度达1800千米，相当于200次登顶珠穆朗玛峰，用心用情守护着美丽的黄山。他的事迹告诉我们（ ）①劳动能够创造人生价值 ②他人的生命更重要 ③平凡中也能闪耀出伟大 ④保护环境重在治理","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"A","explanation":"李培生20多年坚守平凡岗位、守护黄山：①他的劳动创造了人生价值；③平凡的岗位上也能闪耀出伟大。②材料讲的是捡拾垃圾、守护环境，没有涉及“他人的生命更重要”；④保护环境需要治理，但材料强调的是个人坚守奉献，不是“重在治理”。故选A。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第14题","stem":"从港珠澳大桥连通粤港澳大湾区，到贵州花江峡谷大桥架起云端通途，一个个国家超级工程，不仅关乎国家的强盛和安全，更是为了满足人民“路好走”的朴素愿望。材料表明（ ）","options":[{"key":"A","text":"维护国家利益是公民的基本义务"},{"key":"B","text":"国家利益能够反映每个人的需求"},{"key":"C","text":"国家利益和人民利益是高度统一的"},{"key":"D","text":"维护国家利益有时需要放弃个人利益"}],"answer":"C","explanation":"超级工程既关乎国家强盛和安全（国家利益），又满足人民“路好走”的愿望（人民利益），说明国家利益和人民利益是高度统一的。A讲的是公民义务，与材料无关；B“能够反映每个人的需求”说法绝对，国家利益反映的是人民的整体利益；D讲的是二者冲突时的取舍，材料讲的是二者统一。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2024年黑龙江牡丹江中考·道德与法治第9题","stem":"今年2月，黑龙江省委副书记、省长梁惠玲主持召开省长办公会议强调，我省要推进主要粮食作物大面积单产提升，切实当好国家粮食安全“压舱石”。因为粮食安全（ ）","options":[{"key":"A","text":"是国家安全的根本"},{"key":"B","text":"在国家安全体系中居于首位"},{"key":"C","text":"关乎经济社会稳定和国家安全"},{"key":"D","text":"是人民幸福安康的唯一保障"}],"answer":"C","explanation":"粮食安全关乎经济社会稳定和国家安全，是国家安全的重要基础。A国家安全的根本是政治安全；B“居于首位”的表述不准确，总体国家安全观以人民安全为宗旨、以政治安全为根本；D“唯一保障”说法绝对。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京西城区初三二模·道德与法治第14题","stem":"地铁上，一男子因嫌弃旁边乘客衣服沾灰，不停辱骂该乘客。此时，一名女乘客挺身而出，进行制止：“你要是不愿跟他挨着，就别坐这儿了，我愿意跟他挨着。”随后，女乘客轻声安抚邻座乘客。人们对女乘客的做法纷纷点赞，这是因为（ ）①要发自内心的尊重他人人格，做到平等待人 ②我们应该重视他人，对他人的请求给予帮助 ③能够欣赏他人，善于发现他人的潜质和特质 ④正义要求人们惩恶扬善，维护社会公共利益","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"女乘客制止辱骂、安抚邻座，体现了发自内心尊重他人人格、平等待人，①正确；挺身而出制止不文明行为，体现了正义要求人们惩恶扬善，④正确；②③与材料主旨不符。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京大兴区初三二模·道德与法治第18题","stem":"新修订的《中华人民共和国国防教育法》规定，国家在全体公民中开展以爱国主义为核心，以履行国防义务为目的，与国防和军队建设有关的理论、知识、技能以及科技、法律、心理等方面的国防教育。这有利于（ ）①树立总体国家安全观，坚持走中国特色国家安全道路 ②强化法律对道德建设的促进作用，发挥道德的规范作用和法律的教化作用 ③增强公民法律意识，在生活中履行维护国家安全、荣誉和利益的权利 ④弘扬以爱国主义为核心的民族精神，培育家国情怀和担当精神","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"开展国防教育有利于树立总体国家安全观，坚持走中国特色国家安全道路，①正确；有利于弘扬以爱国主义为核心的民族精神，培育家国情怀和担当精神，④正确；②与材料无关；③错在“权利”，维护国家安全、荣誉和利益是公民的义务。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京房山区初二（上）期末·道德与法治第12题","stem":"2024年7月20日，全民健身线上运动会启动仪式在北京石景山首钢园举行。运动会借助虚拟技术和人工智能打造一批虚拟赛事和智能赛事，如数字赛车、虚拟自行车、虚拟赛艇等，通过虚拟技术增加互动性和沉浸感，形成人机互联，带动更多群众尤其是年轻人参与、体验线上虚拟赛事活动，打造多维度健身空间，掀起沉浸式全民健身热潮。这说明（ ）","options":[{"key":"A","text":"网络拉近了人与人间的关系"},{"key":"B","text":"网络促进民主政治的进步"},{"key":"C","text":"网络充满正能量弘扬主旋律"},{"key":"D","text":"网络让运动方式丰富多样"}],"answer":"D","explanation":"虚拟赛事、智能赛事等说明网络让运动方式丰富多样。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京房山区初二（上）期末·道德与法治第15题","stem":"81岁高龄的周代全是一名退休已21年的老党员。他主动申请“关爱帮扶老人”微创投项目，主动担起社区老年服务站站长，成立了由32人组成的银龄志愿服务队，每月针对空巢、独居、失能失智老人进行上门探访。他用心、用情为居民服务、办实事，赢得广泛好评。周代全的退休生活体现了（ ）①牢记初心使命，积极服务社会 ②崇尚劳动光荣，珍惜劳动成果 ③热心公益活动，展现党员形象 ④收获他人好评，践行终身学习","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"①周代全牢记初心使命，积极服务社会；③热心公益活动，展现党员形象。②材料未体现崇尚劳动光荣、珍惜劳动成果；④收获他人好评不是践行终身学习。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京房山区初二（上）期末·道德与法治第18题","stem":"2024年4月19日，中国人民解放军信息支援部队成立大会在北京举行。这支部队是全新打造的战略性兵种，是统筹网络信息体系建设运用的关键支撑，在推动军队高质量发展和打赢现代战争中地位重要、责任重大。这从一个侧面反映出（ ）①我国正在全面推进国防和军队现代化建设 ②人民军队的职责就是巩固国防、抵抗侵略 ③公民应该增强维护国家安全的意识与责任 ④适应国家安全需求，发挥军队坚强柱石作用","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"B","explanation":"①我国正在全面推进国防和军队现代化建设；④适应国家安全需求，发挥军队坚强柱石作用。②人民军队的职责包括巩固国防、抵抗侵略、保卫祖国、保卫人民的和平劳动、参加国家建设事业等，'就是'说法片面；③材料未体现公民维护国家安全的意识与责任。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-media-literacy","stem":"小华在网上看到一张“明天全市停课”的截图。他的正确做法是","options":[{"key":"A","text":"截图有图有真相，一定可信"},{"key":"B","text":"加上自己的评论再转发"},{"key":"C","text":"先核对官方来源和发布日期，再决定是否转发"},{"key":"D","text":"立即转发到班级群提醒大家"}],"answer":"C","explanation":"遇到消息、截图或 AI 给出的结论，要核对来源、日期和上下文，再决定采用或转发。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-equality","stem":"公交车设置无障碍踏板，地铁站铺设盲道。这体现了","options":[{"key":"A","text":"平等就是人人获得完全相同的服务"},{"key":"B","text":"给残障人士的特权"},{"key":"C","text":"浪费公共资源"},{"key":"D","text":"对特殊需要的合理照顾，帮助他们平等参与社会生活"}],"answer":"D","explanation":"平等也包含对特殊需要的合理照顾，关键看是否让人获得实际参与的机会。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-rules-and-freedom","stem":"有居民深夜在家大声唱歌，影响邻居休息。这告诉我们","options":[{"key":"A","text":"自由是有边界的，行使自由不能损害他人的合法权益"},{"key":"B","text":"在自己家里做什么都可以"},{"key":"C","text":"规则限制了我们的一切自由"},{"key":"D","text":"邻居应该一直忍耐"}],"answer":"A","explanation":"自由的行使要受法律约束，并尊重他人的合法权益；公共规则帮助大家减少冲突。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-social-responsibility","stem":"志愿者到养老院服务前，先了解老人需要什么，再选择陪聊、读报等方式。这说明承担责任","options":[{"key":"A","text":"就不能事先做任何计划"},{"key":"B","text":"要先了解对方需要，选择安全、合适、力所能及的方法"},{"key":"C","text":"不需要考虑对方的需要"},{"key":"D","text":"只限于法律明确规定的事"}],"answer":"B","explanation":"帮助他人时先了解需要，再选择安全、合适、力所能及的方法，责任才能落到行动和效果上。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-national-interest","stem":"国家修建跨海大桥，完善了区域交通网络，也方便了群众出行。这体现了","options":[{"key":"A","text":"这项工程满足了每个人的所有需求"},{"key":"B","text":"这项工程只对个别人有利"},{"key":"C","text":"国家利益与人民利益在根本上是一致的"},{"key":"D","text":"国家利益与群众生活无关"}],"answer":"C","explanation":"交通等建设可以同时服务整体发展和群众生活；说“满足每个人的所有需求”超出了材料。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"犯罪的三个基本特征是：严重的社会危害性、____性和应受刑罚处罚性。","answer":["刑事违法"],"explanation":"严重的社会危害性是犯罪最本质的特征。"},{"type":"blank","stem":"我国的国家安全举报受理电话是____。","answer":["12339"],"explanation":"每年4月15日为全民国家安全教育日。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"判断说理","source":"2025年福建中考·道德与法治第26题(1)（参考答案按教材整理）","kind":"判断说理","material":"小敏：最近，小明总是喜欢用不雅语言和别人开玩笑，让人感到很不舒服。\n小文：我也发现了。我建议，作为他的好朋友，我们应该规劝他。","stem":"判断小明的行为是否正确（正确打“✓”，不正确或不完全正确打“×”），并说明理由。（4分）","points":[{"text":"判断：×","score":1},{"text":"小明的行为不尊重他人，伤害了他人的感受","score":1},{"text":"违背了文明有礼的要求，不利于建立良好的人际关系，也损害自身形象","score":1},{"text":"我们应尊重他人，文明用语、以礼待人","score":1}],"score":4,"sample":"","explanation":"对应八年级上册“遵守社会规则·以礼待人”：尊重他人是一种文明的社交方式，是处理好人际关系的基础。"},{"type":"essay","tag":"简答题","source":"依据八年级上册“合理利用网络”编写","kind":"简答题","material":"","stem":"网络是一把双刃剑，请简述网络对我们的影响，并说明怎样合理利用网络。（6分）","points":[{"text":"积极：促进人们交流互动、获取信息，推动经济发展，助力民主政治，丰富精神文化生活","score":2},{"text":"消极：网络信息良莠不齐，可能沉迷网络、泄露个人隐私、受网络诈骗","score":2},{"text":"合理利用：理性参与网络生活，增强媒介素养，提高辨别能力，自觉抵制不良信息，遵守法律和道德","score":2}],"score":6,"sample":"","explanation":"双刃剑类题目要“一分为二”，再写做法。"}]}]},{"id":"xiaosimen-daode-4","group":"道德与法治","subject":"道德与法治","term":"八年级下册","title":"道德与法治 · 八年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建中考真题","stem":"暑假期间，小闽一家外出旅游。出发前，妈妈到派出所更换即将过期的身份证；行车途中，爸爸主动礼让行人；景区内，小闽劝阻弟弟不要乱涂乱刻。据此，下列判断正确的是（ ）①妈妈能够自觉地履行义务 ②爸爸维护了他人的人格尊严 ③小闽具有较强的法律意识 ④弟弟的行为受到法律的保护","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"A","explanation":"妈妈更换身份证是自觉履行公民义务；小闽劝阻弟弟乱涂乱刻，说明其具有较强的法律意识。爸爸礼让行人维护的是行人的生命安全，而非人格尊严；弟弟乱涂乱刻是不文明、不合法的行为，不受法律保护。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考真题","stem":"近些年，我国把宪法宣传教育作为法治建设的基础性工程来抓，通过多种形式增强人们对宪法的认同感，提高践行宪法精神的自觉性。这说明（ ）。","options":[{"key":"A","text":"宪法是其他法律的立法基础和立法依据"},{"key":"B","text":"宪法规定的内容是国家生活中的具体问题"},{"key":"C","text":"宪法的生命在于实施，宪法的权威也在于实施"},{"key":"D","text":"人民可以通过各种途径和方式，直接管理国家事务"}],"answer":"C","explanation":"把宪法宣传教育作为法治建设的基础性工程来抓，增强人们对宪法的认同感、提高践行宪法精神的自觉性，说明宪法的生命在于实施，宪法的权威也在于实施。建设社会主义法治国家，需要坚持宪法至上，自觉践行宪法精神。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第17题","stem":"平等是人类的崇高理想，是社会发展的永恒主题。下列选项直接体现平等的是（ ）①乘公交车时先下后上 ②在食堂就餐时按需点餐 ③在人行道上设置盲道 ④实行男女职工同工同酬","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"D","explanation":"③设置盲道是为盲人提供平等的出行条件，④同工同酬是男女职工享有平等的劳动报酬权利，都直接体现平等。①先下后上体现的是遵守公共秩序，②按需点餐体现的是勤俭节约，都与平等无直接关系。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年广西中考·道德与法治第8题","stem":"消费者李某通过网络平台在某品牌服装店购买保暖内衣，穿上后出现皮肤过敏，不得不就医治疗。经相关机构鉴定，该保暖内衣存在质量问题。案例中该服装店的行为（ ）","options":[{"key":"A","text":"属于刑事违法行为，应承担刑事责任"},{"key":"B","text":"没有违法，不需要承担任何法律责任"},{"key":"C","text":"属于民事违法行为，应承担民事责任"},{"key":"D","text":"属于一般违法行为，社会危害性严重"}],"answer":"C","explanation":"销售问题商品侵害消费者权益，违反《消费者权益保护法》，属于民事违法行为，应承担赔偿等民事责任。A刑事违法行为需具有严重社会危害性，本案未构成犯罪；B服装店销售问题商品已违法；D一般违法行为社会危害性较轻，“社会危害性严重”是刑事违法行为的特征。"},{"type":"choice","tag":"Claude 精选","source":"2025年重庆中考·道德与法治第3题","stem":"全国人大常委会法工委收到一封公民的备案审查建议，建议直指某地“公民在路边停车未按规定缴纳停车费，将被处以200元罚款”的规定不合法。全国人大常委会法工委经审查认为，这一规定不符合设定和实施行政处罚的法律原则和规定，要求制定机关依法作出修改。从中我们可以感受到（ ）①我国尊重和保障人权 ②人民代表大会是最高国家权力机关 ③该公民具有较强的宪法意识 ④我国加强宪法监督，维护国家法制统一","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"C","explanation":"公民写信提出备案审查建议并获采纳，体现公民宪法意识强（③），国家加强宪法监督、维护法制统一（④），也体现尊重和保障人权（①）；②“人民代表大会是最高国家权力机关”说法不准确，全国人民代表大会才是最高国家权力机关。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽中考·道德与法治第5题","stem":"在某法院青少年法治教育基地，法院不提供庭审内容脚本、不预设审判结果，让同学们沉浸式体验网络信息安全违法案件的模拟审判。此举旨在（ ）①提升青少年的法治素养 ②保障公民权利不受侵犯 ③增强青少年网络安全意识 ④促进司法机关公正司法","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"A","explanation":"模拟审判通过实践参与帮助青少年理解法律知识、提升法治素养（①）；案件主题为网络信息安全，可强化青少年对网络安全重要性的认识（③）。②活动侧重教育而非直接保障权利；④活动对象是青少年，目的不是监督司法机关。"},{"type":"choice","tag":"Claude 精选","source":"2025年上海中考·道德与法治第2题（第2问）","stem":"近年来，党和政府千方百计稳就业，充分保障人民____（单选）（ ）","options":[{"key":"A","text":"劳动权"},{"key":"B","text":"受教育权"},{"key":"C","text":"文化权利"},{"key":"D","text":"物质帮助权"}],"answer":"A","explanation":"党和政府千方百计稳就业，体现的是保障人民的劳动权。B、C、D都是公民依法享有的权利，但题干体现的是劳动权。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津中考·道德与法治第19题","stem":"平等是人类的崇高理想，是社会发展的永恒主题。下列做法体现践行平等的是（ ）","options":[{"key":"A","text":"看到他人身处险境主动报警"},{"key":"B","text":"指导社区老人使用智能手机"},{"key":"C","text":"公司规定只招重点高校毕业生"},{"key":"D","text":"在公共交通工具上设置爱心专座"}],"answer":"D","explanation":"设置爱心专座是对弱势群体的合理差别对待，保障其平等享有公共资源，体现平等。A主动报警救助他人属于见义勇为，体现的是关爱而非直接践行平等；B指导老人使用手机是帮助弱势群体适应社会，但更偏向于友善互助，未直接体现制度性平等；C公司仅招重点高校学生属于就业歧视，违背平等原则。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2024年北京中考·道德与法治第12题","stem":"2024年，我国一批法律正式施行。爱国主义教育法以法治方式推动和保障新时代爱国主义教育；粮食安全保障法全方位夯实粮食安全根基；修订后的海洋环境保护法让人民群众更好享受碧海蓝天……这体现（ ）","options":[{"key":"A","text":"科学立法是捍卫社会公平正义的最后一道防线"},{"key":"B","text":"每个公民都享有同样的权利、履行同样的义务"},{"key":"C","text":"厉行法治首先需要加强法治宣传"},{"key":"D","text":"我国社会主义法治国家建设深入推进"}],"answer":"D","explanation":"公正司法是捍卫社会公平正义的最后一道防线，A表述错误；每个公民在法律面前都是平等的，这种平等并不意味着在所有具体权利和义务上都是完全一致的，B表述错误；材料没有强调厉行法治和法治宣传，C排除；爱国主义教育法、粮食安全保障法、海洋环境保护法等法律的制定和实施，体现我国社会主义法治国家建设深入推进，D符合题意。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2024年江西省中考·道德与法治第10题","stem":"孔某在一餐饮公司扫码点餐时，被该公司强制获取个人信息且无法自行删除。孔某将该公司告上法庭，法院判决该公司删除孔某个人信息，向孔某书面赔礼道歉并赔偿相关费用。对此分析正确的是（ ）","options":[{"key":"A","text":"孔某的名誉权受到了不法侵害"},{"key":"B","text":"餐饮公司的行为是行政违法行为"},{"key":"C","text":"孔某依法维护了自身合法权益"},{"key":"D","text":"人民法院依法独立行使了检察权"}],"answer":"C","explanation":"餐饮公司强制获取个人信息侵犯了孔某的隐私权，孔某诉诸法院、获得赔偿，是依法维护自身合法权益，C正确；A错在是隐私权不是名誉权；B错在这是民事侵权，不是行政违法；D错在人民法院行使的是审判权，检察权属于人民检察院。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京大兴区初三二模·道德与法治第16题","stem":"2024年，北京市在“宪法宣传周”期间，开展了5000余场各类宪法主题宣传活动，包括在全新的北京市宪法宣传教育基地开展系列活动。这一举措（ ）","options":[{"key":"A","text":"能够确保全体北京市民都能遵守宪法"},{"key":"B","text":"说明宪法只与国家机关工作人员有关"},{"key":"C","text":"有利于增强市民的宪法意识，弘扬宪法精神"},{"key":"D","text":"表明宪法宣传活动是提升公民法治观念的唯一途径"}],"answer":"C","explanation":"开展宪法宣传周活动，有利于增强市民的宪法意识，弘扬宪法精神。A'确保'说法绝对；B宪法与全体公民有关；D'唯一途径'说法绝对。"},{"type":"choice","tag":"Claude 精选","source":"2025年江西省中考·道德与法治第11题","stem":"江警官在学校“法治宣讲课”上引用了以下案例。社会青年张某经常拦截学生，搜身抢夺财物。人民检察院以张某涉嫌抢劫罪提起公诉。经人民法院审理，张某被判处有期徒刑并处罚金。对该案例解读正确的是（ ）①张某侵犯了被抢劫学生的人身自由 ②法律通过制裁违法犯罪，维护社会秩序 ③人民检察院行使监察权，追诉犯罪 ④有期徒刑属于刑罚，罚金属于行政处罚","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"A","explanation":"①张某拦截学生并搜身抢夺财物，直接限制了学生的人身自由；②法律对张某的制裁体现了其维护社会秩序的作用。③人民检察院行使的是检察权（公诉权），监察权属于监察委员会；④有期徒刑和罚金均属于刑罚种类，而非行政处罚。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京顺义区初三（上）期末·道德与法治第13题","stem":"某市民拨打市民服务热线，反映小区周边的广场舞噪音严重影响生活。市民服务中心接诉即办，第一时间交城管部门核实处理。城管执法人员迅速到达现场，向跳广场舞的群众宣传相关法律法规，要求降低音量。对此，下列点评正确的是（ ）①拨打服务热线的市民依照法定程序，正确行使权利 ②广场娱乐群众坚持权利和义务相统一 ③市民服务中心畅通反映渠道，回应群众诉求 ④城管执法人员依法行使职权，公正司法","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"A","explanation":"①拨打服务热线的市民依照法定程序，正确行使权利；③市民服务中心畅通反映渠道，回应群众诉求。②广场娱乐群众噪音扰民，没有坚持权利和义务相统一；④城管执法人员依法行使职权，但'公正司法'属于司法机关，城管执法是行政执法，不是司法。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京顺义区初三（上）期末·道德与法治第18题","stem":"某村探索推行“说、议、办、评”四个环节融于一体的“村民说事制度”。“说”：想说都能说，“说”出痛点、难点；“议”：遇事要商议，“议”出和谐、稳定；“办”：有事马上办，“办”到群众心里；“评”：事事大家评，“评”出优良好坏。对此，下列认识正确的是（ ）","options":[{"key":"A","text":"“说”反映了公民权利的不断扩大"},{"key":"B","text":"“议”体现了众人的事情众人商量"},{"key":"C","text":"“办”能够提高政府公信力"},{"key":"D","text":"“评”有利于公民直接管理国家事务"}],"answer":"B","explanation":"'议'（遇事要商议）体现了众人的事情众人商量。A'说'反映的是公民表达诉求的渠道畅通，不是权利的不断扩大；C'办'是村民自治组织为群众办事，与政府公信力无关；D'评'是村民评议村务，不是直接管理国家事务。"},{"type":"choice","tag":"Claude 精选","source":"2024年北京平谷初三二模·道德与法治第3题","stem":"某司机一次违章停车，被交警口头警告后立即驶离。事后他获知，根据新修订的《中华人民共和国行政处罚法》，初次违法且危害后果轻微并及时改正的，可以不予行政处罚。对此，认识正确的是（ ）","options":[{"key":"A","text":"轻微违法无需承担法律责任"},{"key":"B","text":"违章停车具有严重社会危害性，应受到刑罚处罚"},{"key":"C","text":"要远离违法犯罪，做到法无授权不可为"},{"key":"D","text":"要学习法律知识，增强法律意识，做到尊法守法"}],"answer":"D","explanation":"某司机一次违章停车，被交警口头警告后立即驶离，启示我们要学习法律知识，增强法律意识，做到尊法守法。A轻微违法也需承担法律责任；B只有触犯刑法的、具有严重社会危害性、受到刑罚处罚的才是犯罪行为；C题干未涉及法无授权不可为。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-constitution","stem":"其他法律都要以宪法为依据制定，不得同宪法相抵触。这表明","options":[{"key":"A","text":"宪法和其他法律没有关系"},{"key":"B","text":"其他法律的效力高于宪法"},{"key":"C","text":"宪法只规定公民的义务"},{"key":"D","text":"宪法具有最高的法律效力"}],"answer":"D","explanation":"宪法是国家的根本法，具有最高法律效力；其他法律在具体领域落实宪法原则。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-rights-duties","stem":"根据我国宪法，下列既是公民的权利、又是公民的义务的是","options":[{"key":"A","text":"受教育"},{"key":"B","text":"选举权"},{"key":"C","text":"言论自由"},{"key":"D","text":"宗教信仰自由"}],"answer":"A","explanation":"按宪法规定，劳动、受教育既是权利也是义务。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-system-and-organ","stem":"我国的根本政治制度是","options":[{"key":"A","text":"基层群众自治制度"},{"key":"B","text":"人民代表大会制度"},{"key":"C","text":"人民代表大会"},{"key":"D","text":"民族区域自治制度"}],"answer":"B","explanation":"见到“制度”问制度安排，见到“机关”问机构：人民代表大会是国家权力机关，人民代表大会制度是根本政治制度。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-organs-and-functions","stem":"我国的法律监督机关是","options":[{"key":"A","text":"国务院"},{"key":"B","text":"全国人大常委会"},{"key":"C","text":"人民检察院"},{"key":"D","text":"人民法院"}],"answer":"C","explanation":"人民法院行使审判权，人民检察院是国家的法律监督机关。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-market-and-government","stem":"某市简化审批、加强市场监管，同时企业根据市场需求自主决定生产什么。这体现了","options":[{"key":"A","text":"政府决定所有企业生产什么"},{"key":"B","text":"市场经济不需要任何监管"},{"key":"C","text":"政府与企业的作用相同"},{"key":"D","text":"市场在资源配置中起决定性作用，同时更好发挥政府作用"}],"answer":"D","explanation":"市场通过价格、供求和竞争配置资源；政府依法宏观调控、监管和提供公共服务。两个主体的作用要分别写清。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"____是国家的根本法，具有最高的法律效力；每年____月4日是国家宪法日。","answer":["宪法","12"],"explanation":"宪法的核心价值追求是规范国家权力运行，保障公民权利。"},{"type":"blank","stem":"我国的国家性质是工人阶级领导的、以工农联盟为基础的____专政的社会主义国家。","answer":["人民民主"],"explanation":"社会主义制度是我国的根本制度；中国共产党领导是中国特色社会主义最本质的特征。"},{"type":"blank","stem":"我国的根本政治制度是____制度。","answer":["人民代表大会"],"explanation":"全国人民代表大会是最高国家权力机关。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据八年级下册“坚持宪法至上”编写","kind":"简答题","material":"","stem":"为什么说宪法是国家的根本法？（6分）","points":[{"text":"内容上：宪法规定国家生活中最根本、最重要的问题","score":2},{"text":"效力上：宪法具有最高的法律效力，是其他法律的立法基础和依据","score":2},{"text":"制定和修改程序上：比普通法律更为严格（修改须全国人大以全体代表三分之二以上多数通过）","score":2}],"score":6,"sample":"","explanation":"记口诀：“内容最根本、效力最高、程序最严”。"},{"type":"essay","tag":"简答题","source":"依据八年级下册“加强宪法监督”编写","kind":"简答题","material":"","stem":"我们应怎样维护宪法权威？（6分）","points":[{"text":"国家：加强宪法实施和监督，推进合宪性审查","score":2},{"text":"公民：增强宪法意识，做宪法的忠实崇尚者、自觉遵守者、坚定捍卫者","score":2},{"text":"青少年：学习宪法知识，参加宪法宣传活动，同违反宪法的行为作斗争","score":2}],"score":6,"sample":"","explanation":"宪法的生命在于实施，宪法的权威也在于实施。每年12月4日为国家宪法日。"}]}]},{"id":"xiaosimen-daode-5","group":"道德与法治","subject":"道德与法治","term":"九年级上册","title":"道德与法治 · 九年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第1题","stem":"2025年3月12日，中央党的建设工作领导小组召开会议。会议指出，党中央决定，自2025年全国两会后至7月在全党开展深入贯彻中央八项规定精神学习教育。下列正确反映此次学习教育发挥作用过程的是（ ）①进一步提升党员干部的纪律作风 ②对党员干部思想理论进行再教育 ③为推进中国式现代化提供有力保障","options":[{"key":"A","text":"①—③—②"},{"key":"B","text":"②—①—③"},{"key":"C","text":"③—①—②"},{"key":"D","text":"③—②—①"}],"answer":"B","explanation":"学习教育首先是对党员干部思想理论进行再教育（②），从而进一步提升党员干部的纪律作风（①），最终为推进中国式现代化提供有力保障（③），过程是②—①—③。A、D把结果放在了前面，C把最终保障当成了起点，都不符合“学习教育发挥作用”的逻辑顺序。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第16题","stem":"某市不定期发布公告，号召市民走出家门清理绿地、抚育林木，或者在网上捐资认养树木，以线上线下相结合的形式履行植树义务。此举有利于（ ）①让参与造林绿化成为人们的自觉行动 ②发挥道德的强制作用，改变自然环境 ③发挥互联网的优势，提升市民生态意识 ④全面推进政务公开，保障公民的决定权","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"号召市民线上线下参与植树，有利于让参与造林绿化成为人们的自觉行动（①），网上捐资认养树木发挥了互联网的优势、提升市民生态意识（③）。②错误，道德没有强制作用，强制作用属于法律；④公民没有“决定权”，政务公开保障的是公民的知情权、参与权等，材料也与政务公开无关。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·道德与法治第22题","stem":"某市积极探索发展全过程人民民主有效路径，把好事实事做到群众的心坎上。下列关于该路径各环节的排序，正确的是（ ）①政府履行职责，组织实施项目 ②政府倾听民声，公开征集项目 ③人大调研视察，监督检查项目 ④人大代表票决，确定实施项目","options":[{"key":"A","text":"①—②—③—④"},{"key":"B","text":"②—③—④—①"},{"key":"C","text":"②—④—①—③"},{"key":"D","text":"③—②—①—④"}],"answer":"C","explanation":"全过程人民民主的民生实事路径是：先由政府倾听民声、公开征集项目（②），再由人大代表票决、确定实施项目（④），然后政府履行职责、组织实施项目（①），最后人大调研视察、监督检查项目（③），即②—④—①—③。A把实施放在征集之前，B把监督放在票决之前，D把监督放在最前面，都不符合逻辑顺序。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第1题","stem":"2026年2月，中共中央办公厅印发的《关于在全党开展树立和践行正确政绩观学习教育的通知》指出，经党中央同意，在全党开展树立和践行正确政绩观学习教育。这一要求发挥作用的过程，正确的是（ ）①夯实党的执政根基 ②全面开展学习教育 ③进一步树立和践行正确政绩观","options":[{"key":"A","text":"①—②—③"},{"key":"B","text":"①—③—②"},{"key":"C","text":"②—③—①"},{"key":"D","text":"③—②—①"}],"answer":"C","explanation":"学习教育先要全面开展（②），通过学习教育进一步树立和践行正确政绩观（③），最终夯实党的执政根基（①），过程是②—③—①。A、B把最终结果“夯实执政根基”放在了前面，D把中间环节放在了最前面，都不符合逻辑顺序。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第19题","stem":"某社区邀请青少年参与老旧小区改造意见的征集。这群青少年走访居民、测算成本、模拟听证，最终形成的建议被社区纳入改造方案。这群青少年（ ）①积极参与民主生活 ②完善基层群众自治制度 ③勇于承担社会责任 ④自觉履行公民法定义务","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"青少年参与社区改造意见征集、走访调研、模拟听证，是积极参与民主生活（①），也是勇于承担社会责任的表现（③）。②完善基层群众自治制度是制度层面的事，青少年的参与不能直接完善制度；④参与意见征集是公民行使参与权，不是履行法定义务。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第22题","stem":"1931年，识字不多的井冈山农民贺页朵在红布上写下加入中国共产党的誓词：“牺牲个人，言首泌蜜（严守秘密），阶级斗争，努力革命，伏（服）从党其（纪），永不叛党。”即使身陷白色恐怖，他始终珍藏这份带有错别字的入党誓词。直至临终，还叮嘱子女要牢记入党誓词上的话。这份入党誓词（ ）①凝结了全体人民共同的价值追求 ②蕴含了百年大党风华正茂的精神密码 ③说明了中华民族精神在不同时期表现相同 ④诠释了共产党员献身党的事业的庄严承诺","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"D","explanation":"贺页朵用生命珍藏入党誓词、至死不渝，蕴含了百年大党风华正茂的精神密码（②），诠释了共产党员献身党的事业的庄严承诺（④）。①入党誓词是共产党员的誓言，不是“全体人民共同的价值追求”；③中华民族精神在不同时期有不同的表现，不是“表现相同”。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年广西中考·道德与法治第4题","stem":"中华文明历尽沧桑而薪火相传，是世界上唯一绵延不断且以国家形态发展至今的伟大文明，具有突出的连续性。下列选项能突出体现这一特性的有（ ）①敦煌文化是中华文明同各种文明交流融汇的结果 ②爱国主义自古以来就流淌在中华民族的血脉之中 ③楚辞汉赋、唐诗宋词、明清小说等作品代代相传 ④四大发明是中国古代最具代表性的科学技术成就","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"C","explanation":"爱国主义自古延续至今（②）和不同朝代文学作品代代相传（③）直接体现文明在时间上的延续性；①敦煌文化侧重包容性而非延续；④四大发明强调科技成就的代表性，未直接体现延续过程。"},{"type":"choice","tag":"Claude 精选","source":"2025年广西中考·道德与法治第14题","stem":"2025年5月20日起，我国第一部专门关于民营经济发展的基础性法律《中华人民共和国民营经济促进法》施行。该法包括公平竞争、投资融资促进、科技创新、权益保护等多个专章。对于该法施行带来的积极影响，传导正确的是（ ）","options":[{"key":"A","text":"完善科技创新制度→降低民营经济组织市场经营风险→拓展民营经济的发展空间"},{"key":"B","text":"完善投资融资制度→支持引导民营经济投资重点领域→巩固民营经济的主体地位"},{"key":"C","text":"公平参与市场竞争→允许民营经济组织进入所有领域→促进民营经济的发展壮大"},{"key":"D","text":"依法保护合法权益→为民营经济营造更好的法治环境→提振民营经济的发展信心"}],"answer":"D","explanation":"依法保护合法权益能直接优化法治环境，增强民营经济发展信心，逻辑链条合理。A科技创新与降低市场经营风险无直接因果关系；B公有制经济是主体，“巩固民营经济的主体地位”错误；C部分领域（如国家安全等）仍有限制，“进入所有领域”错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年重庆中考·道德与法治第7题","stem":"某市积极打造乡村振兴示范片区，推动和美乡村建设。A示范片区覆盖两个镇70多个村，串点成线、连线成片，促进协同发展。该片区成立规划委员会，统筹挖掘当地文化元素，规划出一条途经两个镇、串联20多个景点的骑行路。如今，片区内彩色步道穿村而过，自然景色与民宿等新业态完美融合，吸引了不少游客观光游玩。该示范片区（ ）①主导构建了该市治理新格局 ②对当地资源合理开发和利用 ③转变发展方式建设和美乡村 ④通过协同发展助推共同富裕","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"D","explanation":"挖掘文化元素、串联景点、发展民宿新业态，是对当地资源的合理开发利用（②），转变发展方式建设和美乡村（③），协同发展助推共同富裕（④）；①“主导构建了该市治理新格局”夸大其词，材料只体现一个示范片区的建设。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽中考·道德与法治第10题","stem":"一张宣纸，千年技艺载文韵。宣纸传统工艺有100多道工序，代代相传的匠心让传统技艺赓续绵延，生生不息。宣纸制作技艺是第一批国家级非物质文化遗产名录中的代表性项目，它不仅仅是门技艺，更是国家名片。这蕴涵着（ ）①工匠精神 ②时代精神 ③文化传承 ④文化自信","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"C","explanation":"“代代相传的匠心”体现精益求精的工匠精神（①）；宣纸技艺代代相传，说明文化传承（③）；被称为“国家名片”，体现对传统文化的自豪与自信（④）。②时代精神通常指改革创新等，题干未直接体现。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津市中考·道德与法治第17题","stem":"2024年，民营企业进出口额243329亿元，比上年增长8.8%，占我国进出口总额比重为55.5%。这表明民营经济（ ）","options":[{"key":"A","text":"在资源配置中起决定性作用"},{"key":"B","text":"是我国国民经济的主导力量"},{"key":"C","text":"是我国公有制经济的组成部分"},{"key":"D","text":"是社会主义市场经济的重要组成部分"}],"answer":"D","explanation":"在资源配置中起决定性作用的是市场；国有经济是国民经济的主导力量；民营经济属于非公有制经济，是社会主义市场经济的重要组成部分，D正确。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津市中考·道德与法治第22题","stem":"《粤港澳大湾区发展规划纲要》发布6年来，粤港澳大湾区“1小时生活圈”逐步从发展愿景成为生活现实。这得益于（ ）","options":[{"key":"A","text":"国家支持民族地区发展"},{"key":"B","text":"善用“一国两制”优势"},{"key":"C","text":"国家实施兴边富民行动"},{"key":"D","text":"民族地区经济高速发展"}],"answer":"B","explanation":"粤港澳大湾区涉及内地与港澳的深度合作，其发展需要依托“一国两制”的制度优势整合资源，B正确；大湾区并非民族地区，A、D不符；兴边富民行动针对边疆地区，C不符。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京西城区初三二模·道德与法治第20题","stem":"“云上西城，遗脉相承——西城非遗万象馆”将西城区非遗进行数字化并整体呈现于云端，通过超高清视频、VR等技术，展示西城区知名文化古迹、非遗项目、非遗传承人等，让用户随时随地感受非遗魅力，领略西城深厚的文化底蕴。这体现了（ ）①彰显中华文化自信，展现独特魅力 ②赓续红色基因，弘扬爱国主义精神 ③文化在交流互鉴中发展，从不同文明中寻求智慧 ④推动中华优秀传统文化创造性转化、创新性发展","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"非遗数字化展示彰显了中华文化自信、展现独特魅力，①正确；推动中华优秀传统文化创造性转化、创新性发展，④正确；②③与材料主旨不符。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年北京大兴区初三二模·道德与法治第17题","stem":"2025年4月30日，十四届全国人大常委会第十五次会议表决通过民营经济促进法，自2025年5月20日起施行。这标志着我国民营经济发展迎来重大制度利好。下列关于民营经济的表述正确的是（ ）","options":[{"key":"A","text":"民营经济的生产资料属于集体所有，是国民经济的主导力量"},{"key":"B","text":"民营经济主要分布在关系国家安全、国民经济命脉的重要行业"},{"key":"C","text":"民营经济是社会主义市场经济的重要组成部分"},{"key":"D","text":"民营经济是我国经济社会发展最为重要的基础"}],"answer":"C","explanation":"民营经济是社会主义市场经济的重要组成部分。A错误，民营经济的生产资料属于私人所有，国有经济是国民经济的主导力量；B错误，关系国家安全、国民经济命脉的重要行业主要由国有经济主导；D错误，公有制经济是我国经济社会发展的重要基础。"},{"type":"choice","tag":"Claude 精选","source":"2025年江西省中考·道德与法治第1题","stem":"2024年7月15日至18日，中国共产党第二十届中央委员会第三次全体会议在北京举行。这次会议审议通过了（ ）","options":[{"key":"A","text":"《乡村全面振兴规划（2024—2027年）》"},{"key":"B","text":"《教育强国建设规划纲要（2024—2035年）》"},{"key":"C","text":"《国家空间科学中长期发展规划（2024—2050年）》"},{"key":"D","text":"《中共中央关于进一步全面深化改革、推进中国式现代化的决定》"}],"answer":"D","explanation":"2024年7月，党的二十届三中全会审议通过《中共中央关于进一步全面深化改革、推进中国式现代化的决定》。A、B、C 三项均非三中全会审议通过的文件。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-reform-opening","stem":"某地推行“一网通办”减少办事环节，某港口新开多条国际航线。二者分别体现了","options":[{"key":"A","text":"改革激发发展活力；开放拓展发展空间"},{"key":"B","text":"都体现对外开放"},{"key":"C","text":"都体现改革"},{"key":"D","text":"都与改革开放无关"}],"answer":"A","explanation":"调整制度机制、改进办事流程体现改革；跨境贸易、国际航线等体现开放。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-common-prosperity","stem":"关于共同富裕，下列说法正确的是","options":[{"key":"A","text":"只是少数人先富起来"},{"key":"B","text":"是全体人民的共同富裕，要分阶段逐步推进"},{"key":"C","text":"是所有人同时、同步、同等富裕"},{"key":"D","text":"我国已经完全消除了收入差距"}],"answer":"B","explanation":"共同富裕面向全体人民，是分阶段推进的过程；把“有利于缩小差距”答成“已经消除差距”是夸大。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-innovation","stem":"某快递企业引入智能分拣系统，包裹分拣效率大幅提高。这说明","options":[{"key":"A","text":"技术进步与人们生活无关"},{"key":"B","text":"创新只是科学家的事"},{"key":"C","text":"创新能提高生产效率"},{"key":"D","text":"创新会立即全面取代所有传统产业"}],"answer":"C","explanation":"分析创新要看改进了什么、怎样应用、改善了谁的生产生活；写成“全面取代既有产业”结论过大。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-people-democracy","stem":"某社区就加装电梯征求居民意见，部分建议被采纳。这体现了","options":[{"key":"A","text":"居民可以随意决定社区所有事务"},{"key":"B","text":"民主就是少数服从个别人"},{"key":"C","text":"意见征集只是走形式"},{"key":"D","text":"公民有序参与民主生活"}],"answer":"D","explanation":"建议被采纳能看出公众有序参与；具体由谁决定，要看法定主体和程序。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-ecological-development","stem":"某化工企业改进生产工艺，从源头减少废气排放。这体现了","options":[{"key":"A","text":"绿色发展，从源头减量"},{"key":"B","text":"先污染后治理"},{"key":"C","text":"保护环境就要停止发展"},{"key":"D","text":"环境问题只能事后治理"}],"answer":"A","explanation":"污染处理是事后治理；改进工艺减少排放是源头减量，体现绿色发展。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"____是引领发展的第一动力；科技是第一生产力，人才是第一资源。","answer":["创新"],"explanation":"实施科教兴国战略、人才强国战略、创新驱动发展战略。"},{"type":"blank","stem":"我国处理民族关系的基本原则是民族平等、民族团结和各民族____。","answer":["共同繁荣"],"explanation":"我国实行民族区域自治制度，是基本政治制度之一。"},{"type":"blank","stem":"社会主义核心价值观中，国家层面的价值目标是：富强、民主、文明、____。","answer":["和谐"],"explanation":"社会层面：自由、平等、公正、法治；个人层面：爱国、敬业、诚信、友善。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"时事点评","source":"2025年福建中考·道德与法治第27题（参考答案按教材整理）","kind":"时事点评","material":"时事一：2024年12月，国家医保局公布，医保码上线5年来，全国医保码用户已超12亿人，接入93万家定点医药机构。医保码的普及让医保事项“指尖”可办、“无卡就医”成为现实，极大方便了群众就医。\n时事二：2025年3月，住房城乡建设部发布的国家标准《住宅项目规范》，以安全、舒适、绿色、智慧为目标，规定新建住宅建筑层高不低于3米，4层及以上住宅设置电梯等，以国家标准为“好房子”建设划定底线。","stem":"运用时事知识，对上述两则时事共同体现的主旨作出点评。（6分）","points":[{"text":"主旨：保障和改善民生，增进民生福祉","score":2},{"text":"体现党和政府坚持以人民为中心的发展思想，全心全意为人民服务","score":2},{"text":"有利于满足人民日益增长的美好生活需要，增强人民群众的获得感、幸福感、安全感","score":2}],"score":6,"sample":"","explanation":"“医保”“住房”都是民生领域，“方便群众”“好房子”指向人民美好生活。"},{"type":"essay","tag":"材料分析题","source":"2025年福建中考·道德与法治第28题(2)（参考答案按教材整理）","kind":"材料分析题","material":"【跨越时空的家书】“我虽回国，却恐十年不能还家，老母赡养，托于长兄，我将全力贡献革命。”——摘自抗日将领左权家书\n“我是妈妈，也是军人，那一刻妈妈是要出征上战场，临危忘身、受命忘家，这是一个军人的职责。”——摘自航天英雄刘洋家书","stem":"结合两封家书，运用所学知识，简析蕴含在其中的“变”与“不变”。（4分）","points":[{"text":"变：时代背景、写信人身份和家书内容（革命战争 / 航天事业）发生了变化","score":2},{"text":"不变：爱家更爱国的家国情怀、责任担当和奉献精神始终不变（把个人命运与国家命运紧密相连）","score":2}],"score":4,"sample":"","explanation":"一封写于抗战年代，一封写于新时代航天任务；共同的是“舍小家为大家”。"}]}]},{"id":"xiaosimen-daode-6","group":"道德与法治","subject":"道德与法治","term":"九年级下册","title":"道德与法治 · 九年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年北京中考·道德与法治第15题","stem":"2024年6月7日，第78届联合国大会以协商一致的方式通过由中国提出的决议，宣布每年6月10日为文明对话国际日，以促进不同文明间的平等对话和相互尊重、加强全球团结。文明对话有助于（ ）①尊重文化多样性，美美与共 ②全球治理成为当今时代的主题 ③增进理解信任，消除文化差异 ④文明交流互鉴，促进共同发展","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"文明对话有助于尊重文化多样性，美美与共；文明交流互鉴，促进共同发展，①④符合题意。当今时代的主题是和平与发展，②表述错误，排除；文化是多样的，应尊重文化差异，“消除文化差异”的表述错误，③排除。故本题选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东中考真题","stem":"第九届全国道德模范何镜堂院士，潜心研究建筑设计几十载，打破了国家标志建筑设计由外国建筑师垄断的局面。他说：“学无止境，只要我还能动，我就会寻找各种机会去实地考察和研究建筑，这既是我的工作，也是我的生活。”以何镜堂院士为榜样，我们青少年要努力（ ）①发掘潜能，特立独行扬个性 ②敬业奉献，学有专攻尽精微 ③否定传统，开拓行业新领域 ④勤勉不倦，不畏艰辛干实事","options":[{"key":"A","text":"①③"},{"key":"B","text":"②③"},{"key":"C","text":"①④"},{"key":"D","text":"②④"}],"answer":"D","explanation":"何镜堂潜心研究建筑设计、打破外国垄断，体现“敬业奉献，学有专攻”；坚持实地考察研究，体现“勤勉不倦，不畏艰辛干实事”。“特立独行扬个性”“否定传统”表述绝对，不符合题意。"},{"type":"choice","tag":"Claude 精选","source":"2024年湖北武汉中考真题","stem":"习近平寄语新时代青年“奋力书写为中国式现代化挺膺担当的青春篇章”。为响应号召，九年级（2）班以“中国式现代化·青年担当”为主题开展项目式学习。同学们提交的下列作品中，设计合理的是（ ）①展示“国际湿地城市青年志愿者风采”图片，配文“坚持人与自然和谐共生” ②播报“武汉大学南北极科考队获五四青年奖章”新闻，配文“冰原磨砺，青春出彩” ③绘制“民族伟大复兴”时间轴，标注“为2035年全面建成社会主义现代化强国而奋斗” ④剪辑“嫦娥六号月背采样”视频，标注“建成世界科技强国，向第一个百年奋斗目标奋进”","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"A","explanation":"①青年志愿者参与环境保护，②青年大学生为科技事业作贡献，都符合青年担当的主题。③错误，到2035年是基本实现社会主义现代化，全面建成社会主义现代化强国要到本世纪中叶；④错误，我国已实现第一个百年奋斗目标，建成世界科技强国仍任重道远。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东中考真题","stem":"随着乡村文旅产业的蓬勃发展，李某大学毕业后选择回到家乡做一名民宿管家。她凭借专业优势向游客提供旅游咨询、活动策划等服务，不仅为游客带来美好体验，而且找到了自己的奋斗坐标。这启示我们进行职业选择时要（ ）。","options":[{"key":"A","text":"果断放弃传统的职业岗位"},{"key":"B","text":"优先考虑自己的兴趣爱好"},{"key":"C","text":"兼顾个人特长与时代需要"},{"key":"D","text":"组织开展相关的职业培训"}],"answer":"C","explanation":"李某结合自身专业与乡村文旅发展，体现了职业选择中个人特长与时代需要的兼顾。传统职业依然有重要作用，“果断放弃”表述绝对化。"},{"type":"choice","tag":"Claude 精选","source":"2024年江苏苏州中考真题","stem":"2023年是共建“一带一路”倡议提出10周年。10年来，共建“一带一路”国家间人文交往合作机制日益完善，一出剧目、一部电影、一本好书，常常就能让不同文化背景的人收获情感共振和心灵互通。由此可见（ ）。","options":[{"key":"A","text":"文化多样性，共享多样文化"},{"key":"B","text":"世界多极化，各国相互制约"},{"key":"C","text":"经济全球化，各国相互依赖"},{"key":"D","text":"同住地球村，消除文化差异"}],"answer":"A","explanation":"共建“一带一路”国家间通过剧目、电影、图书等文化形式，让不同文化背景的人收获情感共振和心灵互通，体现了文化的多样性，不同国家和民族的文化在交流中相互分享和欣赏。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年甘肃兰州中考真题（夜雨聆风《专题23 走向未来的少年（解析版）》汇编内第18题；原题为表格题，此处转写为文字叙述，知识点、选项与答案未改）","stem":"某班召开“做更好的自己”主题班会，对同学们的发言，下列微点评不正确的是（ ）发言与微点评：A．“我脸上起了青春痘，很烦恼”——坦然接受自己的生理变化；B．“面临期中考试，我很焦虑”——理性看待考试，学会调节情绪，缓解压力；C．“我的好朋友期末考试成绩超过了我，我心里有些不舒服，不太想理她了。”——竞争并不必然伤害友谊，关键是我们对待竞争的态度；D．“我在数学课上开小差被老师批评了，好难过！”——培养批判精神，避免与老师交流沟通。","options":[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"D"}],"answer":"D","explanation":"A青春痘是青春期正常生理现象，应坦然接受；B考试焦虑是正常心理现象，应调节情绪、缓解压力；C竞争并不必然伤害友谊，关键是对待竞争的态度。D“避免与老师交流”错误：上课开小差被批评，应反思错误、积极与老师沟通、及时改正；这与培养批判精神无关。本题为逆向选择，问的是不正确的微点评，故选D。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·道德与法治第24题","stem":"截至2024年1月底，我国与29个国家和地区签署了22个自由贸易协定，自贸“朋友圈”不断扩大。签署自由贸易协定（ ）","options":[{"key":"A","text":"顺应了经济全球化的趋势"},{"key":"B","text":"推动了国际关系民主化进程"},{"key":"C","text":"构建了国际经济竞争新格局"},{"key":"D","text":"体现了世界各国共享发展成果"}],"answer":"A","explanation":"我国与越来越多国家和地区签署自由贸易协定、自贸“朋友圈”不断扩大，是顺应经济全球化趋势、扩大对外开放的表现。B国际关系民主化与自贸协定无直接关系；C“构建了国际经济竞争新格局”说法夸大；D世界各国共享发展成果是愿景，签署协定本身不等于已经实现共享。故选A。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·道德与法治第25题","stem":"我国于2026年5月起对53个非洲建交国全面实施零关税举措，成为全球首个对非洲建交国实施单方面、全覆盖零关税的主要经济体。此举（ ）①体现国际关系的民主化 ②提升非洲国家的合作主导权 ③增强非洲经济发展的动能 ④彰显中国负责任的大国形象","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"D","explanation":"对非洲建交国全面实施零关税，有利于非洲产品进入中国市场，增强非洲经济发展的动能（③），彰显中国负责任的大国形象（④）。①零关税是经贸举措，不直接体现国际关系的民主化；②“提升非洲国家的合作主导权”无依据，零关税是中方单方面给予的优惠。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年重庆中考·道德与法治第10题","stem":"2025年5月21日，就美国企图全球禁用中国先进计算芯片，中国表示美方措施涉嫌构成对中国企业采取的歧视性限制措施。任何组织和个人执行或协助执行美方措施，将涉嫌违反《中华人民共和国反外国制裁法》等法律法规，须承担相应法律责任。中方敦促美方立即纠正错误做法，遵守国际经贸规则，尊重其他国家科技发展权利。由此可见（ ）①美国的做法不符合当今合作与发展的时代主题 ②美国违背国际经贸规则，是逆经济全球化的行为 ③美国对中国先进计算芯片加严管制，是单边霸凌行径 ④面对美国打压，中国坚决捍卫国家利益，维护国家安全","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"D","explanation":"美国违背国际经贸规则、逆经济全球化（②），加严管制是单边霸凌行径（③），中国坚决捍卫国家利益、维护国家安全（④）。①当今时代的主题是和平与发展，不是“合作与发展”，表述错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年天津中考·道德与法治第24题","stem":"许振超通过自学练就一身绝活，先后9次刷新集装箱装卸世界纪录，创造了“振超效率”。这启示青少年应（ ）①顺应时代变化，学会自主创业 ②提升自身素质，为国奉献争光 ③弘扬劳动精神，实现人生价值 ④学习工匠精神，做好职业规划","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"D","explanation":"许振超通过自学提升素质，为国家创造纪录，体现提升自身素质、为国奉献，②符合题意；他通过劳动实现突破，弘扬劳动精神并创造价值，③符合题意；其事迹体现精益求精的工匠精神，启示青少年学习并做好职业规划，④符合题意。①题干未提及自主创业，许振超是通过提升技能在岗位上取得成就。故本题选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年贵州省贵阳市中考·道德与法治第2题","stem":"传统上，人们谈到国际公共产品，主要指的是涉及全球安全、经济稳定、环境保护等需要国际社会协调与合作的机制和行动，旨在惠及多个国家甚至全球。近年来，一些中国理念和倡议被广泛传播和共享，具备了国际公共产品的属性。这说明（ ）","options":[{"key":"A","text":"世界各国可以照搬中国方案"},{"key":"B","text":"中国已能决定世界发展方向"},{"key":"C","text":"世界各国必须以中国为榜样"},{"key":"D","text":"中国为世界发展贡献了智慧"}],"answer":"D","explanation":"中国理念和倡议被广泛传播和共享，具备了国际公共产品的属性，说明中国为世界发展贡献了智慧，D正确；A中国主张各国根据国情选择发展道路，反对照搬他国模式；B中国是参与者而非决定者，不能决定世界发展方向；C中国尊重各国发展道路的多样性，不要求他国以中国为榜样。故选D。"},{"type":"choice","tag":"Claude 精选","source":"2025年新疆维吾尔自治区中考·道德与法治第7题","stem":"2025年春晚舞台上，陕北民歌《兰花花》与秘鲁民歌《山鹰之歌》让我们共同见证了跨越山海的文化交流，感受到音乐无国界的魅力。文明交流互鉴中，我们应该（ ）","options":[{"key":"A","text":"实现革命文化的创造性转化、创新性发展"},{"key":"B","text":"以开放包容的心态学习借鉴优秀外来文化"},{"key":"C","text":"促进不同文化的相互交融，最终走向统一"},{"key":"D","text":"从不同文明中寻求智慧汲取营养全盘吸收"}],"answer":"B","explanation":"《兰花花》与《山鹰之歌》同台，启示我们要以开放包容的心态学习借鉴优秀外来文化，B正确；A“革命文化”与题意无关；C文化应保持多样性，“走向统一”违背尊重差异的原则；D“全盘吸收”忽视了对不同文化的批判性借鉴。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2025年山西省中考·道德与法治第11题","stem":"1200多年前，藏医药鼻祖宇妥·云丹贡布远赴印度、尼泊尔等国家，收集整理民间医疗土方，汲取国内外医药学精华，完成藏医经典著作《四部医典》。如今，藏医药影响远播尼泊尔、印度、俄罗斯等国家和地区，吸引了许多外国专家学者前来考察。材料表明（ ）","options":[{"key":"A","text":"我国参与全球规则制定"},{"key":"B","text":"经济全球化趋势不可逆转"},{"key":"C","text":"文明在交流互鉴中发展"},{"key":"D","text":"国家间既有合作又有竞争"}],"answer":"C","explanation":"藏医药通过吸收国外精华发展，并影响其他国家，体现了文明在交流互鉴中发展，C正确；A材料未涉及我国参与全球规则制定；B经济全球化强调经济领域的联系，而材料侧重文化、医学的交流；D材料仅体现合作，未提及国家间的竞争。故选C。"},{"type":"choice","tag":"Claude 精选","source":"2025年江西省中考·道德与法治第15题","stem":"从南非的红石光热电站项目，到东南亚的低碳示范区……中国与100多个国家和地区开展绿色能源项目合作，持续赋能绿色发展的世界现代化，被外国学者称为“赋能型大国”。这生动诠释了我国（ ）","options":[{"key":"A","text":"成为维护世界和平的决定性力量"},{"key":"B","text":"展现大国担当，促进共同发展"},{"key":"C","text":"始终坚持合作与共赢的时代主题"},{"key":"D","text":"把握发展契机，避免国际竞争"}],"answer":"B","explanation":"中国与多国开展绿色能源合作，助力全球绿色发展，体现了中国的大国担当和促进共同发展的理念，B正确；A“决定性力量”错误，我国是维护世界和平的坚定力量，且题文未涉及维护世界和平；C和平与发展是时代的主题，“合作与共赢”不是时代主题；D“避免国际竞争”错误，中国积极参与国际合作与竞争。故选B。"},{"type":"choice","tag":"Claude 精选","source":"2024年广东省深圳市中考·道德与法治第22题","stem":"习近平说：“当今世界仍不太平……中国持续为世界贡献中国智慧和中国方案。”中国智慧和中国方案与世界发展的传导路径，正确的是（ ）①中国着眼世界大势——积极参与全球治理——构建人类命运共同体 ②中国经济快速发展——促进世界经济增长——为世界经济发展提供动力 ③中国参与全球规则的制定——构建国际新格局——拓展世界市场 ④中国参与联合国维和行动——促进地区稳定与安全——推动世界和平","options":[{"key":"A","text":"①②"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"③④"}],"answer":"B","explanation":"①中国着眼世界大势，积极参与全球治理，推动构建人类命运共同体，符合世界发展的潮流和各国人民的共同利益，正确；④中国参与联合国维和行动，在维护地区稳定与安全方面发挥了重要作用，有力地推动了世界和平，正确；②我国经济发展已由高速增长转化为高质量发展阶段，错误；③“构建国际新格局”与“拓展世界市场”之间并没有直接的必然联系，错误。故选B。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-globalization","stem":"一款手机在美国设计，零部件来自多个国家，在中国组装，销往全球。这体现了","options":[{"key":"A","text":"经济全球化已经结束"},{"key":"B","text":"生产全球化和贸易全球化"},{"key":"C","text":"只有贸易全球化"},{"key":"D","text":"只有生产全球化"}],"answer":"B","explanation":"设计、制造、组装分布在不同国家体现生产全球化；商品在各国销售体现贸易全球化。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-shared-future","stem":"面对气候变化，各国签署协定、共同减排。这说明","options":[{"key":"A","text":"只有发展中国家需要承担责任"},{"key":"B","text":"气候变化与我们无关"},{"key":"C","text":"全球性问题需要各国平等协商、共同应对"},{"key":"D","text":"某一个国家就能单独解决"}],"answer":"C","explanation":"气候变化等问题跨越国界，各国通过平等协商、分担责任、分享经验来共同应对。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-open-world","stem":"中国举办进口博览会，为各国商品进入中国市场提供机会。这体现了","options":[{"key":"A","text":"中国已主导所有国际合作"},{"key":"B","text":"中国只进口、不出口"},{"key":"C","text":"对外开放会损害本国利益"},{"key":"D","text":"中国扩大开放，促进互利共赢"}],"answer":"D","explanation":"扩大市场机会能带动贸易、实现互利；推断“主导所有国际合作”超出材料。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-cultural-diversity","stem":"对待不同国家的文化习俗，正确的态度是","options":[{"key":"A","text":"了解它的文化背景，尊重差异、交流互鉴"},{"key":"B","text":"和自己习惯不同就是落后"},{"key":"C","text":"全盘照搬外来文化"},{"key":"D","text":"拒绝一切外来文化"}],"answer":"A","explanation":"理解一个习俗要先看它的文化语境；仅凭是否与自己习惯相同来评判，容易把差异误当高下。"},{"type":"choice","tag":"Claude 冲刺","kp":"daode-open-world","stem":"我国企业在海外合作修建铁路，当地交通得到改善，我国企业也开拓了市场。这说明","options":[{"key":"A","text":"对外合作就是单方面援助"},{"key":"B","text":"合作让参与各方都获得发展机会"},{"key":"C","text":"只有我国一方受益"},{"key":"D","text":"只有对方受益"}],"answer":"B","explanation":"判断“互利”要说清参与各方各得到了什么：当地改善交通，我国企业拓展市场。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"当今时代的主题是____与____。","answer":["和平","发展"],"explanation":"和平是发展的前提，发展是和平的基础。"},{"type":"blank","stem":"我国坚持独立自主的和平外交政策，奉行____五项原则。","answer":["和平共处"],"explanation":"和平共处五项原则由周恩来提出，是处理国际关系的基本准则。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据九年级下册“我们共同的世界”编写","kind":"简答题","material":"","stem":"当今时代的主题是什么？为什么说要推动构建人类命运共同体？（6分）","points":[{"text":"和平与发展是当今时代的主题","score":2},{"text":"世界多极化、经济全球化、文化多样化、社会信息化深入发展，各国相互联系、相互依存日益紧密","score":2},{"text":"人类面临许多共同挑战（气候变化、恐怖主义、疫病等），需要携手合作、共同应对","score":2}],"score":6,"sample":"","explanation":"人类命运共同体：建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。"},{"type":"essay","tag":"简答题","source":"依据九年级下册“世界舞台上的中国”编写","kind":"简答题","material":"","stem":"中国在国际舞台上发挥着越来越重要的作用，请举例说明中国的大国担当，并分析原因。（6分）","points":[{"text":"举例：提出共建“一带一路”倡议、积极参与联合国维和行动、提供国际援助等","score":2},{"text":"作为：坚定维护世界和平，促进共同发展，积极参与全球治理","score":2},{"text":"原因：我国综合国力不断增强、国际影响力提升；坚持独立自主的和平外交政策","score":2}],"score":6,"sample":"","explanation":"中国始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者。"}]}]},{"id":"xiaosimen-lishi-1","group":"历史","subject":"历史","term":"七年级上册","title":"历史 · 七年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第2题","stem":"子路问，“闻斯行诸”（听到就去做吗？）孔子说不行；冉有问同样的问题，孔子却说可以。有弟子对此表示疑惑，孔子说，冉有行事畏缩，所以鼓励他大胆去做，子路比较鲁莽，所以让他注意克制。这体现了孔子注重（ ）。","options":[{"key":"A","text":"学而不厌"},{"key":"B","text":"因材施教"},{"key":"C","text":"温故知新"},{"key":"D","text":"不耻下问"}],"answer":"B","explanation":"孔子对同一问题因人而异作答：冉有畏缩就鼓励他大胆去做，子路鲁莽就让他注意克制，体现了因材施教。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第3题","stem":"在秦代，要通过宦学或私学以获得做官吏的资格和业务能力，才能进入仕途，学习的内容包括政事、农业、刑法等诸多方面。这表明秦代（ ）","options":[{"key":"A","text":"实行郡县制度"},{"key":"B","text":"重视官吏素质"},{"key":"C","text":"调整赋税标准"},{"key":"D","text":"统一货币形制"}],"answer":"B","explanation":"秦代要求官吏先经宦学或私学学习政事、农业、刑法等才能做官，说明重视官吏的业务能力与素质。材料未涉及郡县制、赋税与货币。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第3题","stem":"秦汉时期，关东地区、关中平原、南阳盆地、成都平原等地人口密度远超全国平均数。这主要源于（ ）","options":[{"key":"A","text":"农业发展的客观需要"},{"key":"B","text":"治国理念变化"},{"key":"C","text":"北击匈奴的现实诉求"},{"key":"D","text":"经济重心南移"}],"answer":"A","explanation":"关东、关中、南阳、成都平原都是当时农业发达的地区，人口向农业生产条件好的地区集中，源于农业发展的客观需要。秦汉时期经济重心仍在北方，尚未南移；北击匈奴与人口分布无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年云南省中考·历史第2题","stem":"云南晋宁河泊所遗址出土的“益州（郡）太守章”“滇池（县）长印”等两汉时期官印封泥，证实了当时在云南推行（ ）","options":[{"key":"A","text":"禅让制"},{"key":"B","text":"郡县制"},{"key":"C","text":"分封制"},{"key":"D","text":"行省制"}],"answer":"B","explanation":"郡县制下地方分为郡、县两级，由中央政府直接任命郡守、县令等官员管理，官印封泥是郡县制推行的实物证据；禅让制是部落联盟首领让位给贤能者的制度；分封制盛行于西周；行省制是元朝开始实行的地方行政管理制度。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考·历史第4题","stem":"《齐民要术·种谷》中说：“顺天时，量地利，则用力少而成功多。任情返道，劳而无获。”这反映出贾思勰强调农业生产要（ ）","options":[{"key":"A","text":"不误农时，因地制宜"},{"key":"B","text":"编订户籍，开通运河"},{"key":"C","text":"家庭生产，自给自足"},{"key":"D","text":"多种经营，商品生产"}],"answer":"A","explanation":"据题干“顺天时，量地利，则用力少而成功多”可知，《齐民要术·种谷》强调农业生产要遵循自然规律，种植作物必须因地制宜、不误农时；“编订户籍，开通运河”是隋朝统治者采取的措施；“家庭生产，自给自足”是我国长期以来小农经济的特征；“多种经营，商品生产”与题干强调的遵循自然规律无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省镇江市中考·历史第3题","stem":"汉魏时，江南的主要粮食作物是水稻。东晋南朝时，则有麦、黍、粟、麻等许多来自北方的作物。出现上述现象的直接原因是（ ）","options":[{"key":"A","text":"政府重视农业生产"},{"key":"B","text":"海外贸易繁荣发展"},{"key":"C","text":"北方人口大量南迁"},{"key":"D","text":"经济重心南移完成"}],"answer":"C","explanation":"西晋永嘉之乱后，北方战乱导致大量移民南迁（“衣冠南渡”），北人带来北方作物种子和种植技术，使江南开始种植麦、黍等旱地作物；“政府重视农业生产”是江南得到开发的原因之一，但无法直接解释北方作物突然出现在江南；题干作物是中国北方传统作物，与海外引入无关；经济重心南移完成于南宋，而题干时间是南移的初始阶段。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省聊城市中考·历史第2题","stem":"“僇力本业，耕织致粟帛多者复其身。事末利及怠而贫者，举以为收孥。”商鞅变法中的这一规定旨在（ ）","options":[{"key":"A","text":"促进商业发展"},{"key":"B","text":"鼓励农业生产"},{"key":"C","text":"限制土地兼并"},{"key":"D","text":"打击贵族势力"}],"answer":"B","explanation":"“僇力本业，耕织致粟帛多者复其身”意思是努力从事农业生产、粮食布帛产量多的人可以免除徭役，“事末利及怠而贫者，举以为收孥”则是惩罚经商和懒惰致贫的人，商鞅奖励耕织是为了鼓励百姓从事农业生产；这是重农抑商，不是促进商业；题干未提及限制土地兼并；打击贵族势力是废除世袭特权、奖励军功的内容。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省连云港市中考·历史第1题","stem":"考古工作者在浙江余姚发掘出一处距今约7000年的遗址，发现了大量的稻谷、谷壳、稻秆和稻叶堆积。同时，出土了骨耜等工具。这表明，当时该地区（ ）","options":[{"key":"A","text":"知道使用火"},{"key":"B","text":"会简单制衣"},{"key":"C","text":"已有了原始农业"},{"key":"D","text":"建立了早期国家"}],"answer":"C","explanation":"稻谷、谷壳、稻秆和稻叶堆积以及骨耜表明该地区已开始人工种植水稻并使用农具耕作，属于原始农业的范畴；使用火在原始社会普遍存在，但与题干证据无关；制衣需纺织工具或缝纫工具佐证，题干未提及；早期国家出现于更晚的夏商时期，河姆渡仍处于氏族社会。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第3题","stem":"“初并天下，自以为德兼三皇，功过五帝，乃更号曰‘皇帝’”。该材料中的“皇帝”指的是（ ）","options":[{"key":"A","text":"嬴政"},{"key":"B","text":"刘邦"},{"key":"C","text":"李世民"},{"key":"D","text":"赵匡胤"}],"answer":"A","explanation":"公元前221年秦始皇统一六国，自认为德行超过三皇、功绩胜过五帝，于是改称号为“皇帝”，秦始皇就是嬴政；刘邦为汉朝开国皇帝，但非首创“皇帝”称号；李世民为唐朝第二位皇帝；赵匡胤为宋朝建立者，也未统一天下。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省自贡市中考·历史第1题","stem":"秦始皇为解决战国以来“言语异声，文字异形”问题，采取的措施是（ ）","options":[{"key":"A","text":"建立皇帝制度"},{"key":"B","text":"统一文字"},{"key":"C","text":"统一度量衡"},{"key":"D","text":"统一车轨"}],"answer":"B","explanation":"战国时期语言和文字不统一，秦始皇为加强中央集权，统一文字，规定小篆为全国标准字体，后推广隶书。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖北省中考·历史（原始题号未标注）","stem":"据考证，商朝的汉字数量计4400个以上，已经识别的字在1500个以上。现在常用的汉字多数在商朝已经定型，如祖、父、妣（bǐ）、母、兄、弟、姑、子等亲属称谓当时已出现。这说明商朝（ ）","options":[{"key":"A","text":"文字较为成熟"},{"key":"B","text":"统治范围扩大"},{"key":"C","text":"社会等级森严"},{"key":"D","text":"王权色彩浓厚"}],"answer":"A","explanation":"商朝汉字数量超4400个，已识别超1500个，常用汉字多数在商朝已经定型，表明商朝的文字已具备一定规模和规范，能够较为成熟地记录信息、表达含义。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省德阳市中考·历史（原始题号未标注）","stem":"不同类型的史料为史学研究提供了载体，像商周的遗迹、秦汉的史书、唐宋的诗词、明清的档案等。其中史料价值最高的是（ ）","options":[{"key":"A","text":"商周的遗迹"},{"key":"B","text":"秦汉的史书"},{"key":"C","text":"唐宋的诗词"},{"key":"D","text":"明清的档案"}],"answer":"A","explanation":"商周的遗迹属于第一手史料（原始史料），是当时社会直接留下的实物证据，最直接、最真实。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省中考·历史（原始题号未标注）","stem":"以下是某同学在一节历史课堂上整理的笔记。由此可知，他本节课学习的内容是（ ）1．商鞅变法为秦国统一中国奠定基础。2．孝文帝改革增强了北魏实力。3．王安石变法使北宋政府的财政收入有所增加。","options":[{"key":"A","text":"经济重心南移"},{"key":"B","text":"改革推动发展"},{"key":"C","text":"国家走向统一"},{"key":"D","text":"君主专制强化"}],"answer":"B","explanation":"商鞅变法、孝文帝改革、王安石变法均属不同时期的重大改革，都强调改革对国家发展的积极影响。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省遂宁市中考·历史（原始题号未标注）","stem":"朱绍侯等主编的《中国古代史》中写道：“到了战国时期，夺权胜利的地主阶级为了巩固和扩展利益，先后开展了社会改革，掀起了变法运动。面对当时的社会大变革，人们提出不同的主张，形成了‘百家争鸣’的局面。”作者意在说明（ ）","options":[{"key":"A","text":"人民群众是物质生产的主要承担者"},{"key":"B","text":"阶级斗争是历史发展的直接动力"},{"key":"C","text":"劳动在人类社会发展中的重要作用"},{"key":"D","text":"社会变革促进了思想文化的发展"}],"answer":"D","explanation":"地主阶级夺权后开展社会改革、变法运动，面对社会大变革人们提出各种主张，形成百家争鸣，强调社会变革对思想文化的影响。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省梅州市兴宁市宋声学校中考一模·历史","stem":"1963年6月至7月，考古学家对黑龙江省莺歌岭遗址进行了发掘。其文化遗存有方形的半地穴式建筑、陶器、骨角器及少量磨制石器。据此推断，此遗址属于（ ）","options":[{"key":"A","text":"旧石器时代"},{"key":"B","text":"新石器时代"},{"key":"C","text":"青铜时代"},{"key":"D","text":"铁器时代"}],"answer":"B","explanation":"新石器时代是以使用磨制石器为标志的人类物质文化发展阶段。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-early-civilizations","stem":"考古学家在辽河、黄河、长江流域都发现了距今约五千年的文明遗址。这直接说明","options":[{"key":"A","text":"各地之间没有任何交流"},{"key":"B","text":"长江流域文明出现得最早"},{"key":"C","text":"中华文明起源具有多元的特点"},{"key":"D","text":"中华文明只起源于黄河流域"}],"answer":"C","explanation":"不同地方都有发现，直接说明分布较广、起源多元；谁传给谁不能仅凭这一点判断。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-enfeoffment-commandery","stem":"秦朝的郡守、县令与西周的诸侯相比，最大的不同是","options":[{"key":"A","text":"可以把职位传给后代"},{"key":"B","text":"拥有自己的封国"},{"key":"C","text":"不需要服从中央"},{"key":"D","text":"由中央任免，不能世袭"}],"answer":"D","explanation":"西周诸侯有世袭的一面；秦朝郡守、县令由朝廷任命，不能传给后代。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-confucius-teaching","stem":"孔子招收学生，不论贫富贵贱，都可以入学。这体现了他的","options":[{"key":"A","text":"有教无类"},{"key":"B","text":"因材施教"},{"key":"C","text":"温故知新"},{"key":"D","text":"学而不思则罔"}],"answer":"A","explanation":"有教无类讲“谁能受教育”；因材施教讲“怎么教”，即根据学生情况调整方法。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-silk-road","stem":"关于丝绸之路，下列说法正确的是","options":[{"key":"A","text":"它只有贸易往来，没有文化交流"},{"key":"B","text":"张骞出使西域为它的开通创造了条件，沿线交流是双向的"},{"key":"C","text":"它只把中国的丝绸运往西方"},{"key":"D","text":"它是明朝开通的"}],"answer":"B","explanation":"西汉张骞两次出使西域，为丝绸之路开通创造条件；商品、技术和文化双向传播。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-northern-wei-reform","stem":"北魏孝文帝迁都洛阳，规定朝廷使用汉语、改用汉姓。这些措施的主要作用是","options":[{"key":"A","text":"开发了江南地区"},{"key":"B","text":"实现了全国统一"},{"key":"C","text":"促进了民族交融"},{"key":"D","text":"使鲜卑族完全消失"}],"answer":"C","explanation":"改革增加了鲜卑族与汉族在制度、语言和习俗上的接触，促进民族交融；开发江南是另一考点。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"我国境内已知最早的古人类是____，距今约170万年。","answer":["元谋人"],"explanation":"元谋人遗址在云南元谋；北京人会使用天然火。"},{"type":"blank","stem":"我国历史上第一个王朝是____，由禹的儿子____建立，从此“公天下”变为“家天下”。","answer":["夏朝","启"],"explanation":"约公元前2070年禹建立夏朝，禹死后启继位，王位世袭制代替禅让制。"},{"type":"blank","stem":"目前所知我国最早的成熟文字是商朝的____。","answer":["甲骨文"],"explanation":"甲骨文刻在龟甲和兽骨上，是汉字的源头。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2025年福建中考·历史第30题(1)","kind":"材料分析题","material":"战国时期，随着农业发展，铁制农具在各地广泛使用。汉代冶铁竖炉、水排等冶铁工具的发明，使得制造出的农具更加坚固耐用，产量也获得提升。在全国各地出土了大量种类繁多的汉代铁制农具。——据马克垚《世界文明史》等","stem":"根据材料，说明我国古代冶铁技术发展与农业生产之间的关系。（6分）","points":[{"text":"农业生产的需求催生了冶铁技术的革新","score":2},{"text":"农业的发展为冶铁技术的进步提供了物质基础","score":1},{"text":"冶铁技术进步有利于制造出种类更多、数量更大、质量更好的农具","score":1},{"text":"推动农业生产范围扩大、产量增多，推动精耕细作的出现","score":1},{"text":"为我国古代农业长期领先奠定基础","score":1}],"score":6,"sample":"","explanation":"两者相互促进：农业需要更好的工具，推动冶铁革新；冶铁进步又制造出更好的农具，反过来推动农业发展。"},{"type":"essay","tag":"材料分析题","source":"2025年福建中考·历史第30题(2)","kind":"材料分析题","material":"材料一：战国时期，随着农业发展，铁制农具广泛使用；汉代冶铁竖炉、水排的发明，使农具更加坚固耐用。\n材料二：【汉·彩绘雁鱼铜灯】大雁象征夫妻恩爱、诚信守节，鱼象征富足美满。灯盘、灯罩可任意转动开合以调节光照和挡风，鱼身、雁颈和雁体中空相通，可纳烟尘，各部分可拆卸清洗。【汉·鎏金铜马】通体鎏金，表面光洁度很高；马的肌肉和筋骨的雕刻符合解剖比例，以大宛产的汗血马为参照精制而成。——据中国国家博物馆《文物中国史》等","stem":"根据材料一、二，概括影响手工业品制作的因素。（6分）","points":[{"text":"生产、生活的需求（农业生产需要、对美好生活的追求）","score":2},{"text":"科学技术水平（理论提升、工具进步）","score":2},{"text":"国家与社会的影响（社会稳定、统一多民族国家的发展、社会风气与社会传统）","score":2}],"score":6,"sample":"","explanation":"雁鱼灯可以挡风、吸烟尘，说明来自生活需要和技术进步；铜马参照大宛汗血马，与汉朝通西域、国家统一强盛有关；雁、鱼的寓意反映社会风气与传统。"}]}]},{"id":"xiaosimen-lishi-2","group":"历史","subject":"历史","term":"七年级下册","title":"历史 · 七年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第6题","stem":"中国古代选官制度经过了一系列变革，直到进士科的创立，一种新的选官制度正式确立。这种制度出现于（ ）","options":[{"key":"A","text":"隋朝"},{"key":"B","text":"唐朝"},{"key":"C","text":"明朝"},{"key":"D","text":"清朝"}],"answer":"A","explanation":"科举制始于隋朝，隋炀帝时正式设置进士科，标志着科举制度正式确立；唐朝进一步完善科举制（如增加考试科目、殿试等），但并非创立时期；明朝实行八股取士，是科举制度的一种僵化表现；1905年清朝废除科举制度，与创立无关。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第7题","stem":"北宋时，南方主食以稻米为主，北方以面食为主；南宋时，南方的面食店日益增加。该变化产生的主要因素是（ ）。","options":[{"key":"A","text":"温度差异"},{"key":"B","text":"土壤条件"},{"key":"C","text":"生活水平"},{"key":"D","text":"人口迁移"}],"answer":"D","explanation":"从唐朝中晚期至两宋时期，北方人口大批南迁，北方人饮食以面食为主，南方面食店因此日益增加，产生的主要因素是人口迁移。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第10题","stem":"明朝在户部设置太仓库，“专备三边军饷”，与皇室的内库有别。明神宗时，皇室的日用、婚丧等花费远超以往，皇帝“数取太仓银入内库”。这导致明朝（ ）。","options":[{"key":"A","text":"物价不断飞涨"},{"key":"B","text":"与清军作战失利"},{"key":"C","text":"官员职权范围缩小"},{"key":"D","text":"国家财政体制被破坏"}],"answer":"D","explanation":"太仓库专备三边军饷、与皇室内库有别，明神宗违背财政制度，“数取太仓银入内库”，导致明朝国家财政体制被破坏。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第8题","stem":"乾隆时期，钦定绘制了包含高山族、赫哲族等在内的本朝各民族形象的《职贡图》，并配有相应的满文、汉文介绍。这份《职贡图》佐证了（ ）。","options":[{"key":"A","text":"统一多民族国家的发展"},{"key":"B","text":"君主专制强化"},{"key":"C","text":"官员选拔制度的演变"},{"key":"D","text":"人口迅速增长"}],"answer":"A","explanation":"《职贡图》涵盖高山族、赫哲族等各民族形象并配有满文、汉文介绍，体现了清朝对各民族的认可与管辖，佐证统一多民族国家的发展。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建中考·历史第9题（表格转文字）","stem":"汉语中将姜、胡椒等物及其刺激性味道称为“辛”，而“辣”是指辛得厉害；“椒”多指花椒。原产于美洲的辣椒传入中国后，便因其味辛辣而得名。据此判断，可以佐证辣椒进入人民生活的是（ ）","options":[{"key":"A","text":"有椒其馨（[春秋]《诗经》）"},{"key":"B","text":"（蜀人）尚滋味，好辛香（[晋]《华阳国志》）"},{"key":"C","text":"大娘子又过得好，怎么便下得这等狠心辣手（[元]《京本通俗小说》）"},{"key":"D","text":"他是我们这里有名的一个泼皮破落户儿，南省俗谓作“辣子”，你只叫他“凤辣子”就是了（[清]《红楼梦》）"}],"answer":"D","explanation":"辣椒原产美洲，明代才传入中国，只有清代《红楼梦》中“辣子”“凤辣子”的说法能证明辣椒已进入人民生活。A说的是花椒，B说的是辛香之味，C的“辣手”是狠心之意，均与辣椒无关。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第8题","stem":"元朝时，内外商人出海或登陆，须先赴市舶司登记；凡从海外运货抵港，须依法经市舶司抽税后方可销售。这些举措（ ）","options":[{"key":"A","text":"强化了对海外贸易的监管"},{"key":"B","text":"推动了航海技术进步"},{"key":"C","text":"扩大了南方地区经济优势"},{"key":"D","text":"导致了白银大量外流"}],"answer":"A","explanation":"出海登陆要登记、运货抵港要抽税，都是政府通过市舶司加强对海外贸易的管理。材料未涉及航海技术、南方经济优势与白银外流。"},{"type":"choice","tag":"Claude 精选","source":"2025年云南省中考·历史第5题","stem":"南北朝时期，北方少数民族统治者大多采取与汉族士人合作的政策，学习汉族的典章制度。辽宋夏金时期，西夏和金朝仿效唐宋制度，改革军政。据材料可知，少数民族统治者（ ）","options":[{"key":"A","text":"都面临严重的政治危机"},{"key":"B","text":"已经放弃游牧民族生活方式"},{"key":"C","text":"意在消除民族间的隔阂"},{"key":"D","text":"逐渐接受中原王朝统治理念"}],"answer":"D","explanation":"南北朝时期少数民族与汉族士人合作、学习典章制度，辽宋夏金时期西夏和金朝仿效唐宋制度改革军政，这些行为本质上是对中原王朝以“典章制度”为核心的统治理念的接受。材料未提及政治危机、放弃游牧生活方式和消除民族隔阂的意图。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省威海市中考·历史第6题","stem":"《威海人史话》中记载：靖康之难后，威海全境进入金朝统治时期。金被灭后，威海全境又进入元朝统治时期。金、元时期统治威海的少数民族分别是（ ）","options":[{"key":"A","text":"女真族、蒙古族"},{"key":"B","text":"满洲族、蒙古族"},{"key":"C","text":"党项族、满洲族"},{"key":"D","text":"女真族、满洲族"}],"answer":"A","explanation":"金朝由女真族建立（如完颜阿骨打），元朝由蒙古族建立（如忽必烈）；满洲族（满族）是清朝的建立民族，与金、元无关；党项族建立的是西夏政权，与金、元无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省聊城市中考·历史第6题","stem":"“五代方镇残虐，民受其祸，朕今选儒臣干事者百余，分治大藩，纵皆贪浊，亦未及武臣一人也。”宋太祖这样做的主要目的是（ ）","options":[{"key":"A","text":"完善科举制度"},{"key":"B","text":"削弱宰相权力"},{"key":"C","text":"健全监察制度"},{"key":"D","text":"强化中央集权"}],"answer":"D","explanation":"五代时期地方藩镇势力强大，残暴虐杀百姓，严重威胁中央集权。宋太祖选用儒臣治理地方藩镇，是因为他认为即使儒臣贪浊，危害也比不上一个武臣，通过这一措施将地方军政权力分散，削弱了地方藩镇势力，从而强化了中央集权；题干重点不是完善科举制度、削弱宰相权力或健全监察制度。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省连云港市中考·历史第3题","stem":"杜佑《通典》卷七载：“自贞观以后，太宗励精为理……至（贞观）十五年，米每斗值两钱。”作者使用的历史纪年法是（ ）","options":[{"key":"A","text":"干支纪年法"},{"key":"B","text":"年号纪年法"},{"key":"C","text":"王位纪年法"},{"key":"D","text":"公元纪年法"}],"answer":"B","explanation":"题干中“贞观十五年”的“贞观”是唐太宗的年号，年号纪年法是中国古代以帝王即位后设定的年号加具体年份的纪年方式，如贞观、开元等；干支纪年法以天干地支组合纪年（如甲子年）；王位纪年法以君主在位年数纪年（如周平王元年），但题干明确使用年号；公元纪年法为现代国际通用纪年，与“贞观”无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第10题","stem":"历史事实是指对历史人物或事件的客观叙述。历史解释是客观地认识和评判历史的态度和方法。下列选项中属于历史解释的是（ ）","options":[{"key":"A","text":"1684年，清朝设置台湾府，隶属福建省"},{"key":"B","text":"1727年，清朝在西藏设置驻藏大臣"},{"key":"C","text":"乾隆帝平定回部上层贵族大、小和卓叛乱"},{"key":"D","text":"伊犁将军的设置加强了清朝对西北地区的管辖"}],"answer":"D","explanation":"“伊犁将军的设置加强了清朝对西北地区的管辖”中“加强了”是对伊犁将军设置作用的评价，属于历史解释；“1684年，清朝设置台湾府，隶属福建省”“1727年，清朝在西藏设置驻藏大臣”“乾隆帝平定回部上层贵族大、小和卓叛乱”均仅陈述时间、地点和事件，属于历史事实。"},{"type":"choice","tag":"Claude 精选","source":"2023年四川省乐山市中考·历史第5题","stem":"国学大师王国维说：“凡一代有一代之文学……唐之诗，宋之词，元之曲，皆所谓一代之文学。”明清时期的“一代之文学”是（ ）","options":[{"key":"A","text":"杂剧"},{"key":"B","text":"散文"},{"key":"C","text":"小说"},{"key":"D","text":"戏曲"}],"answer":"C","explanation":"明清时期文学艺术的发展与市民文化结合起来，小说等大众化的文学艺术形式有了突出的发展，明清时期的“一代之文学”是小说。"},{"type":"choice","tag":"Claude 精选","source":"2023年湖南省邵阳市中考·历史（原始题号未标注）","stem":"哈佛大学教授艾利森说，我也从中国智慧中学到很多经验，比如1005年的澶渊之盟，交战双方提出，我们不能够打败对方，但可以商讨一个条约，形成对抗的伙伴关系，在一些领域里激烈敌对，但在另外一些领域内结为伙伴。艾利森对澶渊之盟的叙述（ ）","options":[{"key":"A","text":"比较符合历史史实"},{"key":"B","text":"完全违背历史真相"},{"key":"C","text":"是研究澶渊之盟的重要史料"},{"key":"D","text":"属于恶意诋毁中国的言论"}],"answer":"A","explanation":"澶渊之盟后，宋辽之间保持了长久的和平，边境贸易兴盛，艾利森认为军事对抗可以转变为其他领域的合作，比较符合历史史实。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省梅州市兴宁市宋声学校中考一模·历史","stem":"《元史·地理志》记载：“元有天下，薄海内外，人迹所及，皆置驿传，使驿往来，如行国中。”上述材料反映了元朝（ ）","options":[{"key":"A","text":"农业经济发展"},{"key":"B","text":"文明辐射四方"},{"key":"C","text":"丝绸之路受阻"},{"key":"D","text":"陆路交通发达"}],"answer":"D","explanation":"元代设置大量驿站，形成覆盖全国的陆路交通网，陆路向西通往中亚、西亚及东欧。"},{"type":"choice","tag":"Claude 精选","source":"2024年重庆市西南大附中中考一模·历史","stem":"下列是某校历史学习小组进行《一座城门见证唐朝历史》的主题探究时收集的材料（唐朝开远门、文成公主与吐蕃和亲、大秦国僧人、胡商）。材料反映出唐朝（ ）","options":[{"key":"A","text":"中外交往友好共处"},{"key":"B","text":"人才汇集经济繁荣"},{"key":"C","text":"兼容并包繁荣开放"},{"key":"D","text":"民族交融国家统一"}],"answer":"C","explanation":"唐蕃和亲促进了吐蕃经济和社会发展；当时国内各族和国外的商人、使者、艺人、学子、僧侣、工匠等云集长安，反映唐朝兼容并包、繁荣开放。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-imperial-exams","stem":"通常被视为科举制正式确立标志的是","options":[{"key":"A","text":"唐朝完善科举制度"},{"key":"B","text":"宋朝扩大取士规模"},{"key":"C","text":"隋文帝统一全国"},{"key":"D","text":"隋炀帝设进士科"}],"answer":"D","explanation":"隋炀帝设进士科通常作为科举制正式确立的标志；唐朝是完善，不是创立。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-tang-cultural-exchange","stem":"唐朝时，从中国出发东渡日本、传播中国文化的高僧是","options":[{"key":"A","text":"鉴真"},{"key":"B","text":"玄奘"},{"key":"C","text":"张骞"},{"key":"D","text":"郑和"}],"answer":"A","explanation":"玄奘西行天竺求取佛学；鉴真东渡日本；遣唐使是日本派到唐朝学习的使团。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-economic-shift-south","stem":"我国古代经济重心南移完成于","options":[{"key":"A","text":"明朝"},{"key":"B","text":"南宋"},{"key":"C","text":"东晋"},{"key":"D","text":"隋朝"}],"answer":"B","explanation":"经济重心南移是一个长期过程，到南宋完成。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-maritime-trade-offices","stem":"宋元时期政府在一些港口设置市舶司，它的主要职责是","options":[{"key":"A","text":"建造远洋海船"},{"key":"B","text":"管理西藏地区事务"},{"key":"C","text":"管理海外贸易，负责登记、验货、抽税"},{"key":"D","text":"禁止海外贸易"}],"answer":"C","explanation":"市舶司登记商船、验货、征税，体现对海外贸易的管理，不能推出禁止贸易或造船技术进步。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-yuan-regional-governance","stem":"元朝在澎湖设巡检司，管辖","options":[{"key":"A","text":"西藏地区"},{"key":"B","text":"东北地区"},{"key":"C","text":"新疆地区"},{"key":"D","text":"澎湖和台湾"}],"answer":"D","explanation":"元朝设宣政院掌管西藏事务，在澎湖设巡检司管辖澎湖和台湾。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"隋朝创立的____制度，改变了以门第取士的做法，在唐朝得到完善。","answer":["科举"],"explanation":"隋炀帝时正式设置进士科，标志科举制正式诞生。"},{"type":"blank","stem":"唐太宗时，文成公主入藏与吐蕃赞普____联姻；唐玄宗前期的治世被称为“____”。","answer":["松赞干布","开元盛世"],"explanation":"唐太宗时期的治世称“贞观之治”。"},{"type":"blank","stem":"北宋时，____发明活字印刷术；我国最早的纸币是北宋前期四川地区的“____”。","answer":["毕昇","交子"],"explanation":"活字印刷术用胶泥制活字。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2024年福建中考·历史第30题(1)","kind":"材料分析题","material":"历代农民通过对各种自然现象进行观测总结，积累了大量的物候知识。物候知识与气象、天象紧密联系，可被用于把握农时以达到增产目的，如“黄莺儿鸣叫”就是采桑活动时宜的标志。利用物候知识研究农业生产，已经发展为一门科学——物候学。——摘编自阴法鲁等主编《中国古代文化史（插图本）》","stem":"根据材料一，简述物候知识的价值。（4分）","points":[{"text":"对农业生产具有重要的指导作用（把握农时、增产）","score":1},{"text":"是研究古代气象知识的重要依据","score":1},{"text":"推动气象学、天文学的发展","score":1},{"text":"推动物候学的产生","score":1}],"score":4,"sample":"","explanation":"紧扣材料关键词：“把握农时”“与气象、天象紧密联系”“发展为一门科学——物候学”。"},{"type":"essay","tag":"材料分析题","source":"2024年福建中考·历史第30题(2)","kind":"材料分析题","material":"【唐·鎏金银香囊】该香囊利用了陀螺仪万向支架原理，无论如何转动，中间焚香的盂始终保持水平状态，焚香都不会倾洒；外壳通体镂空，便于香气散出，且可随身挂佩，在唐朝风靡一时。\n【北宋·青釉剔花倒装壶】该壶利用了虹吸原理，注水孔在壶底，注水时水并不会从壶嘴流出。水壶翻转后，水也不会从壶底漏出，只有当壶身向壶嘴处倾斜时，水才会自然流出，这增加了壶的密封性和便携性，后来该类壶普遍流行。——摘编自爱德华·谢弗《撒马尔罕的金桃》等","stem":"根据材料二，概括其体现出的古代手工业品的特点。（6分）","points":[{"text":"造型美观、设计精巧","score":2},{"text":"工艺高超","score":1},{"text":"科学原理与实践相结合","score":1},{"text":"注重实用性（便携、密封）","score":1},{"text":"引领风尚、日益走向大众","score":1}],"score":6,"sample":"","explanation":"“陀螺仪原理”“虹吸原理”说明科学原理与实践结合；“随身挂佩”“便携性”说明实用；“风靡一时”“普遍流行”说明引领风尚、走向大众。"}]}]},{"id":"xiaosimen-lishi-3","group":"历史","subject":"历史","term":"八年级上册","title":"历史 · 八年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第12题","stem":"“白话的传播遍于全国，与1919年的学生运动大有关系”，因为此后“各地的学生团体很快办起了约四百种白话报刊”。这表明（ ）。","options":[{"key":"A","text":"戊戌变法促进思想解放"},{"key":"B","text":"君主专制制度已终结"},{"key":"C","text":"五四运动助推文学革命"},{"key":"D","text":"封建礼教被全面推翻"}],"answer":"C","explanation":"1919年五四运动后，各地学生团体很快办起了约四百种白话报刊，说明五四运动助推了文学革命。"},{"type":"choice","tag":"Claude 精选","source":"2024年湖北省武汉市中考·历史第5题","stem":"第二次鸦片战争后，江南机器制造总局、天津机器局等兵工厂生产的武器，供应给驻守台湾以及广西、云南等前线的各路清军使用。煤矿、冶铁、纺织等领域建立的民用企业也逐渐改变着社会面貌。这些现象的出现是因为（ ）","options":[{"key":"A","text":"太平天国分土地"},{"key":"B","text":"洋务运动求富强"},{"key":"C","text":"维新变法启民智"},{"key":"D","text":"扶清灭洋御外侮"}],"answer":"B","explanation":"洋务运动时期创办了军事工业和民用工业，对当时的军事和经济发展产生了一定影响，体现了自强求富的目的。太平天国分土地与《天朝田亩制度》有关；材料未涉及维新变法；扶清灭洋是义和团运动的口号。"},{"type":"choice","tag":"Claude 精选","source":"2024年北京市中考·历史第11题","stem":"1911年，上海的一首竹枝词写道：“武昌起义众心惊，报馆齐张革命声。争向门前探捷报，望平街上路难行……但看某城光复矣，眉飞色舞竟忘餐。”这表现出民众（ ）","options":[{"key":"A","text":"推动了义和团运动的发展"},{"key":"B","text":"支持辛亥革命"},{"key":"C","text":"反对袁世凯窃取革命果实"},{"key":"D","text":"声援北伐战争"}],"answer":"B","explanation":"竹枝词描写武昌起义后上海民众争看捷报、为光复而欢欣鼓舞，表现出民众支持辛亥革命。义和团运动发生在1900年前后；袁世凯窃取革命果实和北伐战争均在1911年之后，与“武昌起义”的时间不符。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第12题","stem":"某历史人物去世后，时人撰写挽联：“抗孙黄以做总统，先临时、后正式、旋改国号，一片心称皇呼帝，忽焉取消，我也笑鳌人紫泥。”这反映出当时（ ）","options":[{"key":"A","text":"清廷压迫百姓"},{"key":"B","text":"复辟行径不得人心"},{"key":"C","text":"军阀割据混战"},{"key":"D","text":"封建制度业已终结"}],"answer":"B","explanation":"挽联讽刺的是先做临时、正式总统、旋改国号称帝又取消的袁世凯，其复辟帝制行径受到时人嘲笑，说明复辟不得人心。材料针对的是袁世凯个人，与清廷压迫、军阀混战、封建制度终结无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第16题","stem":"毛泽东在《论联合政府》中指出，要建设新民主主义的国家“如无大规模的在全国经济比重上占极大优势的工业以及与此相适应的交通、贸易、金融等事业作它的基础，是不能巩固的”。毛泽东意在强调（ ）","options":[{"key":"A","text":"对日作战的方针"},{"key":"B","text":"经济基础的重要性"},{"key":"C","text":"交通工具的革新"},{"key":"D","text":"政治改革的迫切性"}],"answer":"B","explanation":"毛泽东强调新民主主义国家必须以大规模工业及相适应的交通、贸易、金融为基础才能巩固，意在强调经济基础的重要性。材料讲的是建国基础，不是抗日方针、交通革新或政治改革。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第13题","stem":"鸦片战争时，清廷上下对条约的谈判和签订，不理解也不重视，到了20世纪初，研习国际法和条约已渐成风气。这体现出清廷（ ）","options":[{"key":"A","text":"日益腐败"},{"key":"B","text":"近代外交意识逐渐觉醒"},{"key":"C","text":"谋求君主立宪"},{"key":"D","text":"沦为列强统治中国的工具"}],"answer":"B","explanation":"从不理解、不重视条约到研习国际法和条约成风，说明清廷的近代外交意识逐渐觉醒。材料讲的是对条约态度的转变，未涉及腐败、君主立宪与沦为工具。"},{"type":"choice","tag":"Claude 精选","source":"2025年江西省中考·历史（原始题号未标注）","stem":"他公开宣称自己只是一个临时大总统，暂时担任此职只是为了号召国民团结一致、投身革命，一旦一个稳固的共和政府得以建立，便准备退位让贤。材料中的'他'是（ ）","options":[{"key":"A","text":"孙中山"},{"key":"B","text":"黄兴"},{"key":"C","text":"黎元洪"},{"key":"D","text":"张作霖"}],"answer":"A","explanation":"孙中山在1912年就任临时大总统后，为促成南北统一，主动表示愿让位于袁世凯以换取清帝退位。黄兴未担任临时大总统，黎元洪任武昌起义后都督、后任副总统，张作霖是北洋军阀。"},{"type":"choice","tag":"Claude 精选","source":"2025年吉林省中考·历史（原始题号未标注）","stem":"武汉是近代民主革命的重镇，有'首义之城'的美誉。这得益于（ ）","options":[{"key":"A","text":"黄花岗起义"},{"key":"B","text":"武昌起义"},{"key":"C","text":"二次革命"},{"key":"D","text":"北伐战争"}],"answer":"B","explanation":"1911年10月10日武昌起义爆发，是辛亥革命的开端，武汉因此被称为'首义之城'。黄花岗起义在广州，二次革命在1913年，北伐战争在1926年，都与武汉'首义之城'称号的由来无关。"},{"type":"choice","tag":"Claude 精选","source":"2024年山东省潍坊市中考·历史（原始题号未标注）","stem":"《中华民国临时约法》规定：'临时大总统、副总统由参议院选举之。''中华民国之立法权以参议院行之。'这些规定旨在（ ）","options":[{"key":"A","text":"扩大统治基础"},{"key":"B","text":"宣传自由平等"},{"key":"C","text":"倡导三权分立"},{"key":"D","text":"维护民主共和"}],"answer":"D","explanation":"《中华民国临时约法》是中国历史上第一部具有资产阶级共和国宪法性质的重要文件，大总统由参议院选举、立法权归参议院等规定，核心目的是限制袁世凯的权力、维护民主共和制度。自由平等和三权分立都是民主共和制度的体现，但不是这些规定的直接目的。"},{"type":"choice","tag":"Claude 精选","source":"2024年贵州省黔南州中考·历史（原始题号未标注）","stem":"1935年，电影《渔光曲》在莫斯科国际电影节上获荣誉奖，成为中国第一部在国际上获奖的影片。该影片获奖的时间换算成民国纪年是（ ）","options":[{"key":"A","text":"民国二十年"},{"key":"B","text":"民国二十二年"},{"key":"C","text":"民国二十四年"},{"key":"D","text":"民国二十六年"}],"answer":"C","explanation":"1912年中华民国建立，是民国元年。公元年份减1911即得民国年份：1935－1911＝24，即民国24年。民国二十年是1931年，民国二十二年是1933年，民国二十六年是1937年。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省扬州市中考·历史（原始题号未标注）","stem":"20世纪初，武汉街头出现了'乘汽车马车者，男女杂坐，不以为嫌'的场景。该场景反映当时（ ）","options":[{"key":"A","text":"新式教育发达"},{"key":"B","text":"生活方式和传统观念的变化"},{"key":"C","text":"娱乐方式多样"},{"key":"D","text":"中国人民真正成为国家主人"}],"answer":"B","explanation":"20世纪初武汉街头男女同乘汽车马车、不以为嫌，反映传统男女有别观念受到冲击，生活方式和传统观念发生变化。新式教育、娱乐方式都与出行场景无关；人民成为国家主人是在新中国成立后。"},{"type":"choice","tag":"Claude 精选","source":"2024年江苏省宿迁市中考·历史（原始题号未标注）","stem":"毛泽东说：讲到重工业不能忘记张之洞，讲到轻工业不能忘记张謇。张謇创办了（ ）","options":[{"key":"A","text":"大生纱厂"},{"key":"B","text":"江南机器制造总局"},{"key":"C","text":"汉阳铁厂"},{"key":"D","text":"上海轮船招商局"}],"answer":"A","explanation":"张謇是清末状元，甲午战争后认识到要挽救民族危亡就要发展实业，毅然辞官回乡，提出'实业救国'的口号，创办了大生纱厂。江南机器制造总局和上海轮船招商局是李鸿章创办的洋务企业，汉阳铁厂是张之洞创建的。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省长沙市中考·历史（原始题号未标注）","stem":"“是中国自由神，三民五权，推翻历史数千年专制之局；愿吾侪后死者，齐心协力，完成先生一二件未竟之功。”这里的“先生”应该是（ ）","options":[{"key":"A","text":"林则徐"},{"key":"B","text":"洪秀全"},{"key":"C","text":"孙中山"},{"key":"D","text":"陈独秀"}],"answer":"C","explanation":"孙中山提出三民主义，倡导五权宪法，领导辛亥革命推翻了封建君主专制制度，材料中“三民五权，推翻历史数千年专制之局”与孙中山的事迹契合。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省宜宾市中考·历史（原始题号未标注）","stem":"孙中山在担任临时大总统期间，曾发布通令，要求所有政府官员树立公仆意识，“须知凡属官员，皆系为民服务，官规具在，莫不负应尽之责任，而无特别之利益。”这体现了中华民国临时政府（ ）","options":[{"key":"A","text":"治理体系的完善"},{"key":"B","text":"人民主权的实现"},{"key":"C","text":"实业救国的主张"},{"key":"D","text":"民主政治的色彩"}],"answer":"D","explanation":"孙中山强调官员应“为民服务”，体现民主政治中的公仆意识和服务理念。材料只强调官员责任，未涉及制度构建或民众直接行使权力，也与实业救国无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考·历史（原始题号未标注）","stem":"毛泽东说：讲到重工业不能忘记张之洞，讲到轻工业不能忘记张謇。这是在肯定张之洞、张謇（ ）","options":[{"key":"A","text":"实现了“自强”“求富”的目标"},{"key":"B","text":"创办中国近代工业的贡献"},{"key":"C","text":"培养国民独立人格挽救民族危亡"},{"key":"D","text":"学习西方改革内政的主张"}],"answer":"B","explanation":"张之洞是洋务运动代表人物，创办汉阳铁厂等重工业；张謇是实业救国倡导者，创办大生纱厂等轻工业。毛泽东的话旨在肯定两人在创办中国近代工业方面的历史功绩。“自强”“求富”是洋务运动的目标，但未完全实现，且张謇非洋务派。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-unequal-treaties","stem":"规定“允许日本在中国通商口岸开设工厂”的不平等条约是","options":[{"key":"A","text":"《马关条约》"},{"key":"B","text":"《南京条约》"},{"key":"C","text":"《辛丑条约》"},{"key":"D","text":"《北京条约》"}],"answer":"A","explanation":"先对战争再对条款：甲午中日战争后签《马关条约》，允许日本在通商口岸开设工厂。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-unequal-treaties","stem":"标志中国完全沦为半殖民地半封建社会的是","options":[{"key":"A","text":"鸦片战争的爆发"},{"key":"B","text":"《辛丑条约》的签订"},{"key":"C","text":"《南京条约》的签订"},{"key":"D","text":"《马关条约》的签订"}],"answer":"B","explanation":"《南京条约》后开始沦为、《马关条约》大大加深、《辛丑条约》完全沦为半殖民地半封建社会。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-early-modernization","stem":"辛亥革命最大的历史功绩是","options":[{"key":"A","text":"建立了中华人民共和国"},{"key":"B","text":"彻底完成了反帝反封建任务"},{"key":"C","text":"结束了统治中国两千多年的君主专制制度"},{"key":"D","text":"改变了中国半殖民地半封建的社会性质"}],"answer":"C","explanation":"辛亥革命结束了君主专制制度，但没有改变半殖民地半封建的社会性质。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-may-fourth-first-cooperation","stem":"第一次国共合作正式建立的标志是","options":[{"key":"A","text":"1921 年中共一大召开"},{"key":"B","text":"1919 年五四运动爆发"},{"key":"C","text":"1927 年南昌起义"},{"key":"D","text":"1924 年国民党一大召开"}],"answer":"D","explanation":"上海开会、嘉兴南湖续会是中共一大；第一次国共合作正式建立的标志是三年后的国民党一大。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-resistance-war-timeline","stem":"中国人民抗日战争的起点、全民族抗战的开始，分别是","options":[{"key":"A","text":"九一八事变；七七事变"},{"key":"B","text":"七七事变；九一八事变"},{"key":"C","text":"九一八事变；西安事变"},{"key":"D","text":"华北事变；七七事变"}],"answer":"A","explanation":"1931 年九一八事变是抗日战争的起点；1937 年七七事变后全民族抗战开始。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"1839年，____在广东虎门当众销毁鸦片。","answer":["林则徐"],"explanation":"虎门销烟是中国人民禁烟斗争的伟大胜利。"},{"type":"blank","stem":"1895年签订的《____条约》规定割辽东半岛、台湾岛及其附属岛屿和澎湖列岛给日本。","answer":["马关"],"explanation":"甲午战争中，致远舰管带邓世昌壮烈殉国。"},{"type":"blank","stem":"1901年签订的《____条约》标志着中国完全沦为半殖民地半封建社会。","answer":["辛丑"],"explanation":"《辛丑条约》规定清政府保证严禁人民反帝、划定北京东交民巷为使馆界等。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2024年福建中考·历史第29题","kind":"材料分析题","material":"【图5】红四方面军战士杨世才长征前留给母亲的布币（有磨损）。币面可辨认“川陕省苏维埃政府”“工农银行”“全世界无产阶级联合起来”“叁串”等字样，年份字迹已磨损。\n习题：据图判断，该货币最有可能发行于（ ）A.1923年 B.1933年 C.1943年 D.1953年","stem":"图5习题，你选择了正确选项B。请观察该题，提取至少两个信息且结合其反映的史实，说服选择了其余选项的同学。（8分）","points":[{"text":"信息一：币面有“川陕省苏维埃政府”字样 → 是土地革命战争时期（1927—1937年）红色政权发行的","score":3},{"text":"信息二：图注“长征前” → 长征开始于1934年（红四方面军1935年开始长征），货币应发行于1935年前","score":3},{"text":"两个信息互相印证，排除其余选项：1923年尚无苏维埃政权，1943年处于抗日战争时期，1953年新中国已成立","score":2}],"score":8,"sample":"图中货币上有川陕省苏维埃政府字样，由“苏维埃政府”可推知该货币为土地革命战争时期红色政权所发行；图注中有“长征前”，则说明该货币应发行于1935年前，与“苏维埃政府”互相印证，故选择B选项。","explanation":"官方示例只要求两个信息加推理；把其余选项为什么错说出来，说服力更强。"},{"type":"essay","tag":"材料分析题","source":"2025年福建中考·历史第29题","kind":"材料分析题","material":"人工智能（AI）是引领未来的战略性技术。为完成老师布置的学习任务，某同学用“反映第一次国共合作的诗句”这一指令，利用单一AI生成了如下结果，并直接作为自己的答案使用：\n“反映第一次国共合作的诗句是董必武在重访嘉兴南湖后题下的‘革命声传画舫中，诞生共党导工农。重来正值清明节，烟雨迷蒙访旧踪’。这首诗反映了中国共产党第一次全国代表大会在嘉兴南湖的召开，标志着中国共产党正式成立，也标志着第一次国共合作的开始。”","stem":"根据材料并结合所学知识，说明在历史学习中如何正确看待和使用人工智能。（8分）","points":[{"text":"辩证看待：人工智能能提供有效参考信息，但也可能出现杜撰史实、逻辑错误","score":2},{"text":"指出正确信息：董必武诗句反映了中共一大的召开","score":2},{"text":"指出错误：中共一大与第一次国共合作无关（国共合作正式形成的标志是1924年国民党一大）","score":2},{"text":"正确使用：不盲目依赖，交叉比对多种回答、用权威史料相互印证，不用AI取代个人思考","score":2}],"score":8,"sample":"人工智能发展是重大战略机遇，在历史学习中我们需辩证地看待人工智能。它在提供有效参考信息的同时，也可能出现杜撰史实、逻辑错误等情况。据材料可知，人工智能提供了董必武的诗句、其诗句反映了中共一大的召开等正确信息；但也给出了“标志着第一次国共合作的开始”等错误信息和推理。因此，我们可以运用人工智能帮助学习，但不宜盲目依赖，应注意采用交叉比对多种人工智能回答、使用权威史料相互印证等方式，减少谬误；更不宜用人工智能取代个人思考。","explanation":"1924年国民党一大召开，标志着第一次国共合作正式形成；1921年中共一大宣告中国共产党成立。"}]}]},{"id":"xiaosimen-lishi-4","group":"历史","subject":"历史","term":"八年级下册","title":"历史 · 八年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第18题","stem":"提取关键信息是学习历史的方法之一。与“1956年”“社会主义基本制度建立”“进入社会主义初级阶段”等关键信息相吻合的历史史实是（ ）","options":[{"key":"A","text":"土地改革的完成"},{"key":"B","text":"通过《中华人民共和国宪法》"},{"key":"C","text":"三大改造的基本完成"},{"key":"D","text":"第一个五年计划的超额完成"}],"answer":"C","explanation":"三大改造于1956年底完成，标志着生产资料私有制转变为公有制，社会主义基本制度确立，我国进入社会主义初级阶段；土地改革完成于1952年，时间不符；1954年第一届全国人大通过《中华人民共和国宪法》，确立了人民代表大会制度；第一个五年计划侧重工业化建设，于1957年完成。"},{"type":"choice","tag":"Claude 精选","source":"改编自2024年福建中考·历史第17题（表格转文字）","stem":"下表是中国交通里程变化情况（部分）：1978年公路89万公里、高速公路0、铁路5.17万公里、高速铁路0；2023年公路525.7万公里、高速公路18.4万公里、铁路15.9万公里、高速铁路4.5万公里。该表说明我国（ ）。","options":[{"key":"A","text":"国防科技日新月异"},{"key":"B","text":"交通建设飞速发展"},{"key":"C","text":"消费结构不断优化"},{"key":"D","text":"工业体系已现雏形"}],"answer":"B","explanation":"从1978年到2023年，我国公路、铁路里程迅速增长，高速公路、高速铁路从无到有，迅速增长，说明我国交通建设飞速发展。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第18题","stem":"1978年10月，通用公司董事长向中方建议，采用“中外合资”的形式共同办个企业，要赚一起赚，要赔一起赔。复出不久的邓小平迅速批示“合资经营可以办”，合资企业便由此而来。这体现出（ ）","options":[{"key":"A","text":"发展社会主义需要解放思想"},{"key":"B","text":"社会主义市场经济体制建立"},{"key":"C","text":"经济特区稳步建设"},{"key":"D","text":"城市改革全面展开"}],"answer":"A","explanation":"1978年邓小平迅速批准中外合资经营这一新生事物，体现了改革开放之初解放思想、发展社会主义的精神。社会主义市场经济体制建立于1992年后，经济特区、城市改革均非本题主旨。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第19题","stem":"2024年珠海航展中，我国“陆、海、空、天、电、网”全领域大国重器集中亮相，红旗-19、歼-35A、歼-20S等新型装备首次展出。这反映出我国（ ）","options":[{"key":"A","text":"经济总量稳居世界第二"},{"key":"B","text":"外交成就显著"},{"key":"C","text":"重视科技自立自强"},{"key":"D","text":"贸易伙伴增加"}],"answer":"C","explanation":"全领域大国重器与新型装备集中亮相，反映我国重视科技自立自强、国防科技实力提升。材料未涉及经济总量、外交成就与贸易伙伴。"},{"type":"choice","tag":"Claude 精选","source":"2025年云南省中考·历史第17题","stem":"新中国成立后，国家对少数民族古籍文献进行搜集、整理和出版，其中出版的《格萨尔王传》《江格尔》《玛纳斯》三大英雄史诗是世界文化艺术宝库中的瑰宝。以上工作（ ）","options":[{"key":"A","text":"传承和发展了少数民族文化"},{"key":"B","text":"提高了民族地区的科技水平"},{"key":"C","text":"提升了民族地区的教育水平"},{"key":"D","text":"保障了少数民族的政治权利"}],"answer":"A","explanation":"《格萨尔王传》《江格尔》《玛纳斯》是藏族、蒙古族、柯尔克孜族的经典英雄史诗，属于少数民族传统文化的重要组成部分。新中国成立后对这些古籍文献的搜集、整理和出版，直接保护了少数民族的文化遗产，使其得以传承并在当代社会继续发展。题干工作属于文化领域，未涉及科技、教育和政治权利。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年江苏省镇江市中考·历史第12题（表格转文字）","stem":"如下表为某历史专著第五章节的目录，其中▲处的标题最有可能是（ ）第五章：▲；一、“全世界人民包括美国人民都是我们的朋友”；二、“全世界人民的胜利，美帝国主义的惨败”；三、“揭开中日两国关系史上新的一页”。","options":[{"key":"A","text":"沿海经济开放区的设立"},{"key":"B","text":"“一国两制”的提出"},{"key":"C","text":"打开对外关系的新局面"},{"key":"D","text":"祖国统一大业的实现"}],"answer":"C","explanation":"三个子标题均涉及中美、中日关系，结合所学可知，这对应20世纪70年代中国外交的重大突破：1971年恢复联合国合法席位、1972年尼克松访华（中美关系走向正常化）、1972年中日建交，这些事件共同体现“打开对外关系的新局面”；经济开放区属于改革开放后的经济措施，与外交无关；“一国两制”和祖国统一聚焦国家统一问题，与中美关系和中日关系关系不大。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省威海市中考·历史第12题","stem":"家书带有时代的特征。下面这封家书（节选）反映的时代背景是（ ）修善吾弟：……知道你在部队很好，家中人口都很平安……已分到一石七斗田，田也很好……你在外面打美国鬼子，我们在家中受到农会和政府的优待照顾。一九五二年七月八日","options":[{"key":"A","text":"人民解放战争的胜利"},{"key":"B","text":"巩固新生的人民共和国"},{"key":"C","text":"社会主义的艰辛探索"},{"key":"D","text":"全面建成小康社会"}],"answer":"B","explanation":"家书时间为1952年，信中提及“分到一石七斗田”对应土地改革，土地改革将地主土地分配给农民，1952年基本完成，而“打美国鬼子”指抗美援朝，这两项均为巩固新生政权的措施，所以时代背景是巩固新生的人民共和国；解放战争在1949年已结束；社会主义探索始于1956年三大改造完成之后；全面建成小康社会是第一个百年奋斗目标。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省聊城市中考·历史第16题","stem":"太平天国运动、辛亥革命、中国恢复在联合国的合法席位均发生在农历辛亥年。串联这三个重大历史事件，可以得出的主题是（ ）","options":[{"key":"A","text":"思想启蒙"},{"key":"B","text":"救亡图存"},{"key":"C","text":"民族复兴"},{"key":"D","text":"西学东渐"}],"answer":"C","explanation":"太平天国运动沉重打击了清朝统治和外国侵略势力；辛亥革命推翻了清王朝的统治，结束了中国长达两千多年的封建君主专制制度，建立了中华民国；1971年10月25日，第26届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，提高了中国的国际地位。综合来看，这三个事件都围绕着中华民族的命运展开，都体现了中国人民为实现民族独立、国家富强、民族复兴而进行的不懈努力；思想启蒙、救亡图存、西学东渐都只涉及其中一个侧面，不是最核心的主题。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第20题","stem":"“大包干、大包干，直来直去不拐弯，保证国家的，留足集体的，剩下都是自己的。”这句顺口溜反映的政策最先实行的省份是（ ）","options":[{"key":"A","text":"安徽省"},{"key":"B","text":"山东省"},{"key":"C","text":"辽宁省"},{"key":"D","text":"广东省"}],"answer":"A","explanation":"这句顺口溜反映的是家庭联产承包责任制，最早于1978年由安徽凤阳小岗村农民首创实行，后在全国推广；山东省不是家庭联产承包责任制最先实行的省份；辽宁以工业为主，并非此政策最先实行地；广东主要是改革开放中经济特区等政策的先行地，和家庭联产承包责任制首创无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省南充市中考·历史（原始题号未标注）","stem":"下表是1953—1957年工业生产发展的部分情况，该表可用于说明我国（ ）工业生产年平均增长速度：中国18%，英国4.1%，美国2.8%；增产400万吨钢所用时间：中国5年，英国24年，美国15年","options":[{"key":"A","text":"工业发展水平世界领先"},{"key":"B","text":"“一五”计划取得的成就"},{"key":"C","text":"国民经济调整任务完成"},{"key":"D","text":"社会主义制度的初步建立"}],"answer":"B","explanation":"1953—1957年是“一五”计划时期，表格中我国工业生产年平均增长速度、增产400万吨钢所用时间等数据，体现出“一五”计划期间我国工业快速发展，取得显著成就。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省苏州市中考·历史（原始题号未标注）","stem":"读下表，国家实行的这项政策是（ ）时间：1956.7-1966.9；对象：公私合营企业私股股东；措施：发放股息；年息：5厘","options":[{"key":"A","text":"减租减息政策"},{"key":"B","text":"手工业合作化"},{"key":"C","text":"赎买政策"},{"key":"D","text":"扩大企业自主权"}],"answer":"C","explanation":"1956年7月至1966年9月，国家向公私合营企业私股股东发放股息（年息5厘），这是社会主义改造中对资本主义工商业实行的赎买政策。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考·历史（原始题号未标注）","stem":"“新中国成立初期，百废待兴，用于五年计划建设的有限财力，如果平均使用，可能一事无成。中共中央经过反复权衡和深入讨论，作出了优先发展重工业的决策。”这说明第一个五年计划（ ）","options":[{"key":"A","text":"改变了农业至上的传统观念"},{"key":"B","text":"实现各行业的均衡协调发展"},{"key":"C","text":"改变了中国工业落后的面貌"},{"key":"D","text":"体现了中国国情的客观要求"}],"answer":"D","explanation":"在当时中国经济基础薄弱、财力有限的国情下，优先发展重工业是符合实际情况的决策；第一个五年计划只是初步改变了中国工业落后的面貌，“改变了”表述不准确。"},{"type":"choice","tag":"Claude 精选","source":"2025年甘肃省平凉市中考·历史（原始题号未标注）","stem":"20世纪50年代后期至60年代前期，在麦地稻田、车间矿洞、水渠大坝、茫茫荒原，中国人民进行各种“大会战”。“抓晴天，抢阴天，小风小雪是好天，汽灯底下是白天，争取一天当两天！”“宁肯少活20年，拼命也要拿下大油田！”等成为时代标语。这反映出（ ）","options":[{"key":"A","text":"国民经济恢复工作取得了初步成效"},{"key":"B","text":"农业合作化运动极大解放了农村生产力"},{"key":"C","text":"举国支援抗美援朝战争的坚定决心"},{"key":"D","text":"中国人民全面建设社会主义的高昂热情"}],"answer":"D","explanation":"题干时间是20世纪50年代后期至60年代前期，对应全面建设社会主义时期（1956—1966年），材料内容体现了这时期中国人民在工业（如大庆油田开发）、农业等领域高涨的建设热情。"},{"type":"choice","tag":"Claude 精选","source":"2025年贵州省贵阳市中考·历史（原始题号未标注）","stem":"下列处应填写的人物分别是（ ）1960年，某人参加中国人民解放军，多次立功受奖。他以公而忘私、助人为乐的共产主义风格和言行一致的工作作风，成为全国人民学习的榜样。1962年，某人任河南兰考县委书记，为了改变当地的落后面貌，虽然身患重病，仍顽强工作，直到生命的最后一息，被人民称颂为“党的好干部”。","options":[{"key":"A","text":"王进喜、雷锋"},{"key":"B","text":"雷锋、焦裕禄"},{"key":"C","text":"王进喜、焦裕禄"},{"key":"D","text":"雷锋、邓稼先"}],"answer":"B","explanation":"雷锋是解放军战士，以无私奉献闻名；焦裕禄是兰考县委书记，带病工作直至去世。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省自贡市中考·历史","stem":"科技兴则民族兴，科技强则国家强。改革开放以来，墨子“传信”、神舟飞天、高铁奔驰、“天眼”探空、北斗组网、超算“发威”、C919首飞、“福建舰”下海，中国科技全方位突破。这反映出（ ）","options":[{"key":"A","text":"生物科学技术突破"},{"key":"B","text":"文化事业迅速发展"},{"key":"C","text":"对外开放日益扩大"},{"key":"D","text":"综合国力不断提升"}],"answer":"D","explanation":"科技是综合国力的重要组成部分，中国科技全方位突破反映综合国力不断增强。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-new-china-consolidation","stem":"土地改革完成后，农村土地归","options":[{"key":"A","text":"地主所有"},{"key":"B","text":"农民所有"},{"key":"C","text":"集体所有"},{"key":"D","text":"国家所有"}],"answer":"B","explanation":"土地改革使农民获得土地；后来通过农业合作化才走上集体化。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-first-plan-three-transformations","stem":"标志着我国社会主义基本制度确立的是","options":[{"key":"A","text":"中华人民共和国成立"},{"key":"B","text":"土地改革基本完成"},{"key":"C","text":"三大改造基本完成"},{"key":"D","text":"第一个五年计划完成"}],"answer":"C","explanation":"问工业化起步想到一五计划；问社会主义基本制度确立，想到 1956 年底三大改造基本完成。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-reform-and-opening","stem":"十一届三中全会后，农村推行家庭联产承包责任制。下列说法正确的是","options":[{"key":"A","text":"把集体土地变为农民私有"},{"key":"B","text":"恢复了人民公社制度"},{"key":"C","text":"当年就建成了社会主义市场经济体制"},{"key":"D","text":"土地仍归集体所有，农民承包经营"}],"answer":"D","explanation":"家庭联产承包责任制没有把集体土地变为私有；1992 年提出的是建立社会主义市场经济体制的目标。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-prc-diplomacy","stem":"1971 年，我国外交取得的重大成就是","options":[{"key":"A","text":"恢复在联合国的合法权利"},{"key":"B","text":"首次加入联合国"},{"key":"C","text":"中美正式建交"},{"key":"D","text":"参加万隆会议"}],"answer":"A","explanation":"1971 年是恢复合法权利，不是首次加入；1979 年中美正式建交，1955 年万隆会议。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-autonomy-special-regions","stem":"香港、澳门回归祖国后实行的是","options":[{"key":"A","text":"联邦制"},{"key":"B","text":"“一国两制”，设立特别行政区，实行高度自治"},{"key":"C","text":"民族区域自治制度"},{"key":"D","text":"人民公社制度"}],"answer":"B","explanation":"同有“自治”二字：民族区域自治用于少数民族聚居区，港澳特别行政区依据“一国两制”实行高度自治。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"1953—1957年，我国实施第一个五年计划，基本任务是集中主要力量发展____。","answer":["重工业"],"explanation":"“一五”计划期间，长春第一汽车制造厂生产出第一辆国产汽车。"},{"type":"blank","stem":"1964年，我国第一颗____爆炸成功；1970年，第一颗人造地球卫星“____”发射成功。","answer":["原子弹","东方红一号"],"explanation":"“两弹一星”元勋邓稼先被称为“两弹元勋”。"},{"type":"blank","stem":"1980年，我国在深圳、珠海、汕头和____设立经济特区。","answer":["厦门"],"explanation":"厦门经济特区在福建。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2026年福建中考·历史第30题(2)","kind":"材料分析题","material":"图7 纺线女子（清）；图8 大生产运动中妇女在纺线（抗战时期）；图9 碳纤维生产车间的纺织工人（2021年）。","stem":"根据材料并结合所学知识，从劳动者和劳动工具的角度概括推进国家发展的要素。（6分）","points":[{"text":"劳动者角度：技术的提升、理念的进步、积极性的提高","score":2},{"text":"劳动者角度：组织形式的发展、劳动环境的改善","score":1},{"text":"劳动工具角度：劳动工具的进步","score":2},{"text":"劳动工具角度：先进劳动工具的普及","score":1}],"score":6,"sample":"","explanation":"分角度作答：先写“劳动者角度：……”，再写“劳动工具角度：……”，阅卷时一目了然。"},{"type":"essay","tag":"材料分析题","source":"2026年福建中考·历史第31题(2)","kind":"材料分析题","material":"材料一：19世纪末，列强迫使清政府同意其在势力范围内修筑铁路，铁路的经营、所有和收入均归于列强，修路过程充满对中国人民的压迫。\n材料二：2021年，中国与老挝合作建设的中老铁路开通运营，这是老挝的第一条现代化铁路。中老铁路项目为老挝建设了75个隧道、167座桥梁，在当地购买超50亿元材料物资，带动11万人次就业，老挝旅游业也飞速发展。中方还为老挝搭建多层次、广覆盖的培育体系，培养出大量专业技术人才。——据《瞭望》等","stem":"综合上述材料并结合所学知识，说明中老铁路建设的意义。（8分）","points":[{"text":"促进区域内经济水平提升（基础设施、就业、旅游业）","score":2},{"text":"推动世界经济发展，增进民生福祉","score":2},{"text":"有利于推进区域稳定和安全，推动世界和平；促进双方文化交流、培养人才","score":2},{"text":"展现大国担当，为国家间合作提供平等互利、合作共赢的中国智慧和中国方案（与列强修路形成对比）","score":2}],"score":8,"sample":"","explanation":"中老铁路是“一带一路”标志性工程。与近代列强掠夺式修路相比，体现了平等互利、合作共赢。"}]}]},{"id":"xiaosimen-lishi-5","group":"历史","subject":"历史","term":"九年级上册","title":"历史 · 九年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第18题","stem":"在数千年的时间里，为建造数量众多、工程浩大的金字塔，法老对劳动力、财政和建筑技术的控制达到令人惊讶的地步。这反映了古埃及（ ）。","options":[{"key":"A","text":"国王权力至上"},{"key":"B","text":"法律体系完备"},{"key":"C","text":"军事实力强大"},{"key":"D","text":"医学成就辉煌"}],"answer":"A","explanation":"法老作为全国最高的统治者，集军、政、财、神等大权于一身。金字塔的修建，反映了古埃及国王的无限权力。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第21题","stem":"文艺复兴时期，意大利“分立为五州，各自为政”，市民文化发育较早，“文艺发达于民间，其流广而浅”；法国已建立封建君主专制国家，“文艺渊源于宫廷，其流狭而深”。这反映出（ ）","options":[{"key":"A","text":"市民阶层兴起"},{"key":"B","text":"思想传播深受环境影响"},{"key":"C","text":"王权受到限制"},{"key":"D","text":"国情差异导致政体不同"}],"answer":"B","explanation":"同一时期的文艺复兴，在意大利与法国呈现出民间与宫廷两种不同面貌，说明思想传播深受所处环境影响。材料比较的是文艺形态差异，而非市民阶层兴起、王权受限与政体差异。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第20题","stem":"乌尔是古代两河流域城市，出土了装饰有阿富汗特产青金石的竖琴，还出土了刻有动物图案的印度文明印章。据此推知，当时两河流域（ ）","options":[{"key":"A","text":"城市面积广阔"},{"key":"B","text":"阶层分化明显"},{"key":"C","text":"楔形文字出现"},{"key":"D","text":"存在商贸活动"}],"answer":"D","explanation":"两河流域城市出土了阿富汗特产青金石与印度文明印章，说明当时两河流域与阿富汗、印度之间存在商贸往来。材料未涉及城市面积、阶层分化与楔形文字。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·历史第23题","stem":"英国资产阶级革命期间，议会虽下令拍卖王党土地，但并不禁止王党参与赎回。这（ ）","options":[{"key":"A","text":"表明“君权神授”受到推崇"},{"key":"B","text":"客观上有利于社会平稳转型"},{"key":"C","text":"体现出议会有名无实"},{"key":"D","text":"说明王党重掌政权"}],"answer":"B","explanation":"议会拍卖王党土地又允许王党赎回，缓和了革命的激烈程度，客观上有利于英国社会平稳转型。材料否定“君权神授”，议会能下令拍卖土地说明议会有实权，王党并未重掌政权。"},{"type":"choice","tag":"Claude 精选","source":"2025年云南省中考·历史第20题","stem":"根据同学们整理的“城邦”“抽签”“公民大会”“陪审法庭”等关键词，可以推断他们的学习内容是（ ）","options":[{"key":"A","text":"等级森严的种姓制度"},{"key":"B","text":"雅典的民主政治"},{"key":"C","text":"西欧的封君封臣制度"},{"key":"D","text":"日本的大化改新"}],"answer":"B","explanation":"雅典是古希腊典型的城邦国家，其民主政治的核心是公民直接参与国家管理：“公民大会”是最高权力机构，“抽签”体现官职由公民抽签产生，“陪审法庭”由公民组成陪审团，这些关键词完全符合雅典民主政治的特征。种姓制度是古代印度的等级制度，封君封臣制度是中世纪西欧的封建等级制度，大化改新是7世纪日本模仿唐朝的改革。"},{"type":"choice","tag":"Claude 精选","source":"2025年云南省中考·历史第23题","stem":"1689年英国议会通过《权利法案》，君主立宪制逐渐形成。1861年俄国颁布废除农奴制的法令，农奴获得了人身自由。以上政治变革顺应的历史潮流是（ ）","options":[{"key":"A","text":"世界市场的形成与发展"},{"key":"B","text":"资本主义制度的建立与扩展"},{"key":"C","text":"国际共产主义运动兴起"},{"key":"D","text":"民族独立运动的兴起和发展"}],"answer":"B","explanation":"英国确立君主立宪制，属于资本主义政治制度的建立；俄国废除农奴制为资本主义发展创造条件，属于资本主义制度的扩展，因此题干反映的是资本主义制度的建立与扩展；世界市场的形成涉及经济全球化，与题干政治变革无直接关联；国际共产主义运动兴起是指无产阶级反抗资产阶级的斗争；民族独立运动与殖民地斗争有关，与题意无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考·历史第10题","stem":"“市场总是在扩大，需求总是在增加。甚至工场手工业也不再能满足需要了。于是，蒸汽和机器引起了工业生产的革命。”这表明工业革命源于（ ）","options":[{"key":"A","text":"原有生产方式不能满足市场需求"},{"key":"B","text":"新航路开辟为世界市场形成创造条件"},{"key":"C","text":"“光荣革命”后资产阶级掌握政权"},{"key":"D","text":"殖民扩张推动欧洲资本原始积累完成"}],"answer":"A","explanation":"市场需求扩大导致工场手工业无法满足，从而引发工业革命，材料强调“工场手工业不能满足需求”直接推动技术革新（蒸汽机与机器），说明工业革命源于原有生产方式（工场手工业）与市场需求之间的矛盾；新航路开辟是市场扩大的背景，但材料未直接提及；“光荣革命”属于政治前提，与题干无关；殖民扩张是资本积累的途径，但材料未涉及资本问题。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省镇江市中考·历史第16题","stem":"9世纪初，查理曼大帝签署了一道命令，指导管家的庄园工作，其中规定：管家必须保证庄园里有铁匠、鞋匠、伐木者、刀剑制造者、渔民、织网者、面包师等各种职业人员。据此可知，庄园（ ）","options":[{"key":"A","text":"经济自给自足"},{"key":"B","text":"司法公平公正"},{"key":"C","text":"属于管家所有"},{"key":"D","text":"保护市民利益"}],"answer":"A","explanation":"庄园是一个独立的自给自足的经济和政治单位，题干中提到庄园里有铁匠、鞋匠、伐木者、刀剑制造者、渔民、织网者、面包师等各种职业人员，这意味着庄园能够自己生产各种生产工具、生活用品以及食物等，基本满足庄园内人们的生产生活需求，很少需要对外交换，体现了经济上的自给自足；庄园设有庄园法庭，主持法庭的是领主或他的管家，庄园法庭主要维护领主利益，不能说司法公平公正；查理曼大帝签署的命令是让管家管理庄园工作，而不是将庄园归管家所有；庄园与保护市民利益无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省威海市中考·历史第18题","stem":"1892年，恩格斯说：“某一国家的大工业愈发展，该国工人想要弄清他们作为工人阶级在有产阶级面前所处地位的愿望也就愈强烈，工人中间的社会主义运动也就愈扩大，对《宣言》的需求也就愈增长。”这里的“《宣言》”是指（ ）","options":[{"key":"A","text":"《共产党宣言》"},{"key":"B","text":"《独立宣言》"},{"key":"C","text":"《人权宣言》"},{"key":"D","text":"《解放黑人奴隶宣言》"}],"answer":"A","explanation":"《共产党宣言》是马克思、恩格斯为共产主义者同盟起草的纲领，1848年发表，标志着科学社会主义诞生，直接指导工人运动；《独立宣言》是美国独立战争文献，与社会主义无关；《人权宣言》是法国大革命产物，属资产阶级革命范畴；《解放黑人奴隶宣言》是美国内战文件，涉及废除奴隶制，但非社会主义内容。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省聊城市中考·历史第20题","stem":"斯塔夫里阿诺斯说：“由于日本具有向伟大的中国文化世界借用某些东西的悠久传统，因而，19世纪在同样地借用西方世界的东西时，发生的冲突较少、痛苦较小。”他着重分析的是日本明治维新的（ ）","options":[{"key":"A","text":"改革历程"},{"key":"B","text":"有利因素"},{"key":"C","text":"深远影响"},{"key":"D","text":"关键措施"}],"answer":"B","explanation":"题干中提到日本有向中国文化借用东西的悠久传统，这使得在19世纪向西方世界借用东西时冲突少、痛苦小，这是日本进行明治维新时自身所具备的一种有利条件，属于明治维新的有利因素；改革历程主要涉及明治维新从开始到结束所经历的一系列事件和阶段；深远影响是指明治维新对日本在政治、经济、文化、社会等多方面在较长时间内产生的效果；关键措施是指明治维新过程中实施的具体重要政策，如殖产兴业、文明开化等，题干没有阐述这些具体措施。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省连云港市中考·历史第9题","stem":"14世纪中叶，意大利的佛罗伦萨、威尼斯等地，工商业有了一定的发展，出现了资本主义萌芽。这段材料反映了文艺复兴的（ ）","options":[{"key":"A","text":"历史背景"},{"key":"B","text":"运动过程"},{"key":"C","text":"事件性质"},{"key":"D","text":"重要影响"}],"answer":"A","explanation":"材料指出14世纪意大利工商业发展及资本主义萌芽的出现，是文艺复兴产生的社会经济条件。资本主义萌芽为新兴资产阶级的形成奠定基础，成为推动文艺复兴兴起的根本原因；运动过程涉及事件发展，材料涉及的是运动的历史背景；事件性质描述运动本质；重要影响强调结果，材料涉及的是运动的历史背景。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第21题","stem":"下列内容是某同学历史学习笔记的一部分，据此分析其学习主题是（ ）（笔记：基督教的兴起和法兰克王国；西欧庄园；中世纪城市和大学的兴起；拜占庭帝国和《查士丁尼法典》）","options":[{"key":"A","text":"古代亚非文明"},{"key":"B","text":"古代欧洲文明"},{"key":"C","text":"封建时代的欧洲"},{"key":"D","text":"封建时代的亚洲"}],"answer":"C","explanation":"基督教的兴起、法兰克王国对欧洲影响深远，西欧庄园是独立的政治、经济单位，中世纪城市和大学的兴起是商品经济高度发达的表现，拜占庭帝国的《查士丁尼法典》奠定了欧洲民法典的基础，这些均是封建时代欧洲的主要内容；古代亚非文明主要涉及古代埃及、古代两河流域、古代印度等；古代欧洲文明主要涉及希腊城邦、罗马城邦和罗马帝国、希腊罗马古典文化等；封建时代的亚洲主要涉及古代日本以及阿拉伯帝国。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省自贡市中考·历史第13题","stem":"有学者认为：1492年开始了一场引人注目的大交换，这里的“大交换”指“新大陆”和“旧大陆”之间各种植物、动物以及疾病、宗教、文化、人口的互相传播和交流。这种交换始于（ ）","options":[{"key":"A","text":"郑和下西洋"},{"key":"B","text":"哥伦布发现美洲"},{"key":"C","text":"麦哲伦船队环球航行"},{"key":"D","text":"三角贸易的开始"}],"answer":"B","explanation":"1492年哥伦布发现美洲新大陆，打破了美洲与亚欧大陆相对隔绝的状态，出现新大陆和旧大陆之间植物、动物以及疾病、宗教、文化、人口的互相传播和交流，即“大交换”。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省梅州市兴宁市宋声学校中考一模·历史","stem":"12世纪建立了巴黎大学、牛津大学；13世纪出现了剑桥大学；14世纪又有罗马大学、佛罗伦萨大学和维也纳大学相继建立起来。这些大学的名称充分说明中世纪大学（ ）","options":[{"key":"A","text":"与城市的兴起密切相关"},{"key":"B","text":"享有完全自由和自治权"},{"key":"C","text":"受益于商品经济的发展"},{"key":"D","text":"满足了社会分工的需要"}],"answer":"A","explanation":"中世纪大学大多建立在城市中，反映了城市作为文化和教育中心的地位，这些大学都以城市命名，如巴黎、牛津、剑桥、罗马、佛罗伦萨和维也纳，表明它们的建立与这些城市的兴起和发展密切相关。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省梅州市兴宁市宋声学校中考一模·历史","stem":"“它由一个内陆国家扩张成为一个濒临海洋的强国。它开始告别东方，走向西方；告别中古，走向近代；告别愚昧与落后，迈进现代化的门槛。”此观点适合评价（ ）","options":[{"key":"A","text":"彼得一世改革"},{"key":"B","text":"美国南北战争"},{"key":"C","text":"日本明治维新"},{"key":"D","text":"俄国十月革命"}],"answer":"A","explanation":"彼得一世改革前，俄国是一个内陆国家，经济文化落后。彼得一世改革向西方学习，在军事、经济、文化教育等方面进行了一系列改革，使俄国成为濒临海洋的强国，开启了俄国近代化的进程。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-ancient-civilization-map","stem":"《汉谟拉比法典》是哪个古代文明留下的","options":[{"key":"A","text":"古代印度"},{"key":"B","text":"古希腊"},{"key":"C","text":"古巴比伦"},{"key":"D","text":"古埃及"}],"answer":"C","explanation":"尼罗河流域古埃及有金字塔；两河流域古巴比伦留下《汉谟拉比法典》。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-renaissance-ocean-routes","stem":"文艺复兴的核心思想是","options":[{"key":"A","text":"君权神授"},{"key":"B","text":"三权分立"},{"key":"C","text":"社会契约"},{"key":"D","text":"人文主义"}],"answer":"D","explanation":"文艺复兴首先在意大利兴起，人文主义强调人的价值。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-atlantic-revolution-documents","stem":"1689 年英国颁布、用来限制王权的法律文件是","options":[{"key":"A","text":"《权利法案》"},{"key":"B","text":"《独立宣言》"},{"key":"C","text":"《人权宣言》"},{"key":"D","text":"1787 年宪法"}],"answer":"A","explanation":"《权利法案》限王权；《独立宣言》宣告美国独立；《人权宣言》是法国的。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-first-industrial-revolution","stem":"第一次工业革命首先开始于","options":[{"key":"A","text":"法国的钢铁工业"},{"key":"B","text":"英国的棉纺织业"},{"key":"C","text":"美国的电力工业"},{"key":"D","text":"德国的化学工业"}],"answer":"B","explanation":"第一次工业革命始于 18 世纪中期的英国，先在棉纺织业展开；电力广泛应用是第二次工业革命的线索。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-marxism-and-commune","stem":"标志着马克思主义诞生的是","options":[{"key":"A","text":"1917 年十月革命"},{"key":"B","text":"1864 年第一国际成立"},{"key":"C","text":"1848 年《共产党宣言》发表"},{"key":"D","text":"1871 年巴黎公社建立"}],"answer":"C","explanation":"辨认马克思主义诞生的标志，要找《共产党宣言》的发表；巴黎公社是建立工人阶级政权的尝试。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"古代埃及的统治者称为“____”，金字塔是他们的陵墓。","answer":["法老"],"explanation":"古巴比伦《汉谟拉比法典》是迄今已知世界上第一部比较完备的成文法典。"},{"type":"blank","stem":"公元前27年，____建立元首制，罗马进入帝国时代。","answer":["屋大维"],"explanation":"476年西罗马帝国灭亡。"},{"type":"blank","stem":"1776年7月4日，大陆会议通过《____》，宣告美国诞生。","answer":["独立宣言"],"explanation":"独立宣言由杰斐逊起草，华盛顿任大陆军总司令。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2025年福建中考·历史第31题(1)","kind":"材料分析题","material":"1505年，达·芬奇写出了航空科学的开山之作《论鸟的飞行》。18世纪，法国孟格菲兄弟进行了热气球载人实验，后来留下一句名言“我们将这样走到星星那边”。不久，人类又开始用较轻的氢气制造气球。1900年，齐柏林飞艇试飞成功。——摘编自吴军《全球科技通史》","stem":"根据材料一，概括人类得以翱翔天际的原因。（4分）","points":[{"text":"人类对自由飞翔的渴望","score":1},{"text":"科学理论的发展","score":1},{"text":"科学技术的进步","score":1},{"text":"不懈的探索精神","score":1}],"score":4,"sample":"","explanation":"“名言”体现渴望，《论鸟的飞行》体现理论，氢气球、飞艇体现技术进步，几百年的接力体现探索精神。"},{"type":"essay","tag":"简答题","source":"依据人教版九年级上册第15课《探寻新航路》编写","kind":"简答题","material":"","stem":"新航路开辟的原因有哪些？新航路的开辟产生了什么影响？（7分）","points":[{"text":"原因：欧洲商品经济发展，需要大量货币（黄金），《马可·波罗行纪》激起对东方财富的向往","score":2},{"text":"原因：奥斯曼土耳其控制东西方商路；造船技术、航海技术进步（指南针等）","score":2},{"text":"影响：使世界逐渐连成一个整体，促进了欧洲资本主义的发展","score":2},{"text":"影响：给美洲、非洲带来灾难（殖民掠夺、黑奴贸易）","score":1}],"score":7,"sample":"","explanation":"迪亚士到达好望角，哥伦布到达美洲，达·伽马到达印度，麦哲伦船队完成环球航行。"}]}]},{"id":"xiaosimen-lishi-6","group":"历史","subject":"历史","term":"九年级下册","title":"历史 · 九年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建中考·历史第26题","stem":"某一时期，苏俄私人工厂生产的多是农具、家具、衣物等用品用具和食盐、面包等食品，商业经营多围绕这些产品进行。这主要得益于（ ）。","options":[{"key":"A","text":"战时共产主义政策"},{"key":"B","text":"新经济政策"},{"key":"C","text":"社会主义工业化"},{"key":"D","text":"农业集体化"}],"answer":"B","explanation":"新经济政策明确规定中小企业和国家暂时无力兴办的企业允许私人经营，苏俄私人工厂多生产日常生活用品正是得益于此。"},{"type":"choice","tag":"Claude 精选","source":"改编自2024年山东省德州市中考·历史（表格转文字；原始题号未标注）","stem":"某历史社团设计了“滑向倾斜的世界——探战争之源”探究活动，分析下表数据可以得出（ ）1913—1914年主要列强的经济实力及其占有殖民地的情况：英国占世界工业生产总量14%，殖民地面积3350万平方千米，殖民地人口39350万人；沙俄2.6%、1740万平方千米、3320万人；法国6%、1060万平方千米、5550万人；德国16%、290万平方千米、1230万人；日本1%、30万平方千米、1920万人；美国38%、30万平方千米、970万人。","options":[{"key":"A","text":"工业革命推动了西方各国城市化进程"},{"key":"B","text":"资本主义国家间政治经济发展不平衡"},{"key":"C","text":"美国经济、军事实力已成为世界霸主"},{"key":"D","text":"三国同盟、三国协约两大集团已形成"}],"answer":"B","explanation":"英国在殖民地面积和人口上占优势，但在工业生产总量上，美国（38%）和德国（16%）远超英国（14%），显示出资本主义国家间政治经济发展不平衡的现象，而这一现象正是一战爆发的根本原因。材料未涉及城市化进程；材料仅展示经济实力和殖民地情况，未涉及军事实力；材料未涉及两大军事集团的形成。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·历史第27题","stem":"1940年，伦敦深陷德国空袭，丘吉尔夫人克莱门蒂娜去往教堂，恰逢教堂在进行激情澎湃的和平主义布道，她便厌恶地起身离开，尽管她的近亲也被德国俘虏，很可能性命不保。这体现出（ ）","options":[{"key":"A","text":"盟军暂时处于战略劣势"},{"key":"B","text":"英国政府坚持抗击侵略"},{"key":"C","text":"和平进程受到一定阻挠"},{"key":"D","text":"反法西斯立场弥足珍贵"}],"answer":"D","explanation":"丘吉尔夫人在伦敦遭空袭、近亲被俘的情况下仍厌恶和平主义布道、坚持抗战，体现出在法西斯侵略面前反法西斯立场弥足珍贵。材料讲的是个人立场，不是盟军战略态势、英国政府政策与和平进程。"},{"type":"choice","tag":"Claude 精选","source":"2024年内蒙古自治区赤峰市中考·历史（原始题号未标注）","stem":"一战所带来最直接、明显的后果就是人力、物力的巨大损失，其中直接死于战争的军人达900万人，另有2000多万人受伤，350万人留下终身残疾。据此可知，一战（ ）","options":[{"key":"A","text":"是人类历史上的灾难性战争"},{"key":"B","text":"从根本上动摇了欧洲的优势地位"},{"key":"C","text":"削弱了帝国主义的殖民力量"},{"key":"D","text":"促进了殖民地半殖民地民族觉醒"}],"answer":"A","explanation":"材料只列举了一战造成的大量人员伤亡：900万人战死、2000多万人受伤、350万人终身残疾，直接说明一战给人类带来了巨大灾难。B、C、D虽是史实，但材料没有体现。"},{"type":"choice","tag":"Claude 精选","source":"2024年山东省烟台市中考·历史（原始题号未标注）","stem":"由英法美操纵的会议在凡尔赛宫召开，列强为了实现各自目的尔虞我诈、矛盾重重，几经讨价还价，终于在1919年6月28日签署了《协约及参战各国对德和约》。随后协约国同其他战败国也相继签订了一系列条约，解决了欧洲、非洲和西亚战后秩序问题。由此可见，该会议（ ）","options":[{"key":"A","text":"确立的国际秩序由大国主导"},{"key":"B","text":"保障了战后永久和平"},{"key":"C","text":"消除了参战各国之间的矛盾"},{"key":"D","text":"体现了平等协商原则"}],"answer":"A","explanation":"巴黎和会由英法美等大国操纵，会议确立的一战后国际秩序由大国主导。巴黎和会没有保障永久和平（20多年后二战爆发），也没有消除各国矛盾，更谈不上平等协商。"},{"type":"choice","tag":"Claude 精选","source":"2024年江苏省盐城市中考·历史（原始题号未标注）","stem":"1942年1月，《联合国家宣言》宣告：'每一政府各自保证与本宣言签字国合作，并不与敌人缔结单独停战协定或和约'。该宣言中的'敌人'应包括（ ）","options":[{"key":"A","text":"美国"},{"key":"B","text":"日本"},{"key":"C","text":"英国"},{"key":"D","text":"苏联"}],"answer":"B","explanation":"《联合国家宣言》中的'敌人'指的是德、意、日法西斯侵略者。美国、英国、苏联都是宣言的签字国，不是敌人。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考·历史第13题","stem":"20世纪90年代以来，人类社会的很多方面都发生了很大变化。这表现在（ ）","options":[{"key":"A","text":"欧美主要国家开始推广大众教育"},{"key":"B","text":"互联网成为现代社会重要的基础设施"},{"key":"C","text":"日本开始跻身资本主义强国之列"},{"key":"D","text":"电力成为新的能源进入生产生活领域"}],"answer":"B","explanation":"20世纪90年代，互联网在全球迅速普及，成为现代社会重要基础设施，深刻改变人们生活、工作、交往等方式；欧美主要国家推广大众教育是在19世纪中后期；日本在20世纪50—70年代经济高速发展后，就已跻身资本主义强国之列；电力在19世纪70年代第二次工业革命中就开始成为新的能源进入生产生活领域。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省威海市中考·历史第19题","stem":"中国共产党早期领导人瞿秋白于1920年至1922年在俄国工作和生活，他曾生动地描述道：“回忆二三月间，我到俄人家里，黑面包是常餐便饭唯一食品，现在丰富多了……大多数劳动人民也受许多方便利益。”据此判断，促使这一变化出现的主要原因是俄国（ ）","options":[{"key":"A","text":"实行战时共产主义政策，采取余粮收集制"},{"key":"B","text":"实施新经济政策，实行自由贸易"},{"key":"C","text":"实施新政，通过《农业调整法》，稳定了农产品价格"},{"key":"D","text":"进行大规模的农业集体化运动，解决粮食问题"}],"answer":"B","explanation":"1921年，苏俄开始实施新经济政策，以粮食税代替余粮收集制，允许私人经营中小企业，实行自由贸易等，新经济政策的实施调动了生产者的积极性，促使国民经济稳步发展，人民生活水平得到改善，与题干中“现在丰富多了……大多数劳动人民也受许多方便利益”相符；战时共产主义政策实行余粮收集制，严重损害了农民的利益，而且物资极度匮乏；“新政”和《农业调整法》是美国罗斯福新政的内容，与俄国无关；苏联大规模的农业集体化运动开始于1929年，时间不符。"},{"type":"choice","tag":"Claude 精选","source":"2025年山东省聊城市中考·历史第25题","stem":"近年来，全球经济发展过程中出现了诸如英国脱欧，美国贸易保护、边境修墙、控制移民等现象。这些现象主要反映了当今世界的哪一趋势？（ ）","options":[{"key":"A","text":"经济区域化"},{"key":"B","text":"政治集团化"},{"key":"C","text":"文明趋同化"},{"key":"D","text":"逆全球化"}],"answer":"D","explanation":"逆全球化是指一些国家采取一系列措施，阻碍全球贸易、投资、人员流动等的自由化和一体化进程。英国脱欧使得欧洲一体化进程受阻，美国贸易保护限制了国际贸易的自由开展，边境修墙和控制移民限制了人员的自由流动，这些都体现了对全球化趋势的背离，反映了逆全球化的现象；经济区域化是指在一定区域范围内，地理位置邻近的国家或地区通过协议和条约建立区域经济合作组织；政治集团化强调国家在政治层面上的联合与结盟；文明趋同化是指不同文明之间相互交流、融合，在文化、价值观等方面呈现出相似或相近的趋势，题干内容并未涉及文明方面的趋同。"},{"type":"choice","tag":"Claude 精选","source":"2025年黑龙江省齐齐哈尔市中考·历史第24题","stem":"1942年1月，26个国家代表签署《联合国家宣言》，世界反法西斯同盟正式形成；1944年6月，美、英等盟军成功登陆法国诺曼底；1945年2月，雅尔塔会议召开，协调了盟军行动。上述材料共同反映出世界反法西斯战争胜利的最主要原因是（ ）","options":[{"key":"A","text":"反法西斯国家团结合作"},{"key":"B","text":"战争的正义性"},{"key":"C","text":"盟军军事实力逐渐强大"},{"key":"D","text":"正确战略战术"}],"answer":"A","explanation":"题干中的三个事件均体现反法西斯国家的联合行动：《联合国家宣言》标志同盟正式形成，诺曼底登陆是盟军协同作战的体现，雅尔塔会议协调了盟军战略。这些共同说明“团结合作”是胜利主因；“正义性”虽正确，但题干未直接体现；盟军军事实力、正确战略战术仅涉及军事层面，无法涵盖政治合作。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省中考模拟预测·历史（原始题号未标注）","stem":"1914年6月，奥匈帝国皇储斐迪南大公为了向塞尔维亚炫耀武力，到波斯尼亚检阅军队。6月28日，斐迪南大公夫妇在萨拉热窝被塞尔维亚族青年普林西普刺杀。这一事件成为第一次世界大战的（ ）","options":[{"key":"A","text":"开始标志"},{"key":"B","text":"转折点"},{"key":"C","text":"结束标志"},{"key":"D","text":"导火线"}],"answer":"D","explanation":"1914年6月28日萨拉热窝事件发生后，奥匈帝国以此为借口，在德国支持下向塞尔维亚宣战，随后欧洲列强纷纷卷入战争，萨拉热窝事件成为第一次世界大战的导火线。"},{"type":"choice","tag":"Claude 精选","source":"2025年重庆市开州区中考一模·历史（原始题号未标注）","stem":"一战后，通过巴黎和会和华盛顿会议，帝国主义列强建立了“凡尔赛—华盛顿体系”，它确立了帝国主义在欧洲、西亚、非洲、东亚以及太平洋地区的统治秩序。这“两次会议”（ ）","options":[{"key":"A","text":"维护了世界的和平与发展"},{"key":"B","text":"解决了帝国主义国家之间的矛盾"},{"key":"C","text":"都严重损害了中国的主权"},{"key":"D","text":"成功实现了美国称霸世界的野心"}],"answer":"C","explanation":"巴黎和会上把德国在中国山东的特权转让给日本，引发了中国的五四运动；华盛顿会议签订的《九国公约》使中国又恢复到几个帝国主义国家共同支配的局面，两次会议均损害了中国的主权。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省绵阳市中考模拟预测·历史（表转文字；原始题号未标注）","stem":"下表史事与结论对应正确的是（ ）A. 北约的成立——企图通过援助西欧恢复经济，稳定资本主义制度 B. 杜鲁门主义出台——美、苏战时同盟关系正式破裂，冷战开始 C. 不结盟运动兴起——世界形势发展的总趋势走向缓和，世界多极化趋势增强 D. 苏联的解体——标志着发展中国家已成为国际政治舞台上的一支重要力量","options":[{"key":"A","text":"北约的成立——企图通过援助西欧恢复经济，稳定资本主义制度"},{"key":"B","text":"杜鲁门主义出台——美、苏战时同盟关系正式破裂，冷战开始"},{"key":"C","text":"不结盟运动兴起——世界形势发展的总趋势走向缓和，世界多极化趋势增强"},{"key":"D","text":"苏联的解体——标志着发展中国家已成为国际政治舞台上的一支重要力量"}],"answer":"B","explanation":"1947年杜鲁门提出以“遏制共产主义”作为国家政治意识形态和对外政策的指导思想，即杜鲁门主义，它的出台标志着美苏战时同盟关系正式破裂、美苏之间冷战的开始；通过经济援助西欧恢复经济、稳定资本主义制度的是马歇尔计划。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽省合肥市中考一模·历史","stem":"1945年，美苏两国在朝鲜半岛以北纬38度线为界，分别接受日军投降，这就是“三八线”的来历。1961年，民主德国为阻止居民外流和西方势力的渗透，修筑了“反法西斯防卫墙”。这一“线”一“墙”的产生（ ）","options":[{"key":"A","text":"都是双方军事斗争的结果"},{"key":"B","text":"都预示世界局势趋向紧张"},{"key":"C","text":"都是美苏冷战的必然产物"},{"key":"D","text":"都推动了区域经济的发展"}],"answer":"B","explanation":"三八线是冷战初期美苏势力划分的直接结果，柏林墙本质上是美苏在欧洲对抗的产物，这都为后来朝鲜半岛的分裂、德国的分裂埋下了隐患，预示着世界局势趋向紧张；三八线是美苏协商划分，未发生直接军事冲突，1945年冷战尚未开始。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省梅州市兴宁市宋声学校中考一模·历史","stem":"1922年，在一次欧洲经济会议上，苏俄政府代表团声明：准备在经济上实行对外开放，把一部分森林、矿产资源甚至肥沃的耕地租让给外资经营开发，但拒绝任何不平等交易。这表明当时苏俄（ ）","options":[{"key":"A","text":"新经济政策得到落实"},{"key":"B","text":"与西方国家间的矛盾已消除"},{"key":"C","text":"工业化建设成就巨大"},{"key":"D","text":"建立了高度集中的经济体制"}],"answer":"A","explanation":"1922年苏俄新经济政策已经实施，自愿将资源转租给外国资本经营，是新经济政策的体现。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-russia-us-japan","stem":"1861 年俄国改革的主要内容是","options":[{"key":"A","text":"推翻沙皇统治"},{"key":"B","text":"废除黑人奴隶制"},{"key":"C","text":"学习唐朝制度"},{"key":"D","text":"废除农奴制"}],"answer":"D","explanation":"俄国是沙皇自上而下改革废除农奴制；美国用内战解决奴隶制问题。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-war-timelines","stem":"标志着世界反法西斯同盟形成的是","options":[{"key":"A","text":"1942 年《联合国家宣言》签署"},{"key":"B","text":"1945 年联合国成立"},{"key":"C","text":"1939 年德国进攻波兰"},{"key":"D","text":"1918 年第一次世界大战结束"}],"answer":"A","explanation":"1942 年签署宣言是战时组建反法西斯同盟；1945 年成立的是战后的联合国。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-soviet-nep","stem":"苏俄新经济政策的主要内容是","options":[{"key":"A","text":"实行余粮收集制"},{"key":"B","text":"以粮食税代替余粮收集制，允许一定范围的私人经营"},{"key":"C","text":"推行农业集体化"},{"key":"D","text":"优先发展重工业"}],"answer":"B","explanation":"新经济政策保留一定市场空间；农业集体化、优先发展重工业是后来斯大林时期的做法。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-roosevelt-new-deal","stem":"罗斯福新政的核心特点是","options":[{"key":"A","text":"政府完全放任市场"},{"key":"B","text":"实行计划经济体制"},{"key":"C","text":"加强国家对经济的干预"},{"key":"D","text":"废除资本主义制度"}],"answer":"C","explanation":"新政通过整顿金融、兴办公共工程、社会保障等加强国家干预，但没有改变资本主义制度。"},{"type":"choice","tag":"Claude 冲刺","kp":"lishi-cold-war-milestones","stem":"通常作为冷战开始标志的是","options":[{"key":"A","text":"1949 年北约成立"},{"key":"B","text":"1955 年华约成立"},{"key":"C","text":"1991 年苏联解体"},{"key":"D","text":"1947 年杜鲁门主义出台"}],"answer":"D","explanation":"杜鲁门主义出台标志冷战开始；华约成立标志两极格局形成；苏联解体标志冷战结束。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"1917年11月7日（俄历10月25日），俄国____革命取得胜利，建立了世界上第一个社会主义国家。","answer":["十月"],"explanation":"列宁领导了十月革命。"},{"type":"blank","stem":"第二次工业革命中，人类进入“____时代”；美国人____发明了电灯。","answer":["电气","爱迪生"],"explanation":"德国人卡尔·本茨制成内燃机驱动的汽车，美国莱特兄弟发明飞机。"},{"type":"blank","stem":"1945年，联合国正式成立，____是联合国最重要的机构，负责维护国际和平与安全。","answer":["安理会"],"explanation":"中国是安理会五个常任理事国之一。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"材料分析题","source":"2024年福建中考·历史第31题(1)","kind":"材料分析题","material":"五大湖地区一度是美国制造业的骄傲，但持续了两百年的污染问题一直无法得到解决。目前湖中发现了30000种在工业中常见的化合物，有500种对人体有害，其中致癌物芳香烃和能引起基因突变的诱变剂浓度很高。【图8】五大湖地区的工厂集群排放污水·19世纪末。——摘编自王斯德《世界通史》等","stem":"根据材料一，简析造成上述现象的原因。（4分）","points":[{"text":"未做好环境保护","score":2},{"text":"两次工业革命（制造业及化学工业的发展）带来的污染","score":2}],"score":4,"sample":"","explanation":"“制造业的骄傲”“工业中常见的化合物”“19世纪末”指向两次工业革命，尤其是第二次工业革命中化学工业的兴起。"},{"type":"essay","tag":"论述题","source":"2025年福建中考·历史第32题","kind":"论述题","material":"【图14 油画《百团大战》（沈嘉蔚、李如）】画面以长城为背景：近处是八路军战士奋勇冲锋、与日军激烈搏斗的场景，远处是城楼、烽烟，空中有飞机。\n【图15 照片《苏联红旗插上德国国会大厦》（哈尔杰伊）】近处是苏联红军战士在国会大厦顶部插上飘扬的苏联红旗，远处是硝烟弥漫、满目疮痍的柏林城。\n注：在绘画、摄影等视觉艺术中，创作者通过对不同景别（近景、中景、远景等）的运用，营造画面的空间感和氛围。近景能让观众清晰地看到细节，中景往往是作品的视觉中心，近景、中景多用于着重刻画人物或物体、突出作品主体；远景则用于表现广阔的背景或环境，让观众对整体场景有宏观的认识。——据中国人民革命军事博物馆等","stem":"任选一幅作品（写出作品名称即可），选择其中两个景别并结合所学史实，对该作品进行阐释。（要求：价值观正确，史论结合，逻辑清晰）（12分）","points":[{"text":"写出作品名称","score":1},{"text":"景别一：描述画面 + 结合史实（如1940年彭德怀指挥八路军发动百团大战 / 1945年4月柏林战役苏军攻入柏林）","score":4},{"text":"景别二：描述画面 + 结合史实（如长城象征中华民族不屈的抗战意志 / 柏林废墟反映战争残酷、法西斯德国覆灭）","score":4},{"text":"阐明作品意义，价值观正确（中国人民抗战的英勇顽强；反法西斯战争的伟大胜利，珍爱和平）","score":3}],"score":12,"sample":"作品名称：《苏联红旗插上德国国会大厦》。阐释：近景呈现了飘扬的苏联红旗，记录了红军战士将苏联红旗插上德国国会大厦的瞬间。柏林战役是第二次世界大战即将取得胜利之时，苏军对德国发动的最后一战。1945年4月，苏军冲入柏林市中心，与德军展开了激烈争夺，最终将胜利的红旗插上国会大厦。远景是硝烟弥漫、满目疮痍的柏林城，既反映了战争的残酷，也象征着法西斯德国的覆灭。不久，德国宣布无条件投降，欧洲战场的战争结束。作品用飘扬的红旗展现和颂扬了反法西斯战争的伟大胜利，警示人们铭记历史、珍爱和平。（示例后半段为本应用补写）","explanation":"1940年，彭德怀指挥八路军发动百团大战，是抗战以来八路军在华北发动的规模最大的战役，打击了日军，振奋了全国人民的抗战信心。"}]}]},{"id":"xiaosimen-dili-1","group":"地理","subject":"地理","term":"七年级上册","title":"地理 · 七年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024年福建省中考地理试题第1题","stem":"某自然保护区内有一处人工水塘。干季时，每天都有大量野生动物前来饮水。某日不同时段的气温与可拍摄到的动物如下表：0~6时，21~27℃，花豹、狮子；6~12时，21~40℃，珍珠鸡、斑马；12~16时，40~43℃，斑马、狒狒；16~22时，28~40℃，黑斑羚、狮子；22~24时，27~28℃，长颈鹿、大象。当日6~12时和12~16时都能拍摄到的动物是（ ）。","options":[{"key":"A","text":"狮子"},{"key":"B","text":"斑马"},{"key":"C","text":"黑斑羚"},{"key":"D","text":"珍珠鸡"}],"answer":"B","explanation":"6~12时可拍摄到珍珠鸡、斑马，12~16时可拍摄到斑马、狒狒，两时段共有的动物是斑马。"},{"type":"choice","tag":"Claude 精选","source":"2024年福建中考地理变式题（《2024年福建省中考地理试题1-6题原题及变式题》book118试读版，文档内第4题；非原卷第4题）","stem":"2023年12月22日，安溪县气象台发布霜冻黄色预警。安溪区域自动站近24小时最低气温多出现在6:00~7:00，如桃舟乡棠棣小学－4.8℃（7:00）、祥华乡新寨村小学－3.3℃（7:03）。据表可知，一天中最低气温出现在（ ）。","options":[{"key":"A","text":"2时"},{"key":"B","text":"日出前后"},{"key":"C","text":"14时"},{"key":"D","text":"日落前后"}],"answer":"B","explanation":"表中各站最低气温都出现在6点到7点左右，正是日出前后；一天中最高气温出现在午后14时左右。"},{"type":"choice","tag":"Claude 精选","source":"改编自2024年福建中考地理变式题（《2024年福建省中考地理试题1-6题原题及变式题》book118试读版，文档内第7题；非原卷第7题）","stem":"北京某中学地理学习小组通过校园气象站，测得了当地一天内的气温变化，测得当日最高气温达31℃。根据气温日变化规律，一天中最高气温约出现在（ ）。","options":[{"key":"A","text":"日出前后"},{"key":"B","text":"正午12:00"},{"key":"C","text":"午后2:00"},{"key":"D","text":"午夜时分"}],"answer":"C","explanation":"一天中气温最高值出现在午后14时左右，最低值出现在日出前后。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·地理第17题","stem":"在特定日子，北回归线上的地区由于太阳垂直照射而出现'立竿无影'现象，人们修建了标志塔来观测该现象。观测'立竿无影'现象的特定日子是（ ）。","options":[{"key":"A","text":"春分日"},{"key":"B","text":"夏至日"},{"key":"C","text":"秋分日"},{"key":"D","text":"冬至日"}],"answer":"B","explanation":"夏至日太阳直射北回归线，北回归线上的地区正午太阳高度为90°，立竿无影；春分、秋分日太阳直射赤道，冬至日太阳直射南回归线，北回归线上都有影子。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第6题","stem":"2025年3月28日，缅甸发生7.9级地震。此次地震的原因是（ ）","options":[{"key":"A","text":"位于板块内部，地壳比较稳定"},{"key":"B","text":"印度洋板块与亚欧板块碰撞挤压"},{"key":"C","text":"太平洋板块与亚欧板块碰撞挤压"},{"key":"D","text":"印度洋板块与非洲板块碰撞挤压"}],"answer":"B","explanation":"缅甸位于印度洋板块与亚欧板块碰撞挤压的交界地带，地壳活跃，容易发生地震；板块内部地壳稳定，不易发生地震；此次地震与太平洋板块、非洲板块无关。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年江苏省宿迁市中考地理试题第15题（原题依托太阳高度变化图，图中“某日18时至次日6时，最小太阳高度大于零”的信息改写为文字，知识点、选项与答案未改）","stem":"挪威北角（71°10′N）某日18时至次日6时的太阳高度变化显示，最小太阳高度大于零。该地出现极昼现象，判断依据是（ ）","options":[{"key":"A","text":"0时依然看到太阳"},{"key":"B","text":"6时太阳刚刚升起"},{"key":"C","text":"18时太阳已经落山"},{"key":"D","text":"太阳东升西落"}],"answer":"A","explanation":"极昼是指某地24小时内太阳始终位于地平线以上的现象，0时依然看到太阳，可以推测该地出现极昼；6时太阳刚刚升起、18时太阳已经落山都与极昼现象矛盾；太阳东升西落是日常现象，不是判断极昼的依据。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第18题","stem":"使用测高仪时，应注意（ ）①在南半球使用②在晴朗的夜晚③要找准北极星④底座水平放置","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"D","explanation":"南半球看不到北极星，①错误；观测北极星需要良好天气条件，晴朗的夜晚是必要前提，②正确；测量纬度依赖北极星的高度角，要找准北极星，③正确；仪器底座未水平会导致测量误差，应注意底座水平放置，④正确。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省乐山市中考地理试题第14题（原题依托钱凯港位置示意图，改为直接设问，知识点、选项与答案未改）","stem":"2024年11月，共建“一带一路”在拉美地区的标志性项目之一秘鲁钱凯港正式开港。钱凯在（ ）","options":[{"key":"A","text":"北半球、西半球"},{"key":"B","text":"南半球、东半球"},{"key":"C","text":"南半球、西半球"},{"key":"D","text":"北半球、东半球"}],"answer":"C","explanation":"赤道以北是北半球、以南是南半球；20°W和160°E组成的经线圈是东西半球的分界线，20°W以西到160°E是西半球。秘鲁位于赤道以南，南美洲位于西半球，所以钱凯在南半球、西半球。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第16题（原题依托冰冻线分布示意图，改为直接设问，知识点与答案未改）","stem":"距离现场观赏哈尔滨冰灯冰雕最近的地点是（ ）","options":[{"key":"A","text":"（46°N，127°E）"},{"key":"B","text":"（46°S，127°E）"},{"key":"C","text":"（46°N，127°W）"},{"key":"D","text":"（46°S，127°W）"}],"answer":"A","explanation":"哈尔滨位于北半球，经纬度大致在北纬40多度、东经120多度；B、D纬度是南纬，C、D经度是西经，都不符合哈尔滨北半球、东经度的位置特点；（46°N，127°E）最接近哈尔滨。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第2题","stem":"2025年春节是1月29日。2025年春节位于下列哪两个节气之间（ ）","options":[{"key":"A","text":"立秋、处暑"},{"key":"B","text":"立冬、小雪"},{"key":"C","text":"大寒、立春"},{"key":"D","text":"立夏、小满"}],"answer":"C","explanation":"2025年大寒在1月20日，立春在2月3日，1月29日的春节正处在大寒之后、立春之前；立秋、处暑在秋季，立冬、小雪在冬季前期，立夏、小满在夏季前期，都与1月29日不符。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省泸州市中考地理试题第9题","stem":"2025年4月24日神舟二十号载人飞船成功发射，4月30日神舟十九号载人飞船成功着陆。在此期间，泸州（29°N）昼夜长短及变化情况是（ ）","options":[{"key":"A","text":"昼长夜短，昼在变短"},{"key":"B","text":"昼长夜短，昼在变长"},{"key":"C","text":"昼短夜长，昼在变短"},{"key":"D","text":"昼短夜长，昼在变长"}],"answer":"B","explanation":"4月下旬太阳直射北半球并向北移动，北半球昼长夜短；越接近夏至（6月22日），北半球昼越长，所以昼在变长。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年安徽省初中（八年级）学业水平考试地理试题第11题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"规划中的“两洋铁路”中线位于赤道附近。“两洋铁路”中线位于地球上的五带中的（ ）带。","options":[{"key":"A","text":"热带"},{"key":"B","text":"北温带"},{"key":"C","text":"南温带"},{"key":"D","text":"北寒带"}],"answer":"A","explanation":"南北回归线之间的区域属于热带；“两洋铁路”中线位于赤道附近，处在热带。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建省中考地理试题第12题（原题照录）","stem":"世界人口密集区主要分布在（ ）。","options":[{"key":"A","text":"北半球中低纬度"},{"key":"B","text":"北半球中高纬度"},{"key":"C","text":"南半球中低纬度"},{"key":"D","text":"南半球中高纬度"}],"answer":"A","explanation":"原卷参考答案：A。世界人口密集区主要分布在北半球中低纬度地区。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建省中考地理试题第26题第（4）小问（原题为对话填空题，改编为单选题，知识点与答案未改）","stem":"洪堡考察发现：地球是一个两极稍扁、赤道略鼓的不规则球体，赤道半径比极半径长约21千米；珠穆朗玛峰海拔8848.86米，是世界最高峰。地球表面离地心最远的地方是（ ）。","options":[{"key":"A","text":"钦博拉索火山之巅"},{"key":"B","text":"珠穆朗玛峰峰顶"},{"key":"C","text":"乞力马扎罗山顶"},{"key":"D","text":"厄尔布鲁士山顶"}],"answer":"A","explanation":"原卷答案要点：地球形状是不规则球体，赤道半径比极半径长21千米，钦博拉索火山之巅是地球表面离地心最远的地方。赤道处地球半径最大，位于赤道附近的钦博拉索火山之巅离地心最远；珠穆朗玛峰是海拔最高峰，不是离地心最远的地方。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建省中考地理试题第29题第（1）小问（原题为纠错题，改编为单选题，知识点与答案未改）","stem":"某中学生利用泡沫球、竹签、铁丝、记号笔和橡皮泥等器材制作简易地球仪。制作时应调整支架角度，使竹签（地轴）与桌面成（ ）角。","options":[{"key":"A","text":"66.5°"},{"key":"B","text":"90°"},{"key":"C","text":"23.5°"},{"key":"D","text":"45°"}],"answer":"A","explanation":"原卷答案指出制作步骤⑤“使竹签与桌面垂直”是制作错误，应更正为“调整支架角度，使竹签与桌面成66.5°角”。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-coordinates","stem":"经度为 170°E 的地点位于","options":[{"key":"A","text":"西半球"},{"key":"B","text":"东半球"},{"key":"C","text":"东、西半球的分界线上"},{"key":"D","text":"无法判断在哪个半球"}],"answer":"A","explanation":"东西半球以 20°W 和 160°E 组成的经线圈划分。东经不都在东半球，170°E 在西半球。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-earth-motion","stem":"北半球夏至日这一天，太阳直射","options":[{"key":"A","text":"北极圈"},{"key":"B","text":"北回归线"},{"key":"C","text":"赤道"},{"key":"D","text":"南回归线"}],"answer":"B","explanation":"地轴倾斜且地球公转，直射点随季节移动；北半球夏至日太阳直射北回归线。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-map-scale","stem":"下列比例尺中，比例尺最大的是","options":[{"key":"A","text":"1∶500000"},{"key":"B","text":"1∶5000000"},{"key":"C","text":"1∶5000"},{"key":"D","text":"1∶50000"}],"answer":"C","explanation":"比例尺 = 图上距离 ÷ 实地距离，分母越小比例尺越大；1∶5000 大于 1∶50000。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-contours","stem":"在等高线地形图上，等高线向海拔高处凸出的部位是","options":[{"key":"A","text":"山脊"},{"key":"B","text":"山顶"},{"key":"C","text":"鞍部"},{"key":"D","text":"山谷"}],"answer":"D","explanation":"山谷的等高线凸向高处，山脊的等高线凸向低处；要先看标注确定哪边海拔高。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-climate-graphs","stem":"某地最热月平均气温 28℃，最冷月平均气温 -4℃。该地气温年较差是","options":[{"key":"A","text":"32℃"},{"key":"B","text":"24℃"},{"key":"C","text":"28℃"},{"key":"D","text":"4℃"}],"answer":"A","explanation":"年较差 = 最高月平均气温 − 最低月平均气温 = 28 −（−4）= 32℃。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"地球的平均半径约为____千米；赤道周长约为____万千米。","answer":["6371","4"],"explanation":"地球是一个两极稍扁、赤道略鼓的不规则球体。"},{"type":"blank","stem":"纬线指示____方向，经线指示____方向。","answer":["东西","南北"],"explanation":"所有纬线都是圆，赤道最长；所有经线都是半圆，长度相等。"},{"type":"blank","stem":"划分东西半球的经线圈是____经线和160°E经线；南北半球的分界线是____。","answer":["20°W","赤道"],"explanation":"0°经线（本初子午线）通过英国伦敦格林尼治天文台旧址。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版七年级上册“地球的运动”编写","kind":"综合题","material":"","stem":"比较地球自转和公转：分别说出它们的方向、周期，以及各自产生的主要地理现象。（8分）","points":[{"text":"自转：绕地轴自西向东转，周期约为一天（24小时）","score":2},{"text":"自转产生：昼夜交替、时间差异（东边的地点比西边先看到日出）","score":2},{"text":"公转：绕太阳自西向东转，周期为一年","score":2},{"text":"公转产生：四季变化、昼夜长短变化、正午太阳高度变化、五带的划分","score":2}],"score":8,"sample":"","explanation":"地球公转时地轴是倾斜的，且空间指向不变，所以太阳直射点在南北回归线之间移动，产生四季。"},{"type":"essay","tag":"简答题","source":"依据人教版七年级上册“地形图的判读”编写","kind":"简答题","material":"","stem":"在等高线地形图上，如何判断山峰、鞍部、山脊、山谷和陡崖？哪种地形部位容易形成河流？（7分）","points":[{"text":"山峰：等高线闭合，数值中间高四周低","score":1},{"text":"鞍部：两个山顶之间相对低洼的部位","score":1},{"text":"山脊：等高线向海拔低处凸出；山谷：等高线向海拔高处凸出","score":2},{"text":"陡崖：多条等高线重合","score":1},{"text":"山谷容易汇集水流形成河流","score":2}],"score":7,"sample":"","explanation":"等高线稀疏处坡度缓，适合修建盘山公路、开展登山活动的路线一般选在坡缓处。"}]}]},{"id":"xiaosimen-dili-2","group":"地理","subject":"地理","term":"七年级下册","title":"地理 · 七年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年四川省达州市中考地理试题第7题","stem":"大连到鹿特丹的传统航道经过的海峡有（ ）","options":[{"key":"A","text":"马六甲海峡"},{"key":"B","text":"莫桑比克海峡"},{"key":"C","text":"德雷克海峡"},{"key":"D","text":"土耳其海峡"}],"answer":"A","explanation":"大连到鹿特丹的传统航道要经过马六甲海峡、苏伊士运河、直布罗陀海峡；莫桑比克海峡在非洲东南部，德雷克海峡在南美洲南端，土耳其海峡沟通黑海与地中海，都不在这条传统航道上。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·地理第7题","stem":"近年来，我国从巴西进口大豆的数量逐年增加。我国从巴西进口大豆的最佳运输方式是（ ）。","options":[{"key":"A","text":"公路运输"},{"key":"B","text":"铁路运输"},{"key":"C","text":"航空运输"},{"key":"D","text":"水路运输"}],"answer":"D","explanation":"大豆是批量大宗货物，中巴相距遥远、隔着大洋，水路运输运量大、运费低，最适合远洋大宗货物运输；公路、铁路无法跨洋，航空运费太高。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建中考·地理第24题（原题依托贝加尔湖位置图，图中贝加尔湖位于北纬52°—55°之间的信息改写为文字，知识点、选项与答案未改）","stem":"位于亚洲北部的贝加尔湖每年10月初湖面开始结冰，11月底完全冻结后，汽车可在冰面行驶；次年5月初湖冰开始融化，6月底融尽后，船只可在水上航行。贝加尔湖位于北纬52°—55°之间。贝加尔湖结冰期长的主要原因是（ ）。","options":[{"key":"A","text":"纬度高"},{"key":"B","text":"距海近"},{"key":"C","text":"海拔低"},{"key":"D","text":"面积大"}],"answer":"A","explanation":"贝加尔湖位于北纬52°—55°，纬度高，气温低，冬季漫长寒冷，所以结冰期长；它地处内陆、距海远，海拔和面积都不是结冰期长的主要原因。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·地理第13题","stem":"非洲多国合作实施'绿色长城'计划，修建一条位于撒哈拉沙漠南缘的防护林带。实施'绿色长城'计划应对的主要环境问题是（ ）。","options":[{"key":"A","text":"土地荒漠化"},{"key":"B","text":"雨林破坏"},{"key":"C","text":"环境污染"},{"key":"D","text":"水土流失"}],"answer":"A","explanation":"防护林带修在撒哈拉沙漠南缘，目的是阻挡沙漠向南扩展，应对土地荒漠化；雨林破坏在赤道雨林区，环境污染、水土流失都不是这条防护林带要解决的主要问题。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建中考·地理第23题（原题依托瑙鲁位置图，图中瑙鲁位于南纬0°30′—0°32′、东经166°54′—166°56′之间的信息改写为文字，知识点、选项与答案未改）","stem":"瑙鲁是无河流岛国，陆地面积仅21.1平方千米，耕地面积很小，农业部门以海洋渔业为主。该国水资源短缺，需大量进口饮用水。瑙鲁位于南纬0°30′—0°32′、东经166°54′—166°56′之间。瑙鲁地处（ ）。","options":[{"key":"A","text":"热带"},{"key":"B","text":"北温带"},{"key":"C","text":"南温带"},{"key":"D","text":"北寒带"}],"answer":"A","explanation":"瑙鲁位于南纬0°30′附近，紧靠赤道，在南、北回归线之间，属热带；温带在回归线与极圈之间，寒带在极圈以内。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第5题","stem":"2025年3月28日，缅甸发生7.9级地震。缅甸位于（ ）","options":[{"key":"A","text":"东亚地区"},{"key":"B","text":"东南亚地区"},{"key":"C","text":"南亚地区"},{"key":"D","text":"西亚地区"}],"answer":"B","explanation":"缅甸位于亚洲东南部，属于东南亚地区；东亚地区主要包括中国东部、日本、韩国等，南亚地区包括印度、巴基斯坦等，西亚地区主要是中东国家，缅甸都不属于这些地区。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第21题","stem":"近年来，俄罗斯亚马尔半岛能源开发取得进展。我国参建的亚马尔液化天然气项目已经成为北极地区重要的能源开发项目。吸引我国参建亚马尔天然气项目的主要原因是，该国（ ）","options":[{"key":"A","text":"天然气资源丰富"},{"key":"B","text":"劳动力便宜"},{"key":"C","text":"国内市场广阔"},{"key":"D","text":"基础设施完善"}],"answer":"A","explanation":"俄罗斯天然气资源丰富，亚马尔半岛有大量天然气可开发，吸引我国参建获取资源；俄罗斯劳动力不具备“便宜”优势，能源开发也不是依赖廉价劳动力的劳动密集型产业；“国内市场广阔”是我国作为需求方的特点，不是俄罗斯吸引参建的原因；亚马尔半岛位于北极地区，基础设施并不完善。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第24题","stem":"近年来，日本与巴西加强贸易合作，巴西的主要优势是（ ）","options":[{"key":"A","text":"资金实力雄厚"},{"key":"B","text":"劳动力素质高"},{"key":"C","text":"矿产资源丰富"},{"key":"D","text":"科学技术发达"}],"answer":"C","explanation":"日本是发达国家，资金实力雄厚、劳动力素质高、科学技术发达；巴西是发展中国家，但其矿产资源丰富，这是与日本加强贸易合作时的主要优势。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第18题第（1）小问（原题为填空题，改编为单选题，知识点与答案未改）","stem":"从波斯湾出发的油轮，经亚非两洲分界线（ ）运河到达欧洲，比绕道非洲南部到达欧洲可大大缩短航程。","options":[{"key":"A","text":"苏伊士"},{"key":"B","text":"巴拿马"},{"key":"C","text":"基尔"},{"key":"D","text":"京杭"}],"answer":"A","explanation":"亚非两洲的分界线是苏伊士运河，沟通红海和地中海；巴拿马运河是南北美洲分界线，基尔运河在德国，京杭大运河在中国，都不是亚非分界线。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第18题第（3）小问（原题为填空题，改编为单选题，知识点与答案未改）","stem":"非洲大陆东临印度洋，西临大西洋；澳大利亚大陆东临太平洋，西临印度洋。非洲大陆与澳大利亚大陆均濒临（ ）","options":[{"key":"A","text":"印度洋"},{"key":"B","text":"大西洋"},{"key":"C","text":"太平洋"},{"key":"D","text":"北冰洋"}],"answer":"A","explanation":"非洲大陆东临印度洋，澳大利亚大陆西临印度洋，两大陆均濒临印度洋；大西洋只濒临非洲西岸，太平洋只濒临澳大利亚东岸，北冰洋两大陆都不濒临。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第18题第（3）小问（原题为填空题，改编为单选题；干扰项袋鼠、鸭嘴兽、企鹅为补写，明显错误，知识点与答案未改）","stem":"非洲大陆热带草原面积广大，代表性动物有长颈鹿、斑马等。下列动物中，属于非洲热带草原代表性动物的是（ ）","options":[{"key":"A","text":"长颈鹿"},{"key":"B","text":"袋鼠"},{"key":"C","text":"鸭嘴兽"},{"key":"D","text":"企鹅"}],"answer":"A","explanation":"非洲热带草原代表性动物有长颈鹿、斑马等；袋鼠、鸭嘴兽是澳大利亚特有的动物，企鹅主要分布在南极地区。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第13题","stem":"芬兰人口分布南北不均，滑雪是芬兰人喜爱且擅长的传统体育运动项目。冬季，芬兰的气候特征是（ ）","options":[{"key":"A","text":"冷干"},{"key":"B","text":"暖湿"},{"key":"C","text":"热干"},{"key":"D","text":"冷湿"}],"answer":"D","explanation":"芬兰纬度高，冬季寒冷；受北大西洋暖流影响，冬季降水较多、气候较湿润，所以是冷湿而不是冷干；暖湿、热干与芬兰高纬度寒冷不符。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省宜宾市中考地理试题第21题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"货船从大连出发，沿传统航道前往鹿特丹，穿越马六甲海峡进入印度洋；经①运河进入②海，最终到达大西洋沿岸的鹿特丹。①②分别是（ ）。","options":[{"key":"A","text":"苏伊士运河、地中海"},{"key":"B","text":"巴拿马运河、加勒比海"},{"key":"C","text":"基尔运河、北海"},{"key":"D","text":"苏伊士运河、红海"}],"answer":"A","explanation":"从印度洋前往大西洋沿岸的鹿特丹，传统航道经苏伊士运河进入地中海，再出直布罗陀海峡进入大西洋。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年安徽省初中（八年级）学业水平考试地理试题第11题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"规划中的“两洋铁路”中线跨越世界上水量最大的河流，该河流是（ ）。","options":[{"key":"A","text":"亚马孙河"},{"key":"B","text":"尼罗河"},{"key":"C","text":"长江"},{"key":"D","text":"密西西比河"}],"answer":"A","explanation":"世界上水量最大的河流是亚马孙河，它流经热带雨林气候区，降水丰富，河流流量大；尼罗河是世界上最长的河流。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省南充市中考地理试题第12题（非选择题改编为单选题，只改呈现形式，知识点与答案未改；原题“美洲国家”结合本题组南美洲语境明确为南美洲国家）","stem":"南美洲国家均属于（ ）。","options":[{"key":"A","text":"发达国家"},{"key":"B","text":"发展中国家"},{"key":"C","text":"转型国家"},{"key":"D","text":"最不发达国家"}],"answer":"B","explanation":"南美洲国家都是发展中国家；发达国家主要分布在欧洲、北美洲和大洋洲。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-asia-relief","stem":"亚洲的地势特点和河流流向是","options":[{"key":"A","text":"地势平坦，河流流向不定"},{"key":"B","text":"中部高、四周低，许多大河从中部流向四周"},{"key":"C","text":"西高东低，河流都自西向东流"},{"key":"D","text":"四周高、中部低，河流流向中部"}],"answer":"B","explanation":"亚洲地势中部高、四周低，不少大河发源于中部高地，流向周边海洋（也有内流河）。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-japan-ports","stem":"日本工业主要分布在太平洋沿岸和濑户内海沿岸，主要原因是","options":[{"key":"A","text":"这里气候寒冷"},{"key":"B","text":"这里地势高"},{"key":"C","text":"临近港口，便于进口原料燃料和出口产品"},{"key":"D","text":"这里矿产资源特别丰富"}],"answer":"C","explanation":"日本原料、燃料多靠进口，产品多出口；临港便于海运。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-west-asia-oil-water","stem":"油轮从波斯湾驶入阿曼湾，必须经过","options":[{"key":"A","text":"马六甲海峡"},{"key":"B","text":"直布罗陀海峡"},{"key":"C","text":"白令海峡"},{"key":"D","text":"霍尔木兹海峡"}],"answer":"D","explanation":"西亚石油多分布在波斯湾及沿岸，油轮驶出波斯湾到阿曼湾要经过霍尔木兹海峡。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-africa-savanna","stem":"撒哈拉以南非洲广布的热带草原气候，特点是","options":[{"key":"A","text":"全年高温，有明显的干季和湿季"},{"key":"B","text":"全年高温多雨"},{"key":"C","text":"全年炎热干燥"},{"key":"D","text":"夏季炎热干燥，冬季温和多雨"}],"answer":"A","explanation":"辨热带草原气候要找干季和湿季；全年高温多雨是热带雨林气候。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-brazil-rainforest","stem":"亚马孙热带雨林的重要生态价值不包括","options":[{"key":"A","text":"为众多物种提供栖息地"},{"key":"B","text":"适合大面积砍伐后扩大耕地"},{"key":"C","text":"涵养水源"},{"key":"D","text":"储存碳"}],"answer":"B","explanation":"雨林能涵养水源、储存碳、提供栖息地；大面积清林会削弱这些作用，判断能否扩种不能只看雨热条件。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"亚洲与欧洲的分界线有乌拉尔山脉、乌拉尔河、大高加索山脉和____海峡等。","answer":["土耳其"],"explanation":"亚洲与非洲以苏伊士运河为界。"},{"type":"blank","stem":"世界最高峰是____，海拔8848.86米。","answer":["珠穆朗玛峰"],"explanation":"位于中国与尼泊尔边界的喜马拉雅山脉。"},{"type":"blank","stem":"印度的气候以热带____气候为主，6—9月为雨季。","answer":["季风"],"explanation":"西南季风来得早晚、强弱不稳定，导致印度旱涝灾害频繁。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版七年级下册“日本”编写","kind":"综合题","material":"","stem":"日本经济发展有什么特点？为什么日本的工业主要分布在太平洋沿岸和濑户内海沿岸？（6分）","points":[{"text":"特点：资源贫乏，经济对外依赖严重，进口原料（能源和矿产）、出口工业产品","score":2},{"text":"原因：沿海地区多优良港湾，便于进口原料和出口产品","score":2},{"text":"沿海地区平原较多、人口城市集中，劳动力和市场充足","score":2}],"score":6,"sample":"","explanation":"日本是岛国，多火山地震，属于季风气候和温带海洋性气候。"},{"type":"essay","tag":"简答题","source":"依据人教版七年级下册“东南亚”编写","kind":"简答题","material":"","stem":"为什么说马六甲海峡的地理位置十分重要？东南亚的城市主要分布在哪里？为什么？（6分）","points":[{"text":"马六甲海峡位于马来半岛和苏门答腊岛之间，连接太平洋和印度洋","score":2},{"text":"是亚洲与非洲、大洋洲、欧洲之间海上航行的重要通道（被称为“海上生命线”）","score":2},{"text":"城市主要分布在河流沿岸和河口三角洲：地形平坦、土壤肥沃、水源充足、交通便利","score":2}],"score":6,"sample":"","explanation":"东南亚由中南半岛和马来群岛组成，是华人和华侨最多的地区。"}]}]},{"id":"xiaosimen-dili-3","group":"地理","subject":"地理","term":"八年级上册","title":"地理 · 八年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年四川省泸州市中考地理试题第7题","stem":"我国地势特点是（ ）①西高东低②东高西低③逐渐降低④阶梯分布","options":[{"key":"A","text":"①③"},{"key":"B","text":"①④"},{"key":"C","text":"②③"},{"key":"D","text":"②④"}],"answer":"B","explanation":"我国地势西高东低，大致呈三级阶梯状分布：第一级阶梯是青藏高原，第二级阶梯是高原和盆地，第三级阶梯是平原和丘陵；东高西低与事实相反。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建中考·地理第10题（原题依托西延高铁线路图，图中沿线为黄土高原沟壑区的信息改写为文字，知识点、选项与答案未改）","stem":"西延高铁全线桥梁和隧道占比高达91.1%。西延高铁沿线经过黄土高原沟壑区，地势起伏大。西延高铁采用高桥隧比建设方案的主要目的是（ ）。","options":[{"key":"A","text":"减小线路起伏"},{"key":"B","text":"降低施工难度"},{"key":"C","text":"保护原始森林"},{"key":"D","text":"方便动物迁徙"}],"answer":"A","explanation":"黄土高原沟壑纵横、地势起伏大，修桥打隧道可以减小线路起伏、保持线路平顺，保障高铁安全快速运行；桥隧施工难度更大而不是更小，黄土高原也没有大片原始森林，方便动物迁徙不是主要目的。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·地理第16题","stem":"唐朝诗句'王濬楼船下益州，金陵王气黯然收'，描述的是晋朝大将军王濬率水军从益州（今成都）出发，沿长江东进，攻取东吴都城建业（唐称金陵，今南京）的历史事件。晋朝水军从益州到建业，途经的地形区现称为（ ）。","options":[{"key":"A","text":"四川盆地、华北平原"},{"key":"B","text":"四川盆地、长江中下游平原"},{"key":"C","text":"东南丘陵、华北平原"},{"key":"D","text":"东南丘陵、长江中下游平原"}],"answer":"B","explanation":"从成都出发先经过四川盆地，顺江东下进入长江中下游平原，直达南京；华北平原在黄河下游，与长江水路无关，东南丘陵也不在长江干流沿线。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建中考·地理第1题（原题依托'鑫环1号'位置图，图中平台位于海南岛以南海域的信息改写为文字，知识点、选项与答案未改）","stem":"2026年5月，国内规模最大的半潜式海洋牧场智能养殖平台'鑫环1号'，在距海南岛10千米以外的海域开展收尾工作，将于6月正式启用。该平台集养殖、垂钓旅游于一体。图1显示'鑫环1号'位于海南岛以南海域。'鑫环1号'所在海域是（ ）。","options":[{"key":"A","text":"渤海"},{"key":"B","text":"黄海"},{"key":"C","text":"东海"},{"key":"D","text":"南海"}],"answer":"D","explanation":"海南岛以南的海域是南海；渤海、黄海在北方，东海在浙江、福建以东，都不在海南岛以南。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·地理第10题","stem":"'北纬30°中国段'被誉为中国最美的风景'走廊'。横断山脉同一纬度出现亚热带、温带、寒带景观，其主要原因是（ ）。","options":[{"key":"A","text":"热量充足"},{"key":"B","text":"降水丰富"},{"key":"C","text":"相对高度大"},{"key":"D","text":"河流水量大"}],"answer":"C","explanation":"横断山脉山高谷深，相对高度大，山麓到山顶气温随海拔升高而降低，同一纬度出现了从亚热带到寒带的不同景观；热量、降水、河流水量都不是同一纬度出现多带景观的主要原因。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省广安市中考地理试题第15题（原题依托油菜花开花时间图，图中成都、广州、重庆油菜花开放时间在3月1日前、武汉为3月1日至4月1日的信息改写为文字，知识点、选项与答案未改）","stem":"读油菜花开花时间图可知，成都、广州、重庆三地油菜花开放时间在3月1日前，武汉油菜花开放时间为3月1日至4月1日。小明一家计划3月中旬外出观赏油菜花，下列地区观赏性最佳的是（ ）","options":[{"key":"A","text":"成都"},{"key":"B","text":"广州"},{"key":"C","text":"武汉"},{"key":"D","text":"重庆"}],"answer":"C","explanation":"3月中旬正处在武汉油菜花开放时间（3月1日至4月1日）内；成都、广州、重庆的油菜花开放时间都在3月1日前，3月中旬已过花期。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省深圳市中考地理试题（我国人口增长图组）第2题","stem":"关于人口普查，说法正确的是（ ）","options":[{"key":"A","text":"提高人口素养"},{"key":"B","text":"调控第三产业"},{"key":"C","text":"有利于完善人口政策"},{"key":"D","text":"提高人健康状态"}],"answer":"C","explanation":"人口普查可以摸清人口数量、结构、分布等基本国情，为制定和完善人口政策提供依据；提高人口素养、调控第三产业、提高健康状态都不是人口普查的直接作用。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第12题","stem":"与海洋运输相比，中欧班列采用的铁路运输的优势有（ ）","options":[{"key":"A","text":"速度较快"},{"key":"B","text":"受自然条件限制大"},{"key":"C","text":"运价较低"},{"key":"D","text":"投资较小"}],"answer":"A","explanation":"与海洋运输相比，铁路运输速度较快，时间显著短于海运，适合对时效要求较高的货物；海运更易受天气（台风、大雾）等自然条件影响；海运因运量极大，单位成本更低；铁路基建（轨道、枢纽）投资远高于港口和船舶。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省达州市中考地理试题第15题","stem":"长江、黄河哺育了中华儿女，孕育了中华文明，是中华民族的母亲河。黄河最终流入的海洋是（ ）","options":[{"key":"A","text":"渤海"},{"key":"B","text":"黄海"},{"key":"C","text":"东海"},{"key":"D","text":"南海"}],"answer":"A","explanation":"黄河发源于青藏高原巴颜喀拉山，自西向东流经青海、四川、甘肃、宁夏、内蒙古、陕西、山西、河南、山东九个省区，最终在山东东营注入渤海；黄海、东海、南海都不是黄河的入海口。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第19题第（2）小问（原题为填空题，改编为单选题，知识点与答案未改）","stem":"长江三角洲地区位于我国地势第三级阶梯。崇明岛地处我国地势第（ ）级阶梯。","options":[{"key":"A","text":"一"},{"key":"B","text":"二"},{"key":"C","text":"三"},{"key":"D","text":"四"}],"answer":"C","explanation":"我国地势分为三级阶梯，长江三角洲地区位于我国地势第三级阶梯；我国地势只有三级阶梯，没有第四级。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省泸州市中考地理试题第8题","stem":"我国地势分布特点主要影响河流的（ ）①流向②流速③流量④汛期","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"A","explanation":"地势西高东低决定了我国河流多自西向东流（流向）；阶梯交界处落差大、水流急（流速）；地势影响汇水面积和降水分布，进而影响流量；汛期主要由降水季节变化决定，受地势影响小。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省南充市中考地理试题第3题","stem":"今年以来，南充市多次出现不同程度的沙尘天气，空气质量受到了较大影响。导致南充市出现沙尘天气的盛行风最有可能是（ ）","options":[{"key":"A","text":"西北风"},{"key":"B","text":"东南风"},{"key":"C","text":"西南风"},{"key":"D","text":"东北风"}],"answer":"A","explanation":"我国沙尘的源地主要在西北干旱、半干旱地区，沙尘随西北风南下扩散，可影响到四川盆地；东南风、西南风来自海洋，带来湿润气流，不会带来沙尘；东北风也不是沙尘南下的主要风向。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年广东省深圳市中考地理试题（中国风能资源分布图组）第2题（原题依托中国风能资源分布图，图中北京、重庆等地有效风功率密度数值改写为文字，知识点、选项与答案未改；原文档解析文字顺序错乱，答案以文档答案列表B与解析结论句“风能欠缺的地区是重庆”为准，并与教材四川盆地风速小、风能贫乏交叉核对）","stem":"读中国风能资源分布图，北京地区的有效风功率密度为50—100瓦/平方米，重庆地区的有效风功率密度在50瓦/平方米以下。北京、重庆、台湾、成都四地中，风能欠缺的地区是（ ）","options":[{"key":"A","text":"北京"},{"key":"B","text":"重庆"},{"key":"C","text":"台湾"},{"key":"D","text":"成都"}],"answer":"B","explanation":"重庆的有效风功率密度在50瓦/平方米以下，是四地中最低的；重庆位于四川盆地，风速小、风能资源贫乏；北京、台湾、成都的风功率密度都高于重庆。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省宜宾市中考地理试题第23题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"我国东部地区由北向南入冬时间变（ ），其主要影响因素是（ ）。","options":[{"key":"A","text":"晚、纬度位置"},{"key":"B","text":"早、纬度位置"},{"key":"C","text":"晚、海陆位置"},{"key":"D","text":"早、地形因素"}],"answer":"A","explanation":"我国东部地区由北向南，纬度逐渐降低，气温逐渐升高，入冬时间越来越晚，主要影响因素是纬度位置。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年安徽省初中（八年级）学业水平考试地理试题第12题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"青藏地区大部分属于严寒地区，是由于其平均海拔较（ ）。","options":[{"key":"A","text":"高"},{"key":"B","text":"低"},{"key":"C","text":"适中"},{"key":"D","text":"与海拔无关"}],"answer":"A","explanation":"青藏地区平均海拔高，气温低（海拔每升高100米，气温约下降0.6℃），大部分属于严寒地区。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-population","stem":"我国人口分布的重要地理界线是","options":[{"key":"A","text":"昆仑山—祁连山一线"},{"key":"B","text":"长江一线"},{"key":"C","text":"黑河—腾冲线"},{"key":"D","text":"秦岭—淮河一线"}],"answer":"C","explanation":"黑河—腾冲线东南侧人口相对稠密，西北侧相对稀疏；秦岭—淮河是南北方分界。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-steps","stem":"我国地势第一级阶梯的主体是","options":[{"key":"A","text":"黄土高原"},{"key":"B","text":"华北平原"},{"key":"C","text":"四川盆地"},{"key":"D","text":"青藏高原"}],"answer":"D","explanation":"第一级以青藏高原为主，第二级多高原和盆地，第三级多平原和丘陵。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-monsoon","stem":"我国年降水量的空间分布规律是","options":[{"key":"A","text":"从东南沿海向西北内陆递减"},{"key":"B","text":"从西北内陆向东南沿海递减"},{"key":"C","text":"南北各地大致相同"},{"key":"D","text":"从南向北递增"}],"answer":"A","explanation":"年降水量大体由东南沿海向西北内陆递减，季节变化要结合夏季风判断。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-yellow-river-sediment","stem":"黄河下游形成“地上河”的原因是","options":[{"key":"A","text":"下游地势比中游高"},{"key":"B","text":"中游流经黄土高原带来大量泥沙，下游流速减慢、泥沙淤积"},{"key":"C","text":"只是因为下游降水多"},{"key":"D","text":"只是因为上游冰雪融水多"}],"answer":"B","explanation":"解释下游淤积要同时写“中游来沙多”和“下游流速慢”，只写一项不完整。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-transport-choice","stem":"把一批急需的鲜花从福建运往北京参加展会，最适合的运输方式是","options":[{"key":"A","text":"管道运输"},{"key":"B","text":"公路长途慢运"},{"key":"C","text":"航空运输"},{"key":"D","text":"水路运输"}],"answer":"C","explanation":"选运输方式看货量和时效：贵重又紧急的远途货物可考虑航空。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"我国陆地面积约为____万平方千米，居世界第三位。","answer":["960"],"explanation":"前两位是俄罗斯和加拿大。"},{"type":"blank","stem":"我国共有34个省级行政区，其中福建省的简称是____，行政中心是____。","answer":["闽","福州"],"explanation":"台湾省简称台，行政中心台北。"},{"type":"blank","stem":"我国人口分布以黑河—____一线为界，东南半壁人口多、西北半壁人口少；我国少数民族中人口最多的是____族。","answer":["腾冲","壮"],"explanation":"我国有56个民族，汉族人口最多；民族分布呈“大杂居、小聚居、交错杂居”的特点。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版八年级上册“地形和地势”编写","kind":"综合题","material":"","stem":"我国地势有什么特点？这种地势特点对气候和河流有哪些有利影响？（6分）","points":[{"text":"特点：西高东低，呈三级阶梯状分布","score":2},{"text":"利于来自海洋的湿润气流深入内地，形成降水","score":2},{"text":"使许多大河滚滚东流，沟通东西交通；阶梯交界处河流落差大，水能资源丰富","score":2}],"score":6,"sample":"","explanation":"第一、二级阶梯分界：昆仑山—祁连山—横断山；第二、三级阶梯分界：大兴安岭—太行山—巫山—雪峰山。"},{"type":"essay","tag":"综合题","source":"依据人教版八年级上册“气候”编写","kind":"综合题","material":"","stem":"我国气候的主要特征是什么？季风气候显著对农业生产有何利与弊？（6分）","points":[{"text":"特征：气候复杂多样，季风气候显著","score":2},{"text":"利：夏季高温与多雨同期（雨热同期），有利于农作物生长","score":2},{"text":"弊：季风不稳定，降水变率大，易发生旱涝灾害","score":2}],"score":6,"sample":"","explanation":"我国东部季风区与非季风区的分界线：大兴安岭—阴山—贺兰山—巴颜喀拉山—冈底斯山。"}]}]},{"id":"xiaosimen-dili-4","group":"地理","subject":"地理","term":"八年级下册","title":"地理 · 八年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年福建中考·地理第18题","stem":"粤港澳大湾区是由广东省广州市、深圳市等九座城市（简称珠三角九市）和香港、澳门两个特别行政区组成的城市群。粤港澳大湾区濒临的海洋是（ ）。","options":[{"key":"A","text":"渤海"},{"key":"B","text":"黄海"},{"key":"C","text":"东海"},{"key":"D","text":"南海"}],"answer":"D","explanation":"粤港澳大湾区位于广东省南部沿海，濒临南海；渤海在北方，黄海在山东、江苏以东，东海在浙江、福建以东。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建中考·地理第7题（原题依托2024年我国粮食总产量排名图，图中粮食总产量第一的省级行政区为黑龙江的信息改写为文字，知识点、选项与答案未改）","stem":"与福建相比，粮食总产量第一的省级行政区（黑龙江，8.0千万吨）发展种植业的优势条件有（ ）。①热量充足 ②平原广阔 ③海运便利 ④土壤肥沃","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"C","explanation":"黑龙江位于东北平原，平原广阔，黑土肥沃，这是其发展种植业的优势；黑龙江纬度高、热量不如福建，①错误；黑龙江不临海，海运便利不是其优势，③错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市中考地理试题第18题","stem":"京新高速公路被誉为“最美色彩大道”，沿途将邂逅绿的林海、青的草原、黄的荒漠、灰的戈壁和独特的民族文化。京新高速公路沿线植被变化的主要影响因素是（ ）。","options":[{"key":"A","text":"气温"},{"key":"B","text":"降水"},{"key":"C","text":"地形"},{"key":"D","text":"河流"}],"answer":"B","explanation":"京新高速大致呈东西走向，我国降水从东南沿海向西北内陆逐渐减少；自东向西距海越来越远，水汽难以到达，降水逐渐减少，植被由林海、草原逐渐过渡为荒漠、戈壁，因此主要影响因素是降水。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市中考地理试题第21题","stem":"每年3、4月，由齐齐哈尔开往抚远的K5161次“插秧专列”满载“插秧客”前去春耕。该线路经过的主要地形区是（ ）。","options":[{"key":"A","text":"黄土高原"},{"key":"B","text":"华北平原"},{"key":"C","text":"内蒙古高原"},{"key":"D","text":"东北平原"}],"answer":"D","explanation":"齐齐哈尔至抚远的线路位于东北地区，经过的主要地形区是东北平原；东北平原地势平坦、土壤肥沃，适宜大规模机械化耕作，是我国机械化程度最高、提供商品粮最多的粮食生产基地。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市中考地理试题第24题","stem":"青藏高原空气稀薄，太阳辐射强。依托丰富的太阳能资源，在青藏高原的荒漠上建造了多个光伏电站。青藏高原太阳辐射强的主要原因是（ ）。","options":[{"key":"A","text":"纬度低"},{"key":"B","text":"海拔高"},{"key":"C","text":"距海近"},{"key":"D","text":"风力强"}],"answer":"B","explanation":"青藏高原海拔高，空气稀薄，大气对太阳辐射的削弱作用弱，到达地面的太阳辐射多，所以太阳辐射强；纬度低会使太阳高度角大，但不是青藏高原太阳辐射强的主要原因，距海远近和风力强弱与太阳辐射强弱无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考地理试题第13题","stem":"下列做法不利于保护世界自然遗产的是（ ）","options":[{"key":"A","text":"普及全社会自然遗产保护意识"},{"key":"B","text":"科学划分自然遗产保护区"},{"key":"C","text":"积极参与保护自然遗产的国际合作"},{"key":"D","text":"大力开发自然遗产的旅游资源"}],"answer":"D","explanation":"普及保护意识、科学划分保护区、参与国际合作都有助于保护世界自然遗产；大力开发旅游资源可能导致生态破坏、环境污染和野生动物栖息地碎片化，不利于保护。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省广安市中考地理试题第25题（非选择题改编为选择题，只改呈现形式，知识点与答案未改）","stem":"台湾是中国领土不可分割的一部分。福州至台北的高速铁路是我国《国家综合立体交通网规划纲要》（2021—2035）规划建设的一条重要线路。规划中的福台高铁将跨越台湾海峡，推测高铁建设过程中在台湾海峡可能遇到的气象灾害有（ ）","options":[{"key":"A","text":"台风"},{"key":"B","text":"寒潮"},{"key":"C","text":"沙尘暴"},{"key":"D","text":"霜冻"}],"answer":"A","explanation":"台湾海峡地处我国东南沿海，属于亚热带、热带海域，夏秋季节多台风，同时受季风气候影响，降水丰富，易出现暴雨等气象灾害，会对高铁建设造成威胁；寒潮、沙尘暴、霜冻主要影响北方和内陆地区，不是台湾海峡的主要气象灾害。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第36题","stem":"新疆吐鲁番盆地（43°N，90°E）的夏季，嵌在沙窝里的鸡蛋能被地温烤熟。吐鲁番盆地位于我国（ ）","options":[{"key":"A","text":"南方地区"},{"key":"B","text":"北方地区"},{"key":"C","text":"西北地区"},{"key":"D","text":"青藏地区"}],"answer":"C","explanation":"吐鲁番盆地位于新疆维吾尔自治区，从四大地理区域划分来看，新疆属于我国的西北地区；南方地区主要包括秦岭—淮河以南的广大地区，北方地区主要是秦岭—淮河以北的地区，青藏地区主要是青藏高原及周边区域，吐鲁番盆地都不属于这些地区。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省达州市中考地理试题第20题","stem":"两岸同宗同祖，台湾省人口最多的民族是（ ）","options":[{"key":"A","text":"土家族"},{"key":"B","text":"壮族"},{"key":"C","text":"汉族"},{"key":"D","text":"朝鲜族"}],"answer":"C","explanation":"台湾省人口最多的民族是汉族，约占台湾总人口的98%，主要是明清以来从福建、广东等地迁入的汉族后裔；土家族主要分布在湖南、湖北等地，壮族主要分布在广西，朝鲜族主要分布在东北地区。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第8题（原题依托“闯关东”示意图，图中迁出、迁入省区信息已略去，改为直接设问，知识点与答案未改）","stem":"“闯关东”是指人口从黄河下游地区迁往东北地区。“闯关东”人口主要迁出区是（ ）","options":[{"key":"A","text":"豫、晋、吉"},{"key":"B","text":"豫、黑、鲁"},{"key":"C","text":"辽、晋、鲁"},{"key":"D","text":"豫、冀、鲁"}],"answer":"D","explanation":"豫是河南、冀是河北、鲁是山东的简称，黄河下游地区主要是山东、河北、河南；吉、黑、辽是吉林、黑龙江、辽宁的简称，是“闯关东”时主要的人口迁入地。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省泸州市中考地理试题第14题","stem":"三江源生态系统服务于河流的主要功能是（ ）","options":[{"key":"A","text":"保持水土"},{"key":"B","text":"防风固沙"},{"key":"C","text":"调节气候"},{"key":"D","text":"涵养水源"}],"answer":"D","explanation":"三江源被称为“中华水塔”，其高寒草甸、湿地生态系统能蓄积冰雪融水和降水，涵养水源，保障长江、黄河、澜沧江的水量；保持水土、防风固沙、调节气候也是其功能，但服务于河流的主要功能是涵养水源。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市中考地理试题第17题（D选项原文截断，补写明显错误的干扰项“利于防风沙”，知识点与答案未改）","stem":"贵州某地石板房民居屋顶坡度较大，其主要目的是（ ）","options":[{"key":"A","text":"利于通风"},{"key":"B","text":"利于排水"},{"key":"C","text":"利于保暖"},{"key":"D","text":"利于防风沙"}],"answer":"B","explanation":"贵州属亚热带季风气候，降水丰富，石板房坡度大的屋顶便于雨水快速排走，防止渗漏；通风、保暖不是坡度大的主因；贵州降水多、不是风沙区，防风沙与屋顶坡度无关。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第10题","stem":"下列关于拉萨河下游河谷粮食生产条件的叙述，正确的是（ ）①地势很低，热量丰富②灌溉水源充足③地形平坦④土壤肥沃","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"D","explanation":"拉萨河谷地势平坦、土壤肥沃，河水可作灌溉水源，②③④正确；拉萨河谷海拔约3600米，地势高、热量不足，“地势很低，热量丰富”错误，①排除。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省宜宾市中考地理试题第9题","stem":"凤堰村村民将山坡改造成梯田，梯田有利于（ ）","options":[{"key":"A","text":"调节气候"},{"key":"B","text":"美化环境"},{"key":"C","text":"蓄水保土"},{"key":"D","text":"防风固沙"}],"answer":"C","explanation":"山坡改造成梯田后，坡面变缓，能拦蓄雨水、减少水土流失，蓄水保土是梯田最主要的作用；调节气候、美化环境不是主因；防风固沙是干旱、半干旱地区植树种草的作用。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省宜宾市中考地理试题第18题","stem":"宜宾适宜竹生长的气候特点是（ ）","options":[{"key":"A","text":"温暖湿润"},{"key":"B","text":"炎热干燥"},{"key":"C","text":"冬冷夏热"},{"key":"D","text":"寒冷干燥"}],"answer":"A","explanation":"宜宾地处四川盆地南缘，属亚热带季风气候，温暖湿润、雨热同期，适宜竹子生长；炎热干燥、寒冷干燥都不符合宜宾的气候。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-qinling-huaihe","stem":"秦岭—淮河一线大致与下列哪组界线接近","options":[{"key":"A","text":"7 月 0℃ 等温线和年降水量 400 毫米等降水量线"},{"key":"B","text":"黑河—腾冲线"},{"key":"C","text":"第二、三级阶梯分界线"},{"key":"D","text":"1 月 0℃ 等温线和年降水量 800 毫米等降水量线"}],"answer":"D","explanation":"秦岭—淮河大致接近 1 月 0℃ 等温线和年降水量 800 毫米线，两侧南暖湿、北冷干。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-northeast-grain","stem":"东北三省很多地方农作物一年一熟，主要的限制因素是","options":[{"key":"A","text":"热量条件"},{"key":"B","text":"水源条件"},{"key":"C","text":"土壤肥力"},{"key":"D","text":"地形条件"}],"answer":"A","explanation":"东北纬度较高，热量条件相对受限；平原广、黑土肥沃利于商品粮生产。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-loess-conservation","stem":"黄土高原治理水土流失，在不宜耕作的陡坡上应该","options":[{"key":"A","text":"修建大型工厂"},{"key":"B","text":"恢复植被"},{"key":"C","text":"开垦梯田种粮"},{"key":"D","text":"扩大放牧规模"}],"answer":"B","explanation":"缓坡可修梯田，陡坡恢复植被，沟谷建淤地坝拦泥沙，要按坡面位置选措施。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-northwest-oases","stem":"塔里木盆地的绿洲主要分布在","options":[{"key":"A","text":"高山的顶部"},{"key":"B","text":"沙漠腹地"},{"key":"C","text":"盆地边缘的山麓和河流附近"},{"key":"D","text":"盆地中心"}],"answer":"C","explanation":"找绿洲先沿山麓和河流找水，灌溉常靠河水和高山冰雪融水。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-tibetan-river-valleys","stem":"青藏地区一些河谷能种植青稞，主要原因是","options":[{"key":"A","text":"青藏高原整体气候温暖"},{"key":"B","text":"这里降水特别丰富"},{"key":"C","text":"这里是黑土分布区"},{"key":"D","text":"河谷海拔相对较低、热量较好，并有灌溉水源"}],"answer":"D","explanation":"青藏地区以高寒为主要特征；部分河谷海拔相对低、热量较好且有水源，所以能种青稞。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"东北平原的黑土肥沃，被誉为“____”；我国最大的商品粮基地在____平原。","answer":["北大仓","东北"],"explanation":"东北地区是我国重要的老工业基地。"},{"type":"blank","stem":"长江三角洲地区以____为中心，是我国经济最发达的地区之一。","answer":["上海"],"explanation":"长三角被称为“鱼米之乡”，水乡特色明显。"},{"type":"blank","stem":"香港和澳门的经济支柱之一分别是金融业和____业。","answer":["旅游"],"explanation":"港澳与珠三角形成“前店后厂”的合作模式，现建设粤港澳大湾区。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版八年级下册“中国的地理差异”编写","kind":"综合题","material":"","stem":"我国四大地理区域是如何划分的？请说出各区域最主要的自然地理特征。（8分）","points":[{"text":"北方地区与南方地区以秦岭—淮河一线为界","score":2},{"text":"北方地区：温带季风气候，冬冷夏热，耕地多为旱地；南方地区：亚热带季风气候，夏季高温多雨，耕地多为水田","score":2},{"text":"西北地区：深居内陆，降水稀少，气候干旱","score":2},{"text":"青藏地区：地势高，气候高寒","score":2}],"score":8,"sample":"","explanation":"划分依据：地理位置、自然地理特征和人文地理特征。"},{"type":"essay","tag":"综合题","source":"依据人教版八年级下册“黄土高原”编写","kind":"综合题","material":"","stem":"黄土高原水土流失严重的原因有哪些？治理措施有哪些？（8分）","points":[{"text":"自然原因：黄土土质疏松，多孔隙，易被侵蚀；降水集中在夏季且多暴雨；植被覆盖率低","score":3},{"text":"人为原因：过度开垦、过度放牧、乱砍滥伐、开矿","score":2},{"text":"治理：植树种草，退耕还林还草；打坝建库，修建梯田、淤地坝；合理开采","score":3}],"score":8,"sample":"","explanation":"黄土高原是世界上最大的黄土堆积区，千沟万壑、支离破碎。"}]}]},{"id":"xiaosimen-dili-5","group":"地理","subject":"地理","term":"九年级上册","title":"地理 · 九年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年四川省内江市中考地理试题第3题","stem":"一年中M（正午日影）最短时，河南登封（31.5°N，北半球）太阳直射（ ）","options":[{"key":"A","text":"31.5°N"},{"key":"B","text":"23.5°N"},{"key":"C","text":"0°纬线"},{"key":"D","text":"23.5°S"}],"answer":"B","explanation":"正午日影最短说明正午太阳高度最大，北回归线及其以北地区夏至日时正午太阳高度最大，此时太阳直射北回归线23.5°N。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市中考地理试题第7题","stem":"为践行“绿色考察”理念，2025年3月在我国南极秦岭科考站建设的首个多能互补清洁能源系统正式交付使用。该清洁能源系统的使用主要是为了（ ）。","options":[{"key":"A","text":"促进资源开采"},{"key":"B","text":"保护极地生态"},{"key":"C","text":"降低考察成本"},{"key":"D","text":"加快科考进程"}],"answer":"B","explanation":"从“绿色考察”的理念看，所使用的能源要清洁无污染；南极地区全年酷寒干燥、多狂风，风能和太阳能丰富；使用清洁能源是为了保护南极地区的生态环境，而不是为了开采矿产、降低成本或加快科考进程。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市中考地理试题第13题（原题依托巴西地形及大豆主产区示意图，图中巴西西北部为亚马孙平原、地势较低，东南部为巴西高原、地势较高的信息改写为文字，知识点、选项与答案未改）","stem":"大豆是一种温带作物，引入巴西之初仅在其南部一些地区种植，现已在其热带地区广泛种植。巴西西北部为亚马孙平原，地势较低，东南部为巴西高原，地势较高。巴西地势大致为（ ）。","options":[{"key":"A","text":"西高东低"},{"key":"B","text":"东北高、西南低"},{"key":"C","text":"北高南低"},{"key":"D","text":"东南高、西北低"}],"answer":"D","explanation":"巴西西北部为亚马孙平原，地势较低，东南部为巴西高原，地势较高，故巴西地势大致为东南高、西北低。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽省初中（八年级）学业水平考试地理试题第1题","stem":"近年来，我国智慧城乡建设日趋完善，智慧路灯、智能交通信号灯等的使用，提高了通行效率，增强了居民的幸福感。某中学地理兴趣小组对安徽省某市进行实地调查，发现该市智慧路灯一般在日落后10—30分钟开启，且智慧路灯开启时刻有明显的季节差异。该市智慧路灯平均开启时刻最晚的季节是（ ）。","options":[{"key":"A","text":"春季"},{"key":"B","text":"夏季"},{"key":"C","text":"秋季"},{"key":"D","text":"冬季"}],"answer":"B","explanation":"智慧路灯在日落后开启，开启时刻取决于日落时间；夏季北半球昼长夜短，日落时间最晚，路灯开启时刻最迟；春季昼夜接近平分，日落早于夏季，秋季日落早于夏季，冬季昼最短、日落最早。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考地理试题第2题","stem":"假设一架时速约800千米/小时的飞机环赤道一周，所需的时间大约是（ ）","options":[{"key":"A","text":"30小时"},{"key":"B","text":"40小时"},{"key":"C","text":"50小时"},{"key":"D","text":"60小时"}],"answer":"C","explanation":"赤道周长约4万千米，4万千米÷800千米/小时=50小时。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省广安市中考地理试题第10题","stem":"澳大利亚保留古老物种的根本原因是（ ）","options":[{"key":"A","text":"气候干旱，沙漠广布"},{"key":"B","text":"地处热带，热量充足"},{"key":"C","text":"远离大陆，长期孤立"},{"key":"D","text":"地处高原，地层古老"}],"answer":"C","explanation":"澳大利亚与其他大陆分离后，物种独立演化，免受其他大陆物种竞争和干扰，从而保留古老特征；气候干旱不是根本原因，A错误；澳大利亚北部为热带，但热量充足并非古老物种保留的原因，B错误；地势较平坦，地层古老与物种保留无直接关系，D错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省深圳市中考地理试题（荷兰风车与肯尼亚鲜花组）第2题","stem":"与荷兰相比，发展中国家的花卉种植业存在（ ）的优势。","options":[{"key":"A","text":"科技水平高"},{"key":"B","text":"生产历史悠久"},{"key":"C","text":"离欧洲市场较近"},{"key":"D","text":"劳动成本较低"}],"answer":"D","explanation":"花卉种植是一种劳动密集型农业，需要大量劳动力，发展中国家人口众多，劳动力丰富，生产成本低廉，所以劳动成本较低是发展中国家花卉种植业的优势；科技水平高、花卉种植历史悠久、距离欧洲市场近是荷兰的优势。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省深圳市中考地理试题（北美洲组）第3题","stem":"灾害来临时，个人采取的防灾措施正确的是（ ）","options":[{"key":"A","text":"寒潮来临时，衣着注意防寒保暖"},{"key":"B","text":"泥石流来临时，顺山坡往下跑"},{"key":"C","text":"地震来临时，迅速跳楼逃生"},{"key":"D","text":"台风来临时，站在广告牌下躲避"}],"answer":"A","explanation":"寒潮来临，气温会大幅度下降，应多加衣服，注意防寒保暖，A正确；发生泥石流时，应向垂直于泥石流流动方向的山坡上跑，B错误；地震来临时，不能跳楼，可以躲在狭窄的空间里或桌子下面，C错误；台风来临，在街上不能站在广告牌下，容易被掉落物体砸到，D错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年广东省深圳市中考地理试题（端午节粽子组）第3题","stem":"粽子是非物质文化遗产，利于传播到（ ）地区。","options":[{"key":"A","text":"东南亚"},{"key":"B","text":"西亚"},{"key":"C","text":"西欧"},{"key":"D","text":"拉丁美洲"}],"answer":"A","explanation":"粽子由粽叶包裹糯米蒸制而成，糯米是水稻的一种，喜欢湿热的气候环境；东南亚绝大部分位于热带，主要是热带雨林气候和热带季风气候，全年高温、降水丰沛，有利于水稻生长，且东南亚距离中国较近，是世界上华人、华侨最集中的地区，所以粽子利于传播到东南亚。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第13题","stem":"中欧班列为“一带一路”沿线国家带来的机遇不包括（ ）","options":[{"key":"A","text":"带动了沿线地区的就业增长"},{"key":"B","text":"促进了商品和服务的互通有无"},{"key":"C","text":"限制了国家间的文化交流与合作"},{"key":"D","text":"提供了更多投资机会和合作项目"}],"answer":"C","explanation":"中欧班列通过铁路运输、物流仓储、贸易服务等环节，直接或间接创造了大量就业机会，带动了沿线地区的就业增长；班列实现了中欧间商品的双向流通，并推动金融、保险等配套服务发展，促进了贸易互通；班列带动了沿线铁路升级、物流园区建设及企业投资，扩大了合作空间；班列并未限制文化交流与合作，反而是桥梁，贸易商、技术人员随班列流动，促进了文化互动。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省达州市中考地理试题第8题","stem":"小明妈妈在网上购买的商品刚好搭乘中欧班列回国，该商品最有可能是（ ）","options":[{"key":"A","text":"泰国香米"},{"key":"B","text":"澳大利亚羊毛衫"},{"key":"C","text":"巴西咖啡"},{"key":"D","text":"法国葡萄酒"}],"answer":"D","explanation":"中欧班列往返于中国与欧洲之间，从欧洲回国的商品最有可能是法国葡萄酒；泰国香米来自东南亚，澳大利亚羊毛衫来自大洋洲，巴西咖啡来自南美洲，都不走中欧班列回国。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省乐山市中考地理试题第15题（原题依托两洋铁路分布示意图，改为直接设问，知识点、选项与答案未改）","stem":"第一条横穿南美洲的大陆桥——“两洋铁路（钱凯—伊列乌斯）”正在建设中，巴西是资源大国。两洋铁路途经最主要的地形是（ ）","options":[{"key":"A","text":"平原"},{"key":"B","text":"山地"},{"key":"C","text":"盆地"},{"key":"D","text":"高原"}],"answer":"D","explanation":"两洋铁路大部分线路在巴西高原上，巴西高原是世界面积最大的高原；经过平原、山地、盆地的路段较短。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省内江市中考地理试题第20题第（1）小问（原题为填空题，改编为单选题，知识点与答案未改）","stem":"摩洛哥是中国倡导的“一带一路”沿线国家。摩洛哥（ ）矿产丰富。","options":[{"key":"A","text":"磷矿"},{"key":"B","text":"煤矿"},{"key":"C","text":"铁矿"},{"key":"D","text":"石油"}],"answer":"A","explanation":"摩洛哥磷矿（磷灰石）丰富；摩洛哥不是以煤矿、铁矿、石油著称的国家。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第3题","stem":"2025年春节这天（1月29日），眉山市的昼夜长短状况是（ ）","options":[{"key":"A","text":"昼长夜短"},{"key":"B","text":"昼短夜长"},{"key":"C","text":"昼夜等长"},{"key":"D","text":"极昼"}],"answer":"B","explanation":"1月29日太阳直射南半球，北半球昼短夜长；眉山在北半球，春节时昼短夜长；极昼只出现在极圈以内，眉山纬度约30°N，不可能极昼。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第15题","stem":"由图可知，有红树林海岸分布的大洲共（ ）","options":[{"key":"A","text":"3个"},{"key":"B","text":"4个"},{"key":"C","text":"5个"},{"key":"D","text":"6个"}],"answer":"C","explanation":"红树林生长在热带、亚热带海岸，分布于亚洲、非洲、北美洲、南美洲、大洋洲，共5个大洲；欧洲、南极洲没有红树林海岸分布。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-coordinates","stem":"经度为 170°E 的地点位于","options":[{"key":"A","text":"西半球"},{"key":"B","text":"东半球"},{"key":"C","text":"东、西半球的分界线上"},{"key":"D","text":"无法判断在哪个半球"}],"answer":"A","explanation":"东西半球以 20°W 和 160°E 组成的经线圈划分。东经不都在东半球，170°E 在西半球。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-earth-motion","stem":"北半球夏至日这一天，太阳直射","options":[{"key":"A","text":"北极圈"},{"key":"B","text":"北回归线"},{"key":"C","text":"赤道"},{"key":"D","text":"南回归线"}],"answer":"B","explanation":"地轴倾斜且地球公转，直射点随季节移动；北半球夏至日太阳直射北回归线。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-map-scale","stem":"下列比例尺中，比例尺最大的是","options":[{"key":"A","text":"1∶500000"},{"key":"B","text":"1∶5000000"},{"key":"C","text":"1∶5000"},{"key":"D","text":"1∶50000"}],"answer":"C","explanation":"比例尺 = 图上距离 ÷ 实地距离，分母越小比例尺越大；1∶5000 大于 1∶50000。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-asia-relief","stem":"亚洲的地势特点和河流流向是","options":[{"key":"A","text":"西高东低，河流都自西向东流"},{"key":"B","text":"四周高、中部低，河流流向中部"},{"key":"C","text":"地势平坦，河流流向不定"},{"key":"D","text":"中部高、四周低，许多大河从中部流向四周"}],"answer":"D","explanation":"亚洲地势中部高、四周低，不少大河发源于中部高地，流向周边海洋（也有内流河）。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-japan-ports","stem":"日本工业主要分布在太平洋沿岸和濑户内海沿岸，主要原因是","options":[{"key":"A","text":"临近港口，便于进口原料燃料和出口产品"},{"key":"B","text":"这里矿产资源特别丰富"},{"key":"C","text":"这里气候寒冷"},{"key":"D","text":"这里地势高"}],"answer":"A","explanation":"日本原料、燃料多靠进口，产品多出口；临港便于海运。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"地图的三要素是比例尺、____和图例与注记。","answer":["方向"],"explanation":"一般地图“上北下南，左西右东”；有指向标的按指向标定方向。"},{"type":"blank","stem":"俄罗斯的____铁路是世界上最长的铁路。","answer":["西伯利亚"],"explanation":"俄罗斯是世界上面积最大的国家，地跨亚欧两洲。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据人教版七年级上册“海陆的变迁”编写","kind":"简答题","material":"","stem":"板块构造学说的主要观点是什么？请据此解释喜马拉雅山脉的形成。（6分）","points":[{"text":"由岩石组成的地球表层并不是整体一块，而是由六大板块拼合而成","score":2},{"text":"板块处于不断运动之中；板块内部比较稳定，板块交界地带地壳比较活跃，多火山、地震","score":2},{"text":"喜马拉雅山脉位于亚欧板块与印度洋板块的碰撞挤压地带，碰撞挤压隆起形成","score":2}],"score":6,"sample":"","explanation":"板块张裂形成裂谷或海洋（如东非大裂谷、红海），碰撞挤压形成山脉。"},{"type":"essay","tag":"综合题","source":"依据人教版七年级下册“中东”编写","kind":"综合题","material":"","stem":"中东地区为什么成为世界上的“热点地区”？（6分）","points":[{"text":"地理位置重要：位于“两洋三洲五海”之地，交通要道（苏伊士运河、土耳其海峡、霍尔木兹海峡）","score":2},{"text":"石油资源丰富，是世界石油储量最大、出口量最多的地区","score":2},{"text":"水资源匮乏；民族、宗教、文化复杂，领土争端等","score":2}],"score":6,"sample":"","explanation":"中东石油主要分布在波斯湾及其沿岸地区，主要通过波斯湾运往西欧、美国、日本等。"}]}]},{"id":"xiaosimen-dili-6","group":"地理","subject":"地理","term":"九年级下册","title":"地理 · 九年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025年安徽省初中（八年级）学业水平考试地理试题第3题","stem":"在江淮沃野上，现代化的汽车工厂如雨后春笋般纷纷崛起，勾勒出安徽“智”造的壮丽图景。近年来，安徽省依托前瞻性产业政策、尖端科技赋能与全产业链协同发展优势，在汽车领域掀起创新浪潮。2022—2024年全省汽车总产量由全国第七位攀升至全国第二位，2024年全省汽车出口量登顶全国首位。安徽省汽车产业的快速发展，能够（ ）。","options":[{"key":"A","text":"增加居民就业机会"},{"key":"B","text":"改变能源供给类型"},{"key":"C","text":"缓解城乡道路拥堵"},{"key":"D","text":"减少工业用地面积"}],"answer":"A","explanation":"汽车产业属于劳动密集型产业，工厂增多会创造更多就业岗位；能源供给类型与能源结构相关，题干未提及能源转型；汽车产量增加可能加剧交通压力，而非缓解拥堵；产业发展通常需要扩大用地规模，而不是减少用地面积。"},{"type":"choice","tag":"Claude 精选","source":"2025年安徽省初中（八年级）学业水平考试地理试题第6题","stem":"粮食安全是国家安全的基本物质保障。改革开放以来，我国累计已建成10亿亩高标准农田。得益于农业科技的快速发展，我国人均占有粮食显著增加，粮食品质逐渐提高，人民食物消费结构升级，实现了从温饱不足到吃饱吃好的历史性转变。为保障优质农产品稳定供给，我国走科技强农之路的做法有（ ）。①培育高产优质品种 ②增加粮食进口数量 ③提高农业灌溉技术 ④使用大量化肥农药","options":[{"key":"A","text":"①②"},{"key":"B","text":"①③"},{"key":"C","text":"②④"},{"key":"D","text":"③④"}],"answer":"B","explanation":"培育高产优质品种可以提高粮食的产量和品质，①正确；增加粮食进口数量不属于走科技强农之路，②错误；提高农业灌溉技术能够合理利用水资源、保障农作物生长所需水分、提高农业生产效率和农产品质量，③正确；使用大量化肥农药会造成环境污染、土壤板结等问题，不利于农业的可持续发展，④错误。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年江苏省宿迁市中考地理试题第25题（原题依托2021—2023年江苏省人口相关数据统计表，表中常住人口、出生率、死亡率、出生人口数据改写为文字，知识点、选项与答案未改）","stem":"2021—2023年江苏省人口相关数据统计表显示：2021年常住人口8505.40万，出生率5.65‰，死亡率6.77‰，出生人口48.06万；2022年常住人口8515.00万，出生率5.23‰，死亡率7.04‰，出生人口44.53万；2023年常住人口8526.00万，出生率4.81‰，死亡率7.55‰，出生人口41.00万。从表中可以看出，江苏省（ ）","options":[{"key":"A","text":"常住人口增加"},{"key":"B","text":"出生率上升"},{"key":"C","text":"死亡率下降"},{"key":"D","text":"出生人口增多"}],"answer":"A","explanation":"常住人口从2021年的8505.40万增至2023年的8526.00万，逐年增加，A符合题意；出生率从5.65‰降至4.81‰，呈下降趋势，B错误；死亡率从6.77‰升至7.55‰，逐年上升，C错误；出生人口从48.06万降至41.00万，持续减少，D错误。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第28题","stem":"当前，京杭大运河江苏段成为“黄金水道”，原因是（ ）①水量丰富②水流湍急③经济发达④历史悠久","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"②③④"},{"key":"D","text":"①③④"}],"answer":"D","explanation":"京杭大运河江苏段位于东部季风区，水量丰富，利于航运，①正确；江苏段地势平坦，水流平缓，不是湍急，②错误；江苏段沿线经济发达，运输需求大，③正确；京杭大运河历史悠久，江苏段作为其中一段，航运基础好，④正确。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第33题","stem":"港珠澳大桥、深珠通道（规划中）和深中通道，是粤港澳大湾区的核心交通枢纽工程，集“桥、岛、隧”于一体，是世界上综合建设难度大的跨海集群工程。港珠澳大桥位于（ ）","options":[{"key":"A","text":"长江入海口"},{"key":"B","text":"黄河入海口"},{"key":"C","text":"钱塘江入海口"},{"key":"D","text":"珠江入海口"}],"answer":"D","explanation":"港珠澳大桥连接香港、珠海、澳门，位于珠江入海口处；长江入海口在上海附近，黄河入海口在山东，钱塘江入海口在浙江杭州湾，港珠澳大桥都不在这些地方。"},{"type":"choice","tag":"Claude 精选","source":"2025年江苏省宿迁市中考地理试题第38题","stem":"2024年7月27日北京中轴线被列入《世界遗产名录》。明清时期，故宫（皇宫）在中轴线上，体现其（ ）","options":[{"key":"A","text":"政治中心"},{"key":"B","text":"经济中心"},{"key":"C","text":"军事中心"},{"key":"D","text":"交通中心"}],"answer":"A","explanation":"明清时期的故宫是皇帝居住和处理国家政务的场所，是全国最高权力机关所在地；中轴线是中国古代都城和宫殿建筑中体现皇权至上、等级秩序的核心布局，故宫位于中轴线上，直接彰显了其作为全国政治核心的地位；经济中心通常对应商业区、市集等，军事中心多为军营、要塞等，交通中心则是道路枢纽地带，都与故宫的功能和布局不符。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省达州市中考地理试题第1题（原题依托疆电入渝工程规划图，图中哈密、重庆位置信息已略去，改为直接设问“哈密位于重庆的哪个方向”，知识点与答案未改）","stem":"疆电入渝工程是将新疆的电力输送到重庆的跨区域能源调配工程。哈密位于重庆的（ ）","options":[{"key":"A","text":"东北方向"},{"key":"B","text":"西北方向"},{"key":"C","text":"东南方向"},{"key":"D","text":"西南方"}],"answer":"B","explanation":"哈密位于新疆东部（约93.5°E，42.8°N），重庆位于西南地区（约106.5°E，29.5°N），与重庆相比，哈密纬度更高、经度更小，即位于重庆的西北方向。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省达州市中考地理试题第14题（原题依托北京降水量柱状图，改为直接设问“北京降水量最多的月份是”；A选项在来源文本中截断，按补写干扰选项规则补为明显错误的“1月”，北京1月降水量最少，知识点与答案未改）","stem":"北京降水量最多的月份是（ ）","options":[{"key":"A","text":"1月"},{"key":"B","text":"4月"},{"key":"C","text":"7月"},{"key":"D","text":"10月"}],"answer":"C","explanation":"北京属于温带季风气候，降水集中在夏季，7、8月降水最多，7月为全年降水量最多的月份；1月、4月、10月降水都远少于7月。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省乐山市中考地理试题第7题（原题依托长江上游梯级电站分布示意图，图中各电站所在河段信息已略去，改为直接设问，知识点、选项与答案未改）","stem":"长江上游建有6大梯级电站。下列梯级电站中，位于金沙江（玉树至宜宾）河段的是（ ）","options":[{"key":"A","text":"三峡、乌东德"},{"key":"B","text":"葛洲坝、白鹤滩"},{"key":"C","text":"乌东德、溪洛渡"},{"key":"D","text":"三峡、葛洲坝"}],"answer":"C","explanation":"乌东德、白鹤滩、溪洛渡电站位于金沙江（玉树至宜宾）河段；三峡和葛洲坝位于川江（宜宾至宜昌）河段。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省乐山市中考地理试题第10题","stem":"白鹤滩电站每年可向华东输电超600亿千瓦时，替代燃煤约两千万吨，减少二氧化碳排放超五千万吨；与干流其他工程协调，进一步保障长江中下游汛期安全；“高峡平湖—曲坝飞架”成为网红打卡地。白鹤滩电站带来的效益有（ ）①发电②防洪③旅游④采煤⑤生态","options":[{"key":"A","text":"①②③⑤"},{"key":"B","text":"②③④⑤"},{"key":"C","text":"①③④⑤"},{"key":"D","text":"①②③④"}],"answer":"A","explanation":"向华东输电超600亿千瓦时是发电效益①；保障汛期安全是防洪效益②；网红打卡地是旅游效益③；替代燃煤、减排二氧化碳是生态效益⑤；白鹤滩是水电站，与采煤无关，④错误。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省南充市中考地理试题第9题（D选项原文缺失，按①②③④组合规律补写为“②③④”，知识点与答案未改）","stem":"吸引该集团到南充建立新能源商用车生产基地的主要原因是（ ）①政府政策支持②土地资源丰富③劳动力丰富④科技发达","options":[{"key":"A","text":"①②③"},{"key":"B","text":"①②④"},{"key":"C","text":"①③④"},{"key":"D","text":"②③④"}],"answer":"A","explanation":"南充作为内陆城市，吸引新能源商用车生产基地靠的是政府政策支持、土地资源丰富、劳动力丰富，①②③正确；南充科技水平与沿海发达地区相比不占优势，④不是主要原因。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省眉山市中考地理试题第18题","stem":"遭遇洪水时，下列做法正确的是（ ）","options":[{"key":"A","text":"在河谷中，向河谷下游转移"},{"key":"B","text":"在城市中，向高层建筑转移"},{"key":"C","text":"在乘车时，催促司机加速行驶"},{"key":"D","text":"在电杆旁，迅速爬上电线杆"}],"answer":"B","explanation":"城市遭遇洪水时，向高层建筑转移能躲避洪水，B正确；在河谷中应向高处转移，向下游走会被洪水追上，A错误；乘车遇洪水催促加速行驶容易熄火、被冲走，C错误；电杆旁爬电线杆有触电危险，D错误。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市中考地理试题第29题（非选择题改编为多选题，只改呈现形式，知识点与答案未改）；原题为 5 项多选（4 项正确），改编为单选“不属于”（选项为其中 3 项正确 + 1 项错误）","stem":"下列不属于粤港澳大湾区发展人形机器人产业有利条件的是（ ）。","options":[{"key":"A","text":"政策支持"},{"key":"B","text":"科技力量雄厚"},{"key":"C","text":"产业基础好"},{"key":"D","text":"矿产资源丰富"}],"answer":"D","explanation":"粤港澳大湾区发展人形机器人产业的有利条件是政策支持、科技力量雄厚、产业基础好、市场需求大。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市中考地理试题第30题（非选择题改编为多选题，只改呈现形式，知识点与答案未改）；原题为 5 项多选（4 项正确），改编为单选“不属于”（选项为其中 3 项正确 + 1 项错误）","stem":"下列不属于东北三省可开发的冰雪经济项目的是（ ）。","options":[{"key":"A","text":"冰雪旅游"},{"key":"B","text":"冰雪运动培训"},{"key":"C","text":"冰雪赛事"},{"key":"D","text":"热带海滨度假"}],"answer":"D","explanation":"东北三省可开发的冰雪经济项目有冰雪旅游、冰雪运动培训、冰雪赛事、冰雪艺术等。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市中考地理试题第22题（非选择题改编为单选题，只改呈现形式，知识点与答案未改）","stem":"理塘县所处地形区的地形地势特征是（ ）。","options":[{"key":"A","text":"地形以山地和高原为主，地势起伏较大"},{"key":"B","text":"地形以平原为主，地势低平"},{"key":"C","text":"地形以丘陵为主，地势起伏和缓"},{"key":"D","text":"地形以盆地为主，四周高、中间低"}],"answer":"A","explanation":"理塘县地处青藏地区，地形以山地和高原为主，地势起伏较大。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-population","stem":"我国人口分布的重要地理界线是","options":[{"key":"A","text":"长江一线"},{"key":"B","text":"黑河—腾冲线"},{"key":"C","text":"秦岭—淮河一线"},{"key":"D","text":"昆仑山—祁连山一线"}],"answer":"B","explanation":"黑河—腾冲线东南侧人口相对稠密，西北侧相对稀疏；秦岭—淮河是南北方分界。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-steps","stem":"我国地势第一级阶梯的主体是","options":[{"key":"A","text":"华北平原"},{"key":"B","text":"四川盆地"},{"key":"C","text":"青藏高原"},{"key":"D","text":"黄土高原"}],"answer":"C","explanation":"第一级以青藏高原为主，第二级多高原和盆地，第三级多平原和丘陵。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-china-monsoon","stem":"我国年降水量的空间分布规律是","options":[{"key":"A","text":"从西北内陆向东南沿海递减"},{"key":"B","text":"南北各地大致相同"},{"key":"C","text":"从南向北递增"},{"key":"D","text":"从东南沿海向西北内陆递减"}],"answer":"D","explanation":"年降水量大体由东南沿海向西北内陆递减，季节变化要结合夏季风判断。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-qinling-huaihe","stem":"秦岭—淮河一线大致与下列哪组界线接近","options":[{"key":"A","text":"1 月 0℃ 等温线和年降水量 800 毫米等降水量线"},{"key":"B","text":"7 月 0℃ 等温线和年降水量 400 毫米等降水量线"},{"key":"C","text":"黑河—腾冲线"},{"key":"D","text":"第二、三级阶梯分界线"}],"answer":"A","explanation":"秦岭—淮河大致接近 1 月 0℃ 等温线和年降水量 800 毫米线，两侧南暖湿、北冷干。"},{"type":"choice","tag":"Claude 冲刺","kp":"dili-northeast-grain","stem":"东北三省很多地方农作物一年一熟，主要的限制因素是","options":[{"key":"A","text":"地形条件"},{"key":"B","text":"热量条件"},{"key":"C","text":"水源条件"},{"key":"D","text":"土壤肥力"}],"answer":"B","explanation":"东北纬度较高，热量条件相对受限；平原广、黑土肥沃利于商品粮生产。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"我国的四大高原是青藏高原、内蒙古高原、黄土高原和____高原。","answer":["云贵"],"explanation":"四大盆地：塔里木、准噶尔、柴达木、四川盆地。"},{"type":"blank","stem":"台湾岛是我国第一大岛，岛上最高峰是____山，素有“东南盐库”“祖国宝岛”之称。","answer":["玉"],"explanation":"台湾海峡是沟通东海和南海的通道，福建与台湾隔海相望。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版八年级上册“河流”编写","kind":"综合题","material":"","stem":"黄河下游为什么形成“地上河”？治理黄河的根本措施是什么？（6分）","points":[{"text":"黄河中游流经黄土高原，水土流失严重，河水携带大量泥沙","score":2},{"text":"下游地势平坦，水流缓慢，泥沙大量淤积，河床不断抬高，形成“地上河”","score":2},{"text":"根本措施：在中游黄土高原地区做好水土保持（植树种草、退耕还林还草、修建淤地坝等）","score":2}],"score":6,"sample":"","explanation":"黄河上游水能丰富、中游泥沙多、下游地上河、有凌汛现象。"},{"type":"essay","tag":"简答题","source":"依据人教版八年级下册“西北地区”编写","kind":"简答题","material":"","stem":"西北地区为什么气候干旱？当地发展农业的主要方式是什么？（6分）","points":[{"text":"深居内陆，距海遥远","score":2},{"text":"周围多高山阻挡，湿润气流难以到达","score":2},{"text":"农业方式：利用高山冰雪融水发展灌溉农业（绿洲农业），如新疆的坎儿井；草原地区发展畜牧业","score":2}],"score":6,"sample":"","explanation":"新疆光照充足、昼夜温差大，瓜果甜美，长绒棉品质好。"}]}]},{"id":"xiaosimen-shengwu-1","group":"生物","subject":"生物","term":"七年级上册","title":"生物 · 七年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第17题（模拟卷）","stem":"用显微镜观察洋葱表皮细胞装片的同一部位时，选择下列哪种目镜和物镜的组合，视野中的细胞体积最大？（ ）。","options":[{"key":"A","text":"目镜5×物镜40×"},{"key":"B","text":"目镜10×物镜40×"},{"key":"C","text":"目镜10×物镜10×"},{"key":"D","text":"目镜16×物镜10×"}],"answer":"B","explanation":"显微镜的放大倍数＝目镜放大倍数×物镜放大倍数，放大倍数越大，看到的细胞体积越大；A 是 200 倍，B 是 400 倍，C 是 100 倍，D 是 160 倍，所以 B 组合看到的细胞体积最大。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建省初中学业水平考试·生物第2题","stem":"细胞中叶绿体的功能是（ ）。","options":[{"key":"A","text":"起支持作用"},{"key":"B","text":"细胞控制中心"},{"key":"C","text":"能量转换器"},{"key":"D","text":"控制物质进出"}],"answer":"C","explanation":"叶绿体是进行光合作用的场所，能把光能转变成化学能，是细胞中的能量转换器；起支持作用的是细胞壁，控制中心是细胞核，控制物质进出的是细胞膜。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第1题","stem":"2025年10月31日我国成功发射神舟二十一号载人飞船，首次将小鼠送入空间站。小鼠结构和功能的基本单位是（ ）。","options":[{"key":"A","text":"细胞"},{"key":"B","text":"组织"},{"key":"C","text":"器官"},{"key":"D","text":"系统"}],"answer":"A","explanation":"细胞是生物体结构和功能的基本单位，组织、器官、系统都是由细胞构成的更高层次。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第5题","stem":"某同学观察黄瓜果肉细胞时看不清楚，要使视野变亮，应该在使用显微镜时选择（ ）。","options":[{"key":"A","text":"小光圈、平面镜"},{"key":"B","text":"大光圈、平面镜"},{"key":"C","text":"大光圈、凹面镜"},{"key":"D","text":"小光圈、凹面镜"}],"answer":"C","explanation":"视野暗时要增强光线：用大光圈进光多、用凹面镜聚光强，两者配合视野最亮。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第12题","stem":"小丽在植物栽培实践中种植了五彩椒。五彩椒的生殖器官是指它的（ ）。","options":[{"key":"A","text":"根、茎、叶"},{"key":"B","text":"果实和种子"},{"key":"C","text":"花、果实、种子"},{"key":"D","text":"种子"}],"answer":"C","explanation":"绿色开花植物的生殖器官是花、果实、种子，营养器官是根、茎、叶。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第17题","stem":"下列关于杜鹃鸟和杜鹃花的叙述中，错误的是（ ）。","options":[{"key":"A","text":"都是由受精卵发育而来"},{"key":"B","text":"杜鹃鸟比杜鹃花多了“系统”这一结构层次"},{"key":"C","text":"杜鹃花的叶和杜鹃的眼都属于器官"},{"key":"D","text":"杜鹃鸟的骨由保护组织构成"}],"answer":"D","explanation":"骨主要由结缔组织构成，不是保护组织；保护组织是植物的组织，动物没有保护组织。A、B、C 三项都正确。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第20题","stem":"草履虫是一种单细胞动物，下列关于草履虫叙述错误的是（ ）。","options":[{"key":"A","text":"能分裂产生新个体"},{"key":"B","text":"能自己制造有机物"},{"key":"C","text":"能够排出代谢废物"},{"key":"D","text":"通过表膜交换气体"}],"answer":"B","explanation":"草履虫是单细胞动物，没有叶绿体，不能自己制造有机物，要靠摄取食物；它能分裂繁殖、排出废物、通过表膜与外界交换气体。"},{"type":"choice","tag":"Claude 精选","source":"宁化县2025-2026七上生物期中卷 第23题","stem":"鲜豆浆含丰富的蛋白质，素有“绿色牛乳”之称，豆浆中的营养物质主要来自黄豆的（ ）。","options":[{"key":"A","text":"胚芽"},{"key":"B","text":"子叶"},{"key":"C","text":"胚乳"},{"key":"D","text":"胚轴"}],"answer":"B","explanation":"黄豆是双子叶植物，营养物质储存在子叶里；胚乳是单子叶植物（如小麦、玉米）储存营养的结构。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市初中学业水平模拟考试·生物第1题（模拟卷，非中考真题）","stem":"我们所生活的世界是一个到处与生物相伴的大集体。下列关于生物学或生物的相关说法错误的是（ ）。","options":[{"key":"A","text":"生物学包括了对人类的研究"},{"key":"B","text":"生物都是由基本单位细胞构成的"},{"key":"C","text":"生长和繁殖属于生物的基本特征"},{"key":"D","text":"生物学是一门基础科学"}],"answer":"B","explanation":"除病毒以外，生物都是由细胞构成的；病毒没有细胞结构，由蛋白质外壳和内部的遗传物质组成，只能寄生在活细胞内才能进行生命活动；生长和繁殖是生物的基本特征，人类作为生物的一种，也属于生物学的研究范畴。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市初中学业水平模拟考试·生物第5题第(2)小题（模拟卷，非中考真题）","stem":"关于该水培装置的使用和放置事项，不利于菠菜生长的是（ ）。","options":[{"key":"A","text":"海绵上密集固定菠菜苗"},{"key":"B","text":"定期按比例补充营养液"},{"key":"C","text":"放置在通风良好的地方"},{"key":"D","text":"放置在光照充足的地方"}],"answer":"A","explanation":"海绵上密集固定菠菜苗会导致植株之间相互遮挡、通风不良、光照不足，影响菠菜的光合作用和呼吸作用，不利于生长；定期补充营养液、通风良好、光照充足都有利于菠菜生长。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市初中学业水平模拟考试·生物第23题第(2)小题（模拟卷，非中考真题；原为非选择题填空，改为单选题，选项为改编时补写）","stem":"该食物网中，食虫鸟和青蛙都捕食蜘蛛，二者的关系是（ ）。","options":[{"key":"A","text":"捕食关系"},{"key":"B","text":"竞争关系"},{"key":"C","text":"合作关系"},{"key":"D","text":"寄生关系"}],"answer":"B","explanation":"食虫鸟和青蛙都捕食蜘蛛，二者因争夺共同的食物而存在竞争关系；该食物网共有5条食物链，分别是植物→昆虫→蜘蛛→食虫鸟→蛇→鹰、植物→昆虫→蜘蛛→青蛙→蛇→鹰、植物→昆虫→青蛙→蛇→鹰、植物→鼠→蛇→鹰、植物→鼠→鹰。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第7题第(1)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"第17届世界园艺博览会会展园区内的湿地公园吸引了一些珍稀野生动物迁徙而来。黑喉潜鸟迁徙而来，增加了当地的生物多样性；黑喉潜鸟与苍鹭处于相似的营养级，食物资源有限。短期内原有的苍鹭数量会（ ）。","options":[{"key":"A","text":"增加"},{"key":"B","text":"不变"},{"key":"C","text":"减少"},{"key":"D","text":"先增加后减少"}],"answer":"C","explanation":"黑喉潜鸟与苍鹭食性相近、处于相似的营养级，会形成竞争关系；短期内苍鹭的食物资源减少，数量随之减少。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第10题第(2)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"科学家正致力于研究转基因的细菌或酵母菌，使其能高效分解垃圾场中的纤维素，并转化为酒精或可溶性糖类等。利用该转基因细菌可大量处理垃圾中的纤维素，实现变废为宝。为使这项工作顺利开展，在日常生活中，提倡在源头上先对垃圾进行（ ）。","options":[{"key":"A","text":"分类"},{"key":"B","text":"焚烧"},{"key":"C","text":"填埋"},{"key":"D","text":"随意丢弃"}],"answer":"A","explanation":"对垃圾进行分类处理，有利于把含纤维素的垃圾集中起来，便于后续针对性处理，提高资源回收利用率。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第11题第(4)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"生物兴趣小组探究种子萌发的环境条件，⑤号瓶放在透光盒子中，③号瓶放在不透光盒子中，其他条件相同且适宜，几天后③、⑤号瓶内种子几乎都萌发了。根据实验结果，⑤号瓶与③号瓶作对照，说明（ ）。","options":[{"key":"A","text":"光是种子萌发的必要条件"},{"key":"B","text":"光不是种子萌发的必要条件"},{"key":"C","text":"种子萌发必须在黑暗中进行"},{"key":"D","text":"种子萌发必须在光照下进行"}],"answer":"B","explanation":"两瓶唯一变量是光照，结果都萌发，说明有光无光都能萌发，光不是种子萌发的必要条件。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第6题","stem":"桃树枝条上具有分生组织的结构是（ ）。","options":[{"key":"A","text":"形成层"},{"key":"B","text":"筛管"},{"key":"C","text":"导管"},{"key":"D","text":"表皮"}],"answer":"A","explanation":"形成层属于分生组织，细胞能不断分裂产生新细胞，使茎不断加粗；筛管和导管属于输导组织，分别运输有机物和水、无机盐；表皮属于保护组织。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-microscope","stem":"显微镜的目镜是 10×，物镜是 40×，物像的放大倍数是","options":[{"key":"A","text":"40 倍"},{"key":"B","text":"4 倍"},{"key":"C","text":"400 倍"},{"key":"D","text":"50 倍"}],"answer":"C","explanation":"总放大倍数 = 目镜倍数 × 物镜倍数 = 10 × 40 = 400 倍，要用乘法。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-cell-structures","stem":"植物细胞有、而动物细胞没有的结构是","options":[{"key":"A","text":"细胞膜"},{"key":"B","text":"细胞核"},{"key":"C","text":"细胞质"},{"key":"D","text":"细胞壁"}],"answer":"D","explanation":"动、植物细胞都有细胞膜、细胞质、细胞核；植物细胞有细胞壁，许多还有液泡，部分有叶绿体。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-cell-to-organism","stem":"一片完整的叶，在结构层次上属于","options":[{"key":"A","text":"器官"},{"key":"B","text":"组织"},{"key":"C","text":"细胞"},{"key":"D","text":"系统"}],"answer":"A","explanation":"整片叶是器官，叶表皮是保护组织；植物体没有“系统”这一层次。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-plant-groups","stem":"裸子植物和被子植物最主要的区别是","options":[{"key":"A","text":"能不能进行光合作用"},{"key":"B","text":"种子外面有没有果皮包被"},{"key":"C","text":"能不能产生种子"},{"key":"D","text":"有没有根、茎、叶"}],"answer":"B","explanation":"裸子植物和被子植物都结种子，关键看种子外有无果皮包被。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-bacteria-and-fungi","stem":"细菌与真菌最主要的区别是","options":[{"key":"A","text":"细菌都由多个细胞构成"},{"key":"B","text":"真菌都是单细胞生物"},{"key":"C","text":"细菌没有成形的细胞核"},{"key":"D","text":"细菌没有遗传物质"}],"answer":"C","explanation":"细菌没有成形的细胞核，但有遗传物质；真菌有成形的细胞核，酵母菌是单细胞真菌。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"除病毒以外，生物都是由____构成的。","answer":["细胞"],"explanation":"病毒没有细胞结构，由蛋白质外壳和内部的遗传物质组成。"},{"type":"blank","stem":"细胞核内含有遗传物质，是细胞的____中心。","answer":["控制"],"explanation":"细胞膜控制物质进出；线粒体和叶绿体是细胞中的能量转换器。"},{"type":"blank","stem":"植物细胞比动物细胞多了细胞壁、____和液泡等结构。","answer":["叶绿体"],"explanation":"植物的根尖细胞没有叶绿体。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"实验探究","source":"依据人教版七年级上册“练习使用显微镜”编写","kind":"实验探究","material":"","stem":"使用显微镜观察时：①对光时应转动什么，使哪个物镜对准通光孔？②镜筒下降时眼睛应注视哪里？为什么？③视野中物像偏左上方，要移到中央应把玻片往哪个方向移动？（6分）","points":[{"text":"对光：转动转换器，使低倍物镜对准通光孔","score":2},{"text":"镜筒下降时眼睛注视物镜，以免物镜压碎玻片标本","score":2},{"text":"玻片向左上方移动（物像移动方向与玻片移动方向相反，“偏哪往哪移”）","score":2}],"score":6,"sample":"","explanation":"显微镜放大倍数 = 目镜倍数 × 物镜倍数；放大倍数越大，看到的细胞越大、数目越少、视野越暗。"},{"type":"essay","tag":"实验探究","source":"依据人教版七年级上册“绿色植物是生物圈中有机物的制造者”编写","kind":"实验探究","material":"","stem":"“绿叶在光下制造有机物”实验中：①为什么要先把天竺葵放到黑暗处一昼夜？②用黑纸片把叶片一部分上下两面遮盖起来的目的是什么？③为什么要把叶片放入酒精中隔水加热？④滴加碘液后，见光部分和遮光部分各呈什么颜色？说明什么？（8分）","points":[{"text":"暗处理：把叶片中原有的淀粉运走耗尽","score":2},{"text":"遮光：设置对照实验，变量是光","score":2},{"text":"酒精隔水加热：溶解叶片中的叶绿素（脱色），隔水加热防止酒精燃烧","score":2},{"text":"见光部分变蓝、遮光部分不变蓝；说明光是光合作用的条件，淀粉是光合作用的产物","score":2}],"score":8,"sample":"","explanation":"光合作用：二氧化碳 + 水 →（光能、叶绿体）→ 有机物（储存能量）+ 氧气。"}]}]},{"id":"xiaosimen-shengwu-2","group":"生物","subject":"生物","term":"七年级下册","title":"生物 · 七年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第17题","stem":"男性产生精子的器官是（ ）。","options":[{"key":"A","text":"睾丸"},{"key":"B","text":"附睾"},{"key":"C","text":"输精管"},{"key":"D","text":"阴茎"}],"answer":"A","explanation":"睾丸是男性主要的生殖器官，能产生精子并分泌雄性激素；附睾贮存和输送精子，输精管输送精子。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建省初中学业水平考试·生物第14题","stem":"跑步时人体各系统协调配合，起主要调节作用的是（ ）。","options":[{"key":"A","text":"消化系统"},{"key":"B","text":"神经系统"},{"key":"C","text":"呼吸系统"},{"key":"D","text":"泌尿系统"}],"answer":"B","explanation":"神经系统是机体内对生理功能活动起主导调节作用的系统，跑步时神经系统可以调节呼吸频率、心跳速度、肌肉收缩和舒张等，使人体成为一个统一的整体。"},{"type":"choice","tag":"Claude 精选","source":"2024届福建省厦门市逸夫中学中考适应性考试·生物第3题","stem":"甲血管与心室相连，流静脉血；乙血管与心房相连，流动脉血，这两条血管依次是（ ）。","options":[{"key":"A","text":"主动脉和肺动脉"},{"key":"B","text":"肺静脉和肺动脉"},{"key":"C","text":"上腔静脉和下腔静脉"},{"key":"D","text":"肺动脉和肺静脉"}],"answer":"D","explanation":"心室与动脉相连，心房与静脉相连；甲血管与心室相连、流静脉血，是肺动脉；乙血管与心房相连、流动脉血，是肺静脉。"},{"type":"choice","tag":"Claude 精选","source":"2024届福建省厦门市逸夫中学中考适应性考试·生物第14题","stem":"下列关于人的生殖的叙述，错误的是（ ）。","options":[{"key":"A","text":"男性的主要生殖器官是睾丸，它能产生精子和分泌雄性激素"},{"key":"B","text":"女性的主要生殖器官是卵巢，它能产生卵细胞和分泌雌性激素"},{"key":"C","text":"精子和卵细胞结合形成受精卵的场所是子宫"},{"key":"D","text":"胎儿生活在子宫内，通过胎盘和脐带从母体获得营养物质和氧气"}],"answer":"C","explanation":"精子与卵细胞在输卵管处相遇并结合形成受精卵，不是子宫；睾丸是男性的主要生殖器官，卵巢是女性的主要生殖器官，胎儿在子宫内通过胎盘、脐带从母体获得营养物质和氧气。"},{"type":"choice","tag":"Claude 精选","source":"2024届江苏省南京市建邺区金陵河西区七年级生物第二学期期末质量检测模拟试题第4题","stem":"血液中能止血和吞噬病菌的血细胞分别是（ ）。","options":[{"key":"A","text":"血小板和红细胞"},{"key":"B","text":"血小板和白细胞"},{"key":"C","text":"白细胞和红细胞"},{"key":"D","text":"白细胞和血小板"}],"answer":"B","explanation":"血小板有止血和加速血液凝固的作用；白细胞能吞噬病菌，起防御和保护作用；红细胞运输氧。"},{"type":"choice","tag":"Claude 精选","source":"2024届江苏省南京市建邺区金陵河西区七年级生物第二学期期末质量检测模拟试题第11题","stem":"狗在受伤后，会用舌头舔伤口，这样有利于伤口的愈合，其原因是唾液中含有（ ）。","options":[{"key":"A","text":"抗体"},{"key":"B","text":"消化酶"},{"key":"C","text":"溶菌酶"},{"key":"D","text":"生长素"}],"answer":"C","explanation":"唾液中含有溶菌酶等杀菌物质，能破坏许多病菌的细胞壁、使病菌溶解，属于第二道防线，有利于伤口愈合。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市初中学业水平模拟考试·生物第21题第(4)小题（模拟卷，非中考真题；原为非选择题填空，改为单选题，选项为改编时补写）","stem":"人体通过饮食摄入的水，主要在消化道的（ ）被吸收进入血液；人每天形成原尿约150L，而排出的尿液约1.5L，这是因为大量的水通过（ ）的重吸收作用回到血液。","options":[{"key":"A","text":"胃、肾小球"},{"key":"B","text":"小肠、肾小管"},{"key":"C","text":"大肠、肾小囊"},{"key":"D","text":"口腔、输尿管"}],"answer":"B","explanation":"小肠是消化和吸收的主要器官，人体通过饮食摄入的水主要在小肠被吸收进入血液；原尿流经肾小管时，大部分水、全部葡萄糖和部分无机盐被重新吸收回血液，所以原尿约150L而尿液仅约1.5L。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第8题第(1)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"5月12日是我国防灾减灾日。地震来临时，学校师生很快撤离到安全地带，这得益于日常的防震疏散演练。师生快速作出这一反应的结构基础是（ ）。","options":[{"key":"A","text":"大脑"},{"key":"B","text":"脊髓"},{"key":"C","text":"反射弧"},{"key":"D","text":"神经元"}],"answer":"C","explanation":"反射是指人体通过神经系统，对外界或内部的各种刺激所发生的有规律的反应，反射的结构基础是反射弧，包括感受器、传入神经、神经中枢、传出神经和效应器。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第8题","stem":"在青春期的变化中，属于心理变化的是（ ）。","options":[{"key":"A","text":"身高突增"},{"key":"B","text":"心脏收缩能力增强"},{"key":"C","text":"肺活量增加"},{"key":"D","text":"有较强的独立意识"}],"answer":"D","explanation":"身高突增、心脏收缩能力增强、肺活量增加都属于身体变化；有较强的独立意识属于心理变化。青春期在身体和心理上都会发生显著变化。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第12题","stem":"神舟二十号载人飞船发射的画面在我们眼球中成像的部位是（ ）。","options":[{"key":"A","text":"角膜"},{"key":"B","text":"晶状体"},{"key":"C","text":"巩膜"},{"key":"D","text":"视网膜"}],"answer":"D","explanation":"外界物体的光线经角膜、晶状体等折射后，在视网膜上形成清晰的物像；视网膜上有感光细胞，能感受光的刺激产生神经冲动，再经视神经传到大脑形成视觉。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省长沙市中考生物真题第7题","stem":"青春期是生长发育发生重要变化的时期。下列青少年行为习惯不健康的是（ ）。","options":[{"key":"A","text":"腰背挺直、坐姿端正"},{"key":"B","text":"规律进餐、足量饮水"},{"key":"C","text":"劳逸结合、睡眠充足"},{"key":"D","text":"躺卧看书、直视强光"}],"answer":"D","explanation":"躺卧看书、直视强光会危害眼睛健康，容易形成近视，是不健康的行为；腰背挺直、规律进餐、劳逸结合都是健康的生活方式。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省长沙市中考生物真题第12题","stem":"在冬奥会滑雪比赛中，运动员协调运动、维持身体平衡的结构是（ ）。","options":[{"key":"A","text":"大脑"},{"key":"B","text":"脑干"},{"key":"C","text":"小脑"},{"key":"D","text":"脊髓"}],"answer":"C","explanation":"小脑的主要功能是使运动协调、准确，维持身体的平衡；大脑是调节机体活动的最高级中枢，脑干有心血管中枢、呼吸中枢等重要的生命活动中枢，脊髓是调节躯体运动的低级中枢。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第23题（模拟卷）","stem":"下列有关生物体生理活动的叙述顺序判断正确的是（ ）。","options":[{"key":"A","text":"人体肺循环的路线是：右心室→肺动脉→肺部毛细血管网→肺静脉→左心房"},{"key":"B","text":"松树体内水分输送的方向是：叶→茎→根"},{"key":"C","text":"人的生殖发育顺序是：受精卵→胎儿→胚胎→新生儿"},{"key":"D","text":"某生态系统中能量流动的方向是：狼→野兔→草"}],"answer":"A","explanation":"肺循环的途径是右心室→肺动脉→肺部毛细血管→肺静脉→左心房；植物体内水分运输的方向是土壤中的水分→根→茎→叶；人的生殖发育顺序是受精卵→胚胎→胎儿→新生儿；生态系统中的能量沿食物链从生产者流向消费者，应该是草→野兔→狼。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第26题（模拟卷）","stem":"患心绞痛的病人，可服下列哪种药（ ）。","options":[{"key":"A","text":"硝酸甘油"},{"key":"B","text":"小柴胡颗粒"},{"key":"C","text":"牛黄解毒丸"},{"key":"D","text":"阿司匹林"}],"answer":"A","explanation":"心绞痛的药物治疗应增加冠状动脉血流量、减少心肌耗氧量，硝酸甘油是最广泛用于抗心绞痛的药物；小柴胡颗粒、牛黄解毒丸、阿司匹林不是治疗心绞痛的对症药物。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省南京师大附中中考冲刺卷·生物第22题（模拟卷）","stem":"每一天我们都要从食物中获取不同的营养物质，在这些营养物质中，不能为人体提供能量，但对维持正常生命活动却很重要的是（ ）。","options":[{"key":"A","text":"蛋白质、无机盐、水"},{"key":"B","text":"脂肪、维生素、糖类"},{"key":"C","text":"维生素、无机盐、水"},{"key":"D","text":"脂肪、蛋白质、糖类"}],"answer":"C","explanation":"食物所含的六类营养物质中，能为人体提供能量的是糖类、脂肪和蛋白质；水、无机盐和维生素不能为人体提供能量，但对维持正常生命活动却有重要的意义：维生素对人体的生命活动有重要的调节作用，水是人体各项生命活动进行的载体，无机盐是构成人体组织的重要材料。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-germination-variables","stem":"探究“水分对种子萌发的影响”，下列做法正确的是","options":[{"key":"A","text":"同时改变水分和温度"},{"key":"B","text":"每组只放 1 粒种子"},{"key":"C","text":"不需要设置对照组"},{"key":"D","text":"只改变水分，其他条件相同且适宜"}],"answer":"D","explanation":"控制单一变量才能判断差异由谁造成；每组用多粒种子可以减小偶然性。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-fruit-and-seed","stem":"我们吃的桃肉属于果皮，它是由花的哪一部分发育来的","options":[{"key":"A","text":"子房壁"},{"key":"B","text":"胚珠"},{"key":"C","text":"受精卵"},{"key":"D","text":"花药"}],"answer":"A","explanation":"子房发育成果实，子房壁发育成果皮，胚珠发育成种子，受精卵发育成胚。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-transpiration-transport","stem":"叶片制造的有机物运输到根部，主要通过","options":[{"key":"A","text":"根毛"},{"key":"B","text":"筛管"},{"key":"C","text":"导管"},{"key":"D","text":"气孔"}],"answer":"B","explanation":"导管运水和无机盐，筛管运有机物。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-digestion-absorption","stem":"蛋白质开始被消化的部位是","options":[{"key":"A","text":"小肠"},{"key":"B","text":"大肠"},{"key":"C","text":"胃"},{"key":"D","text":"口腔"}],"answer":"C","explanation":"淀粉在口腔开始消化，蛋白质在胃开始消化，脂肪主要在小肠消化。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-blood-circuits","stem":"肺循环的起点是","options":[{"key":"A","text":"左心室"},{"key":"B","text":"右心房"},{"key":"C","text":"左心房"},{"key":"D","text":"右心室"}],"answer":"D","explanation":"体循环从左心室出发，肺循环从右心室出发；肺动脉里流的是含氧较少的血。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"人体生命活动所需要的能量，主要是由____提供的。","answer":["糖类"],"explanation":"脂肪是备用能源物质；蛋白质是建造和修复身体的重要原料。"},{"type":"blank","stem":"缺乏维生素A易患夜盲症，缺乏维生素____易患坏血病；儿童缺钙易患____。","answer":["C","佝偻病"],"explanation":"缺维生素B₁易患脚气病，缺铁易患缺铁性贫血。"},{"type":"blank","stem":"人体最大的消化腺是____，它分泌的胆汁不含消化酶，能乳化脂肪。","answer":["肝脏"],"explanation":"胰腺分泌的胰液含有消化糖类、脂肪、蛋白质的酶。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据人教版七年级下册“消化和吸收”编写","kind":"简答题","material":"","stem":"为什么说小肠是消化和吸收的主要器官？请写出小肠与其功能相适应的结构特点。（6分）","points":[{"text":"小肠很长（5—6米），内表面有环形皱襞和小肠绒毛，大大增加了消化和吸收的面积","score":2},{"text":"小肠内有多种消化液（肠液、胰液、胆汁）","score":2},{"text":"小肠绒毛壁、毛细血管壁都很薄，只由一层上皮细胞构成，利于吸收","score":2}],"score":6,"sample":"","explanation":"淀粉在口腔开始消化，蛋白质在胃开始消化，脂肪在小肠开始消化（胆汁乳化脂肪）。"},{"type":"essay","tag":"简答题","source":"依据人教版七年级下册“发生在肺内的气体交换”编写","kind":"简答题","material":"","stem":"肺泡有哪些适于进行气体交换的结构特点？肺泡与血液进行气体交换后，血液成分发生了什么变化？（6分）","points":[{"text":"肺泡数目多，增加了气体交换面积","score":2},{"text":"肺泡外缠绕着丰富的毛细血管和弹性纤维；肺泡壁和毛细血管壁都只由一层上皮细胞构成","score":2},{"text":"血液由含氧少的静脉血变成含氧丰富的动脉血","score":2}],"score":6,"sample":"","explanation":"气体交换的原理是气体扩散作用（从浓度高处向浓度低处扩散）。"}]}]},{"id":"xiaosimen-shengwu-3","group":"生物","subject":"生物","term":"八年级上册","title":"生物 · 八年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第11题","stem":"酸奶不仅营养丰富，还容易被消化与吸收。小闽为奶奶制作酸奶，需要用到的是（ ）。","options":[{"key":"A","text":"酵母菌"},{"key":"B","text":"曲霉菌"},{"key":"C","text":"醋酸菌"},{"key":"D","text":"乳酸菌"}],"answer":"D","explanation":"制作酸奶利用乳酸菌的发酵作用，乳酸菌在无氧条件下将牛奶中的乳糖转化为乳酸；酵母菌用于酿酒、发面，醋酸菌用于制醋。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建省初中学业水平考试·生物第9题","stem":"濒危鸟类黑脸琵鹭具有的特征是（ ）。","options":[{"key":"A","text":"无脊椎骨"},{"key":"B","text":"用鳃呼吸"},{"key":"C","text":"体表有鳞片"},{"key":"D","text":"前肢变成翼"}],"answer":"D","explanation":"黑脸琵鹭属于鸟类，体内具有脊柱，属于脊椎动物，用肺呼吸、气囊辅助呼吸，被覆羽毛，前肢变成翼，翼是飞行器官。"},{"type":"choice","tag":"Claude 精选","source":"2024届福建省厦门市逸夫中学中考适应性考试·生物第2题","stem":"环境污染、过度采伐等会导致地球生物多样性锐减，保护生物多样性刻不容缓，下列说法不正确的是（ ）。","options":[{"key":"A","text":"生物多样性是指生物种类的多样性"},{"key":"B","text":"生物种类的多样性实质上是基因的多样性"},{"key":"C","text":"建立自然保护区是保护生物多样性最有效的措施"},{"key":"D","text":"生物的种类越丰富，生态系统越稳定"}],"answer":"A","explanation":"生物多样性通常有三个层次的含义：生物种类的多样性、基因（遗传）的多样性和生态系统的多样性，不只是生物种类的多样性；生物种类的多样性实质上是基因的多样性，建立自然保护区是保护生物多样性最有效的措施，生物种类越丰富、生态系统越稳定。"},{"type":"choice","tag":"Claude 精选","source":"2024年广东省初中学业水平考试·生物第9题","stem":"在丹霞山发现的国达铁角蕨有根、茎、叶的分化，叶背有孢子囊。在分类上，与它属于同一类群的是（ ）。","options":[{"key":"A","text":"满江红"},{"key":"B","text":"海带"},{"key":"C","text":"葫芦藓"},{"key":"D","text":"苏铁"}],"answer":"A","explanation":"国达铁角蕨有根、茎、叶的分化，叶背有孢子囊，属于蕨类植物；满江红也是蕨类植物。海带是藻类植物（无根、茎、叶的分化），葫芦藓是苔藓植物（无根），苏铁是裸子植物（能产生种子）。"},{"type":"choice","tag":"Claude 精选","source":"2024年广东省初中学业水平考试·生物第21题","stem":"小华对黄嘴白鹭的分析错误的是（ ）。","options":[{"key":"A","text":"卵生"},{"key":"B","text":"胸肌发达"},{"key":"C","text":"用肺呼吸"},{"key":"D","text":"体温不恒定"}],"answer":"D","explanation":"黄嘴白鹭是鸟类：卵生、胸肌发达、用肺呼吸、体温恒定。鸟类和哺乳类都是恒温动物，体温不会随环境温度变化。"},{"type":"choice","tag":"Claude 精选","source":"2024届江苏省南京市建邺区金陵河西区七年级生物第二学期期末质量检测模拟试题第29题","stem":"下列有关动物行为的叙述正确的是（ ）。","options":[{"key":"A","text":"马随着音乐的节奏踏起优美的舞步是先天性行为"},{"key":"B","text":"学习行为由生活经验和学习获得，与遗传因素无关"},{"key":"C","text":"蚯蚓走迷宫实验说明低等的动物也具有学习行为"},{"key":"D","text":"具有社会行为的动物群体中，往往是年长者为“首领”"}],"answer":"C","explanation":"马随音乐踏舞步是出生后通过学习建立的行为，属于学习行为；学习行为是在遗传因素的基础上、通过生活经验和学习获得的，与遗传因素有关；蚯蚓走迷宫说明低等动物也有学习行为；社会行为群体中，首领一般是攻击行为中的优胜者，不是年长者。"},{"type":"choice","tag":"Claude 精选","source":"2024年江苏省苏州市初中学业水平考试·生物第24题","stem":"链霉素是从链霉菌（属于放线菌）中提取的一种抗生素，对肺炎链球菌具有明显的抑制作用。相关叙述正确的是（ ）。","options":[{"key":"A","text":"链霉菌呈放射状分枝的菌丝内具有横隔"},{"key":"B","text":"肺炎链球菌能直接将无机物合成有机物"},{"key":"C","text":"链霉菌和肺炎链球菌的细胞都具有拟核"},{"key":"D","text":"链霉素对所有细菌均有明显的抑制作用"}],"answer":"C","explanation":"链霉菌和肺炎链球菌都是原核生物，细胞内都没有成形的细胞核，都有拟核；放线菌的基内菌丝一般无横隔；肺炎链球菌是异养生物，不能将无机物合成有机物；链霉素只对部分细菌有抑制作用，不是所有细菌。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市初中学业水平模拟考试·生物第18题","stem":"小李假期去博物馆参观。以下是他在参观时看到的一些青铜器，其中所涉及的生物原型属于哺乳类的是（ ）。","options":[{"key":"A","text":"猪尊"},{"key":"B","text":"鸮卣（猫头鹰）"},{"key":"C","text":"鸟尊"},{"key":"D","text":"蛇首扁柄斗"}],"answer":"A","explanation":"猪是哺乳动物，特征是胎生、哺乳、体表被毛；猫头鹰和鸟属于鸟类，蛇属于爬行类。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第9题第(3)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"为增加枇杷产量，枇杷树培育过程中需定期施有机肥，施肥后一般都要松土，原因是：一方面可促进土壤微生物将有机肥中的有机物分解为（ ）；另一方面还可促进根呼吸作用，从而有利于根对营养物质的吸收。","options":[{"key":"A","text":"无机盐、水和二氧化碳等无机物"},{"key":"B","text":"有机物"},{"key":"C","text":"氧气"},{"key":"D","text":"淀粉"}],"answer":"A","explanation":"土壤中的微生物可以将有机肥中的有机物分解为无机盐、水和二氧化碳等无机物，供植物吸收利用；松土增加土壤中的氧气含量，促进根的呼吸作用，有利于根对营养物质的吸收。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建省初中学业水平考试·生物第33题第(2)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"斜纹夜蛾体表有防止水分散失的（ ）。","options":[{"key":"A","text":"角质层"},{"key":"B","text":"外骨骼"},{"key":"C","text":"皮肤"},{"key":"D","text":"羽毛"}],"answer":"B","explanation":"斜纹夜蛾属于节肢动物，体表有外骨骼，能防止体内水分蒸发、保护内部结构；外骨骼不能随身体生长而生长，生长过程中有蜕皮现象。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第17题","stem":"在光学显微镜下观察青霉的装片，可观察到的是（ ）。","options":[{"key":"A","text":"菌丝"},{"key":"B","text":"芽孢"},{"key":"C","text":"叶绿体"},{"key":"D","text":"DNA"}],"answer":"A","explanation":"青霉属于真菌，由菌丝构成，在光学显微镜下可以观察到菌丝；芽孢是细菌的休眠体，青霉没有叶绿体，DNA在光学显微镜下看不到。"},{"type":"choice","tag":"Claude 精选","source":"2025届湖南省长沙市长郡教育集团中考生物最后冲刺模拟试卷第20题（模拟卷）","stem":"关于下列动物的形态结构与其生活环境、生活习性相适应的叙述，错误的是（ ）。","options":[{"key":"A","text":"蝗虫的体表有外骨骼，适于陆地生活"},{"key":"B","text":"家兔有发达的盲肠，有助于消化植物纤维"},{"key":"C","text":"家鸽体内有发达的气囊，适于进行气体交换"},{"key":"D","text":"河蚌的外套膜能分泌形成贝壳，起保护作用"}],"answer":"C","explanation":"家鸽体内有发达的气囊，气囊能暂时储存气体、辅助呼吸，但进行气体交换的场所是肺，气囊不能进行气体交换；蝗虫的外骨骼能防止体内水分蒸发，家兔发达的盲肠有助于消化植物纤维，河蚌的外套膜能分泌形成贝壳。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第2题（模拟卷）","stem":"两栖动物是由水生向陆生过渡的类型，它不是真正陆地动物的原因是（ ）。","options":[{"key":"A","text":"四肢不够发达"},{"key":"B","text":"体表没有覆盖鳞片"},{"key":"C","text":"受精作用和幼体发育离不开水"},{"key":"D","text":"仍然用鳃呼吸"}],"answer":"C","explanation":"两栖动物的生殖和发育都离不开水：水中产卵、水中受精，幼体生活在水中、用鳃呼吸，成体既能生活在水中也能生活在潮湿的陆地上，用肺呼吸、皮肤辅助呼吸；所以两栖动物不是真正适应陆地生活的动物。成体用肺呼吸，不是始终用鳃呼吸。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第30题（模拟卷）","stem":"节肢动物和环节动物的共同特征是（ ）。","options":[{"key":"A","text":"具有外骨骼"},{"key":"B","text":"身体分节"},{"key":"C","text":"具有贝壳"},{"key":"D","text":"足分节"}],"answer":"B","explanation":"节肢动物的身体由许多体节构成，并且分部，体表有外骨骼，足和触角分节；环节动物的身体也由许多体节构成，用刚毛辅助运动；二者的共同特征是身体分节。环节动物体外没有外骨骼，足也不分节，二者都没有贝壳。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省南京师大附中中考冲刺卷·生物第7题（模拟卷）","stem":"某生物学习小组利用甲、乙、丙三种动物探究动物的绕道取食行为。动物甲、乙、丙完成绕道取食前的尝试次数分别是165次、32次、5次。三种动物的学习能力从低到高的顺序是（ ）。","options":[{"key":"A","text":"甲、乙、丙"},{"key":"B","text":"乙、甲、丙"},{"key":"C","text":"丙、乙、甲"},{"key":"D","text":"甲、丙、乙"}],"answer":"A","explanation":"“尝试”与“错误”是常见的学习行为；动物越高等，学习能力越强，经过的“尝试”与“错误”的次数就越少。甲尝试 165 次最多、学习能力最低，丙尝试 5 次最少、学习能力最高，所以学习能力从低到高的顺序是甲、乙、丙。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-reflex-arc","stem":"在反射弧中，执行反应的结构是","options":[{"key":"A","text":"效应器"},{"key":"B","text":"感受器"},{"key":"C","text":"神经中枢"},{"key":"D","text":"传入神经"}],"answer":"A","explanation":"反射弧依次是感受器、传入神经、神经中枢、传出神经、效应器；效应器执行反应。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-bones-and-muscles","stem":"屈肘时，肱二头肌和肱三头肌的状态是","options":[{"key":"A","text":"两者同时舒张"},{"key":"B","text":"肱二头肌收缩，肱三头肌舒张"},{"key":"C","text":"肱二头肌舒张，肱三头肌收缩"},{"key":"D","text":"两者同时收缩"}],"answer":"B","explanation":"肌肉只能牵拉骨；屈肘和伸肘时两块肌肉的收缩、舒张状态相反。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-hormone-regulation","stem":"能调节血糖浓度的激素是","options":[{"key":"A","text":"生长激素"},{"key":"B","text":"唾液淀粉酶"},{"key":"C","text":"胰岛素"},{"key":"D","text":"甲状腺激素"}],"answer":"C","explanation":"胰岛素调节血糖；唾液淀粉酶是消化酶，不是激素。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-immune-specificity","stem":"皮肤和黏膜阻挡病原体进入人体，属于","options":[{"key":"A","text":"特异性免疫"},{"key":"B","text":"计划免疫"},{"key":"C","text":"接种疫苗获得的免疫"},{"key":"D","text":"非特异性免疫"}],"answer":"D","explanation":"皮肤、黏膜能阻挡多类外来物质，属于非特异性免疫；疫苗帮助形成针对特定抗原的特异性免疫。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-food-web","stem":"下列食物链书写正确的是","options":[{"key":"A","text":"草→兔→狐"},{"key":"B","text":"阳光→草→兔→狐"},{"key":"C","text":"兔→草→狐"},{"key":"D","text":"草→兔→狐→细菌"}],"answer":"A","explanation":"捕食食物链从生产者写起，箭头指向取食者，不写阳光和分解者。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"腔肠动物身体呈辐射对称，有口无肛门；扁形动物身体呈____对称。","answer":["两侧"],"explanation":"腔肠动物如水螅、海葵；扁形动物如涡虫、血吸虫。"},{"type":"blank","stem":"鱼用____呼吸，通过尾部和躯干部的摆动以及鳍的协调作用游泳。","answer":["鳃"],"explanation":"鲸、海豚是哺乳动物，用肺呼吸。"},{"type":"blank","stem":"哺乳动物的主要特征是：体表被毛，胎生、____。","answer":["哺乳"],"explanation":"哺乳动物牙齿有门齿、犬齿、臼齿的分化，体温恒定。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据人教版八年级上册“鸟”编写","kind":"简答题","material":"","stem":"鸟类有哪些适于飞行的形态结构特点？（6分）","points":[{"text":"身体呈流线型，可减少飞行时空气的阻力；前肢变成翼","score":2},{"text":"骨骼轻、薄、坚固，有些骨内部中空；胸肌发达，附着在胸骨上","score":2},{"text":"有气囊辅助肺呼吸（双重呼吸）；食量大、消化快，直肠很短不储存粪便","score":2}],"score":6,"sample":"","explanation":"鸟类体温恒定，卵生，体表覆羽。"},{"type":"essay","tag":"简答题","source":"依据人教版八年级上册“细菌和真菌”编写","kind":"简答题","material":"","stem":"比较细菌和真菌的结构与生殖方式，并各举一例说明它们在生活中的利用。（7分）","points":[{"text":"细菌：单细胞，没有成形的细胞核（原核生物）","score":2},{"text":"真菌：有真正的细胞核（真核生物），有单细胞（酵母菌）也有多细胞（霉菌、蘑菇）","score":2},{"text":"细菌靠分裂生殖；真菌主要靠孢子生殖（酵母菌还可出芽生殖）","score":2},{"text":"利用：乳酸菌制酸奶、泡菜；酵母菌做馒头面包、酿酒；青霉菌提取青霉素","score":1}],"score":7,"sample":"","explanation":"细菌和真菌一般没有叶绿体，营养方式为异养；腐生的细菌真菌作为分解者参与物质循环。"}]}]},{"id":"xiaosimen-shengwu-4","group":"生物","subject":"生物","term":"八年级下册","title":"生物 · 八年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":3,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2025届江苏省南京师大附中中考冲刺卷·生物第13题（模拟卷）","stem":"下列属于相对性状的一组的是（ ）。","options":[{"key":"A","text":"球形西瓜和磨盘形南瓜"},{"key":"B","text":"豌豆的红花和白花"},{"key":"C","text":"玉米的圆粒和黄粒"},{"key":"D","text":"兔的白毛与鼠的黑毛"}],"answer":"B","explanation":"相对性状是指同种生物同一性状的不同表现形式；豌豆的红花和白花是同一性状（花色）的不同表现形式，是相对性状。球形西瓜和磨盘形南瓜、兔的白毛与鼠的黑毛都不是同种生物；玉米的圆粒和黄粒是同一个生物的两种性状（粒形和粒色），不是相对性状。"},{"type":"choice","tag":"Claude 精选","source":"2024届福建省厦门市逸夫中学中考适应性考试·生物第8题","stem":"下列关于有性生殖和无性生殖的描述，错误的是（ ）。","options":[{"key":"A","text":"有性生殖必须经过两性生殖细胞的结合"},{"key":"B","text":"由种子萌发成新个体的生殖方式属于有性生殖"},{"key":"C","text":"人属于高等动物一定不能进行无性生殖"},{"key":"D","text":"利用植物的根、茎、叶等器官繁殖新个体的方式属于无性生殖"}],"answer":"C","explanation":"有性生殖必须经过两性生殖细胞结合形成受精卵，种子由受精卵发育而来、属于有性生殖；人可以进行有性生殖，也可以用克隆技术进行无性生殖，只是由于伦理关系一般不能进行人类克隆；利用植物营养器官繁殖属于无性生殖。"},{"type":"choice","tag":"Claude 精选","source":"2025年福建省初中学业水平考试·生物第20题","stem":"下列做法不利于青少年健康成长的是（ ）。","options":[{"key":"A","text":"经常暴饮暴食"},{"key":"B","text":"主动与父母沟通"},{"key":"C","text":"做好卫生保健"},{"key":"D","text":"多参加体育锻炼"}],"answer":"A","explanation":"经常暴饮暴食会对青少年的肠胃造成很大的负担，容易引起消化不良、肠胃疾病等问题，不利于青少年健康成长；主动与父母沟通、做好卫生保健、多参加体育锻炼都有利于青少年的身心健康。"},{"type":"choice","tag":"Claude 精选","source":"2024年广东省初中学业水平考试·生物第12题","stem":"特异性免疫是免疫疗法的基础，下列结构或物质参与特异性免疫的是（ ）。","options":[{"key":"A","text":"皮肤"},{"key":"B","text":"黏膜"},{"key":"C","text":"溶菌酶"},{"key":"D","text":"抗体"}],"answer":"D","explanation":"特异性免疫是第三道防线，产生抗体、消灭抗原，只针对特定的病原体起作用。皮肤和黏膜是第一道防线，溶菌酶是第二道防线，都属于非特异性免疫。"},{"type":"choice","tag":"Claude 精选","source":"2025年四川省成都市初中学业水平模拟考试·生物第14题","stem":"下列哪一组生物性状不属于相对性状？（ ）。","options":[{"key":"A","text":"人的有酒窝和无酒窝"},{"key":"B","text":"玉米的高杆和矮杆"},{"key":"C","text":"家猪的长尾和短尾"},{"key":"D","text":"小猫的卷毛和灰毛"}],"answer":"D","explanation":"相对性状是同种生物同一性状的不同表现形式；卷毛是毛发形态、灰毛是毛发颜色，是两种不同的性状，不属于相对性状；其余三组都是同一性状的不同表现形式。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省成都市初中学业水平模拟考试·生物第22题第(1)小题（模拟卷，非中考真题；原为非选择题填空，改为单选题，选项为改编时补写）","stem":"人的新生命起点受精卵在（ ）形成，怀孕后胎儿在（ ）内发育至成熟。","options":[{"key":"A","text":"卵巢、输卵管"},{"key":"B","text":"输卵管、子宫"},{"key":"C","text":"子宫、输卵管"},{"key":"D","text":"卵巢、子宫"}],"answer":"B","explanation":"精子与卵细胞在输卵管中结合形成受精卵，标志着新生命的起点；子宫是女性产生月经和孕育胎儿的器官，胎儿在子宫内发育至成熟；卵巢产生卵细胞、分泌雌性激素。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建省初中学业水平考试·生物第31题第(4)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"1978年，科学家将人胰岛素基因转移到大肠杆菌中，经发酵生产胰岛素。⑤中应用的生物技术有（ ）和发酵技术。","options":[{"key":"A","text":"克隆技术"},{"key":"B","text":"杂交育种"},{"key":"C","text":"组织培养"},{"key":"D","text":"转基因技术"}],"answer":"D","explanation":"把一种生物的基因转入另一种生物体内，培育出的生物称为转基因生物，所用技术是转基因技术；转基因技术可以定向改变生物的性状。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第21题","stem":"在某个经常刮大风的海岛上，无翅和残翅的昆虫特别多。下列叙述不正确的是（ ）。","options":[{"key":"A","text":"无翅和残翅的昆虫在繁殖过程中会发生变异"},{"key":"B","text":"无翅和残翅的昆虫不容易被吹到大海而淹死"},{"key":"C","text":"无翅和残翅的昆虫生存、繁殖后代的机会更多"},{"key":"D","text":"无翅和残翅的昆虫特别多，不是自然选择的结果"}],"answer":"D","explanation":"海岛上经常刮大风，有翅昆虫容易被吹到海里淹死，无翅和残翅的昆虫容易存活下来并繁殖后代，这是自然选择的结果；变异是不定向的，自然选择是定向的。"},{"type":"choice","tag":"Claude 精选","source":"2025年湖南省初中学业水平考试·生物第24题","stem":"培育一株开出多个品种花的树状月季，运用的技术是（ ）。","options":[{"key":"A","text":"嫁接"},{"key":"B","text":"杂交技术"},{"key":"C","text":"扦插"},{"key":"D","text":"组织培养"}],"answer":"A","explanation":"嫁接能把不同品种月季的枝或芽接到同一株月季上，使一株开出多个品种的花，并保持接穗的优良性状；杂交技术会产生新性状，不能保证开出指定的多个品种，扦插和组织培养只能繁殖同一品种。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年湖南省初中学业水平考试·生物第31题第(1)小题（原为非选择题填空，改为单选题，选项为改编时补写，知识点和答案未改）","stem":"在豌豆杂交实验中，在植株A的花粉未成熟时剪除雄蕊并用小袋包住花朵，去除雄蕊的目的是避免（ ）。","options":[{"key":"A","text":"自花传粉"},{"key":"B","text":"异花传粉"},{"key":"C","text":"风力传粉"},{"key":"D","text":"昆虫传粉"}],"answer":"A","explanation":"豌豆是自花传粉植物，在花粉未成熟时去除雄蕊并套袋，可以避免自花传粉，再蘸取另一植株的成熟花粉涂在柱头上进行人工异花传粉。"},{"type":"choice","tag":"Claude 精选","source":"2025届湖南省长沙市长郡教育集团中考生物最后冲刺模拟试卷第10题（模拟卷）","stem":"下列有关人类染色体与遗传病的叙述，正确的是（ ）。","options":[{"key":"A","text":"男性精子的染色体组成一定是22条常染色体+Y"},{"key":"B","text":"正常人体细胞的染色体一条来自父方，一条来自母方"},{"key":"C","text":"近亲结婚能引起后代染色体数目变异，增加了患遗传病的机会"},{"key":"D","text":"白化病不是遗传病"}],"answer":"B","explanation":"正常人体细胞中的染色体是成对存在的，一条来自父方，一条来自母方；男性精子的染色体组成是 22 条常染色体+X 或 22 条常染色体+Y，不一定是含 Y 的那一种；近亲结婚增加的是后代患隐性遗传病的机会，不是引起染色体数目变异；白化病是隐性遗传病。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第20题（模拟卷）","stem":"2014年1月份，浙江等地率先发现H7N9型禽流感，其病原体是全球首次发现的新亚型流感病毒。有关下列说法，正确的是（ ）。","options":[{"key":"A","text":"H7N9型禽流感的病原体有细胞结构，能独立生活"},{"key":"B","text":"研制注射H7N9型禽流感疫苗是预防该病流行的有效措施"},{"key":"C","text":"发现H7N9型禽流感患者及时隔离治疗属于切断传播途径"},{"key":"D","text":"H7N9型禽流感病毒侵入人体能刺激淋巴细胞产生抗体参与，属于非特异性免疫"}],"answer":"B","explanation":"病毒没有细胞结构，主要由内部的核酸和外部的蛋白质外壳组成，不能独立生活，只能寄生在活细胞里；研制注射 H7N9 禽流感疫苗是预防该病流行的最有效措施，有利于保护易感人群。发现患者及时隔离治疗属于控制传染源；病毒刺激淋巴细胞产生抗体，只对该病毒有效，属于特异性免疫。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第36题第(2)小题（模拟卷，原为非选择题填空，改为单选题，选项为改编时补写，知识点和答案未改）","stem":"水痘是一种呼吸道传染病，由带状疱疹病毒感染引起，通过空气和飞沫传播。某校发现6名同学感染了水痘，为防止疫情扩散，学校让该6名同学离校诊治，待痊愈后再返校。这种做法在传染病的预防措施中属于（ ）。","options":[{"key":"A","text":"控制传染源"},{"key":"B","text":"切断传播途径"},{"key":"C","text":"保护易感人群"},{"key":"D","text":"以上都不是"}],"answer":"A","explanation":"传染病的预防措施有控制传染源、切断传播途径、保护易感人群；传染源是指能够散播病原体的人或动物，让患水痘的同学离校诊治属于控制传染源。教室、宿舍喷洒消毒液属于切断传播途径，未出过水痘且未接种疫苗的同学及时接种属于保护易感人群。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025届江苏省苏州市张家港市达标名校中考考前最后一卷·生物第38题（模拟卷，原为非选择题填空，改为单选题，选项为改编时补写，知识点和答案未改；原题“白眼雌性果蝇”与“白眼雄性果蝇”笔误，已统一为雄性）","stem":"摩尔根发现的这只白眼雄性果蝇，体细胞中有4对染色体，其性别决定方式与人类相同。这只白眼雄性果蝇体细胞的染色体组成是（ ）。","options":[{"key":"A","text":"3对+XX"},{"key":"B","text":"3对+XY"},{"key":"C","text":"4对+XX"},{"key":"D","text":"4对+XY"}],"answer":"B","explanation":"果蝇体细胞中有 4 对染色体，其中 3 对是常染色体，1 对是性染色体；果蝇的性别决定方式与人类相同，雄性的性染色体是 XY，雌性是 XX，所以白眼雄性果蝇体细胞的染色体组成是 3 对+XY。"},{"type":"choice","tag":"Claude 精选","source":"2025届江苏省南京师大附中中考冲刺卷·生物第25题（模拟卷）","stem":"下列关于生物生殖发育的描述中正确的是（ ）。","options":[{"key":"A","text":"胎儿通过胎盘从母体获得营养物质"},{"key":"B","text":"所有鸡卵都能孵化成小鸡"},{"key":"C","text":"蚊子和蝗虫都进行不完全变态发育"},{"key":"D","text":"雌蛙鸣叫是青蛙的繁殖行为"}],"answer":"A","explanation":"胎儿通过胎盘从母体中获得营养物质和氧；只有受精的鸡卵才可能孵化出小鸡；蚊的发育经过受精卵—幼虫—蛹—成虫四个阶段，属于完全变态发育，蝗虫的发育经过受精卵—幼虫—成虫三个阶段，属于不完全变态发育；雄蛙鸣叫属于青蛙的繁殖行为，雌蛙不会鸣叫。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-sexual-asexual","stem":"下列繁殖方式属于无性生殖的是","options":[{"key":"A","text":"受精的鸡蛋孵出小鸡"},{"key":"B","text":"柳枝扦插长成新植株"},{"key":"C","text":"用种子繁殖小麦"},{"key":"D","text":"青蛙的受精卵发育成蝌蚪"}],"answer":"B","explanation":"无性生殖不经过两性生殖细胞结合；扦插、嫁接是常见例子。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-gene-dna-chromosome","stem":"基因是","options":[{"key":"A","text":"蛋白质分子"},{"key":"B","text":"细胞核"},{"key":"C","text":"有遗传效应的 DNA 片段"},{"key":"D","text":"染色体的全部"}],"answer":"C","explanation":"染色体主要由 DNA 和蛋白质组成，基因是有遗传效应的 DNA 片段，一条染色体上有多个基因。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-dominance-evidence","stem":"一对双眼皮的父母生了一个单眼皮的孩子（按一对基因完全显性分析），可以判断","options":[{"key":"A","text":"双眼皮是隐性性状"},{"key":"B","text":"孩子的单眼皮不能遗传"},{"key":"C","text":"父母的基因组成都是纯合的"},{"key":"D","text":"单眼皮是隐性性状"}],"answer":"D","explanation":"表现相同的双亲生出另一种表现的后代，另一种表现就是隐性性状；父母都携带隐性基因。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-natural-selection","stem":"关于自然选择，下列说法正确的是","options":[{"key":"A","text":"种群中先有可遗传的变异，环境选择保留有利变异"},{"key":"B","text":"生物为了适应环境会主动产生需要的变异"},{"key":"C","text":"生物产生的变异都是有利的"},{"key":"D","text":"人工选择就是自然选择"}],"answer":"A","explanation":"先有可遗传变异，再有选择；生物不会因为“想适应”就产生恰好需要的变异。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-biodiversity-protection","stem":"建立自然保护区保护大熊猫及其栖息环境，属于","options":[{"key":"A","text":"人工选择"},{"key":"B","text":"就地保护"},{"key":"C","text":"迁地保护"},{"key":"D","text":"建立种质库"}],"answer":"B","explanation":"让生物留在原有栖息地、保护当地生态系统，属于就地保护；动物园等属于迁地保护。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"扦插、嫁接属于____生殖；嫁接成活的关键是接穗和砧木的____紧密结合。","answer":["无性","形成层"],"explanation":"有性生殖要经过两性生殖细胞结合成受精卵。"},{"type":"blank","stem":"家蚕的发育经过卵、幼虫、蛹、成虫四个时期，属于____变态发育；蝗虫的发育属于____变态发育。","answer":["完全","不完全"],"explanation":"青蛙的发育为变态发育，蝌蚪用鳃呼吸，成蛙用肺呼吸、皮肤辅助呼吸。"},{"type":"blank","stem":"鸟卵中将来发育成雏鸟的结构是____。","answer":["胚盘"],"explanation":"卵黄为胚胎发育提供主要营养，卵白提供营养和水分。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"综合题","source":"依据人教版八年级下册“人的性别遗传”编写","kind":"综合题","material":"","stem":"人的性别是由什么决定的？为什么说生男生女的机会是均等的？（6分）","points":[{"text":"人的性别由性染色体决定：男性为XY，女性为XX","score":2},{"text":"男性产生含X和含Y的两种精子，且数量相等；女性只产生含X的一种卵细胞","score":2},{"text":"受精时两种精子与卵细胞结合的机会均等，所以生男生女机会均等（各占50%）","score":2}],"score":6,"sample":"","explanation":"人的体细胞中有23对染色体，其中22对常染色体、1对性染色体。"},{"type":"essay","tag":"综合题","source":"依据人教版八年级下册“基因的显性和隐性”编写","kind":"综合题","material":"","stem":"一对有耳垂（显性，基因A）的夫妇生了一个无耳垂的孩子。①这对夫妇的基因组成分别是什么？②孩子的基因组成是什么？③这对夫妇再生一个孩子，有耳垂的概率是多少？（6分）","points":[{"text":"夫妇的基因组成都是Aa","score":2},{"text":"无耳垂孩子的基因组成是aa","score":2},{"text":"再生一个孩子有耳垂的概率是3/4（75%）","score":2}],"score":6,"sample":"","explanation":"Aa × Aa → AA：Aa：aa = 1：2：1，有耳垂（AA、Aa）占3/4。"}]}]},{"id":"xiaosimen-shengwu-5","group":"生物","subject":"生物","term":"九年级上册","title":"生物 · 九年级上册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"2024届福建省厦门市逸夫中学中考适应性考试·生物第16题","stem":"经体循环后，血液成分发生的变化是（ ）。","options":[{"key":"A","text":"氧气增多，二氧化碳减少"},{"key":"B","text":"氧气减少，二氧化碳增多"},{"key":"C","text":"氧气和二氧化碳都增多"},{"key":"D","text":"氧气和二氧化碳都减少"}],"answer":"B","explanation":"在体循环中，从左心室射出的动脉血流经组织细胞周围的毛细血管时，与组织细胞进行物质交换，将氧气和营养物质供给细胞利用，将细胞产生的二氧化碳等废物带走，血液由动脉血变成了静脉血，氧气减少、二氧化碳增多。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第4题","stem":"下列关于植物细胞形态的叙述，正确的是（ ）。","options":[{"key":"A","text":"近似长方体"},{"key":"B","text":"近似长方形"},{"key":"C","text":"扁形"},{"key":"D","text":"不同的植物以及不同结构的细胞形态各不相同"}],"answer":"D","explanation":"植物细胞的形态多种多样：保卫细胞呈半月形，导管细胞呈管状，表皮细胞、叶肉细胞形态也各不相同，不能一概说成近似长方体或扁形。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第10题","stem":"切洋葱时常会引起流泪，原因是洋葱组织细胞中含有对眼睛有刺激的物质，这些物质主要存在于细胞的（ ）。","options":[{"key":"A","text":"液泡"},{"key":"B","text":"细胞壁"},{"key":"C","text":"细胞膜"},{"key":"D","text":"细胞核"}],"answer":"A","explanation":"液泡内的细胞液中溶解着多种物质，洋葱细胞中对眼睛有刺激的物质就存在于液泡内的细胞液中。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第17题","stem":"关节在运动中所起的作用是（ ）。","options":[{"key":"A","text":"动力"},{"key":"B","text":"支点"},{"key":"C","text":"控制"},{"key":"D","text":"杠杆"}],"answer":"B","explanation":"运动系统中，骨起杠杆作用，关节起支点作用，骨骼肌收缩起动力作用，三者协调完成运动。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第2题（原卷D项“套袋处埋”按文意订正为“套袋处理”）","stem":"下列关于花和果实的叙述不正确的是（ ）。","options":[{"key":"A","text":"一个西瓜含有多粒种子，说明一个子房中有多个胚珠"},{"key":"B","text":"玉米的种皮和果皮紧密结合在一起，一粒玉米就是一个果实"},{"key":"C","text":"通过对玉米实施人工辅助授粉，可以解决玉米果穗顶部缺粒现象"},{"key":"D","text":"将未成熟的花进行套袋处理，透气的袋内能结出果实说明花是雌花"}],"answer":"D","explanation":"未成熟的花套袋后隔绝了外来花粉，无论雌花还是雄花，透气的袋内都不可能结出果实；结出果实需要传粉受精。A、B、C三项都正确。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第11题","stem":"下列关于呼吸系统的叙述中，正确的是（ ）。","options":[{"key":"A","text":"口是呼吸道的起点"},{"key":"B","text":"呼吸道可以过滤全部有害物质"},{"key":"C","text":"气管壁有O形软骨支撑"},{"key":"D","text":"肺泡外缠绕着毛细血管，有利于气体交换"}],"answer":"D","explanation":"呼吸道以鼻为起点，只能对吸入气体起温暖、湿润、清洁作用，不能过滤全部有害物质；气管壁是C形软骨支撑。肺泡外面包绕丰富的毛细血管，肺泡壁和毛细血管壁都只有一层上皮细胞，利于气体交换。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第17题","stem":"下列关于人体血管的叙述中，不正确的是（ ）。","options":[{"key":"A","text":"动脉的管壁薄，弹性小"},{"key":"B","text":"静脉将血液送回心脏"},{"key":"C","text":"毛细血管只允许红细胞单行通过"},{"key":"D","text":"动脉的血流速度最快"}],"answer":"A","explanation":"动脉管壁厚、弹性大、血流速度最快；静脉把血液从全身各处送回心脏，管壁较薄、弹性小；毛细血管管腔极细，只允许红细胞单行通过。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第31题","stem":"下列关于一株番茄和一头牛的叙述中，错误的是（ ）。","options":[{"key":"A","text":"细胞是它们的结构和功能的基本单位"},{"key":"B","text":"它们都是由受精卵发育而来"},{"key":"C","text":"番茄的果实和牛的心脏都属于器官"},{"key":"D","text":"它们的结构层次都是细胞→组织→器官→系统"}],"answer":"D","explanation":"番茄是植物，结构层次是细胞→组织→器官→植物体，没有系统这一层次；牛是动物，结构层次是细胞→组织→器官→系统→动物体。A、B、C三项都正确。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025年福建中考·生物第5题（原题含撕取、盖片、显微镜与视野图，题干补写各图内容与①为细准焦螺旋，知识点、选项与答案未改）","stem":"小福制作了洋葱鳞片叶内表皮细胞临时装片并进行观察：甲为撕取内表皮，乙为盖盖玻片，丙为显微镜（①为细准焦螺旋），丁为观察到的洋葱内表皮细胞视野。下列叙述正确的是（ ）。","options":[{"key":"A","text":"甲操作中撕取的内表皮越厚越好"},{"key":"B","text":"乙中的盖玻片应直接水平放下"},{"key":"C","text":"调节丙中的①可使物像更加清晰"},{"key":"D","text":"丁是酒精染色后观察到的视野"}],"answer":"C","explanation":"①是细准焦螺旋，调节它可以使物像更加清晰。撕取的内表皮要薄而透明，越厚越不利于观察；盖盖玻片时要让一侧先接触水滴、再缓缓放下，避免产生气泡；观察洋葱内表皮细胞用碘液染色，不是酒精染色。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第6题","stem":"福建省生物资源丰富，近年均有新物种被发现，如青鸾粉褶菌（大型真菌）、裂禾蕨（蕨类植物）等。下列关于裂禾蕨的叙述，正确的是（ ）。","options":[{"key":"A","text":"无输导组织"},{"key":"B","text":"无真正的根"},{"key":"C","text":"能开花结果"},{"key":"D","text":"用孢子繁殖"}],"answer":"D","explanation":"蕨类植物用孢子繁殖，不开花、不结果。蕨类有真正的根、茎、叶和输导组织。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第10题","stem":"关注健康，定期体检。从均衡膳食的角度，以下食谱中最适合奶奶的是（ ）。","options":[{"key":"A","text":"炖猪蹄、红烧肉、白糖糕"},{"key":"B","text":"清蒸鱼、炒白菜、杂粮饭"},{"key":"C","text":"腌萝卜、烧茄子、酱黄瓜"},{"key":"D","text":"烤鸡腿、炸鸡翅、炸油饼"}],"answer":"B","explanation":"B有鱼（优质蛋白质）、白菜（维生素）、杂粮饭（糖类和膳食纤维），荤素搭配、清淡少油，最适合老年人。A油脂和糖分过多，C多是腌制食品、营养单一且盐分高，D多是油炸食品。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第23题","stem":"人体的有些功能是通过增大表面积实现的。下列叙述与之不符的是（ ）。","options":[{"key":"A","text":"肾小管细长而且弯曲"},{"key":"B","text":"肺内有众多的肺泡"},{"key":"C","text":"消化道有多种消化液"},{"key":"D","text":"鼻腔毛细血管密集"}],"answer":"C","explanation":"肾小管细长弯曲增大了重吸收面积，肺内众多肺泡增大了气体交换面积，鼻腔黏膜面积大、毛细血管密集分布其上，有利于温暖吸入的空气；消化液的种类多少与表面积无关，消化道增大表面积靠的是小肠绒毛等结构。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第27题第(3)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"蜂虎的栖息地丧失、环境污染正威胁着蜂虎的生存。划线部分体现了环境与生物的关系是（ ）。","options":[{"key":"A","text":"生物影响环境"},{"key":"B","text":"环境影响生物"},{"key":"C","text":"生物适应环境"},{"key":"D","text":"环境适应生物"}],"answer":"B","explanation":"栖息地丧失、环境污染使蜂虎生存受威胁，是环境条件的变化影响了生物的生存。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第29题第(2)b小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"为探究光照时间对番茄生长和产量的影响，将A、B组均置于自然光照下，并在实验期间每天天黑后对B组进行4小时补光。测定结果：B组株高、茎粗、单株果数、单果质量均高于A组。从光合作用的角度分析，B组番茄产量更高的原因是（ ）。","options":[{"key":"A","text":"B组光合作用时间更长，产生并积累的有机物更多"},{"key":"B","text":"B组呼吸作用更强，消耗的有机物更多"},{"key":"C","text":"B组蒸腾作用更强，散失的水分更多"},{"key":"D","text":"B组光合作用时间更短，产生的有机物更少"}],"answer":"A","explanation":"B组补光延长了光照时间，光合作用时间更长，制造并积累的有机物更多，产量更高。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第32题第(2)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"小闽开展“绣球的栽培与观察”跨学科实践活动，为探究土壤条件对绣球花色的影响，采用白醋（A组）、清水（B组）、食用碱（C组）以定期浇灌的方式模拟不同土壤条件。待绣球开花时，须观察并记录的是（ ）。","options":[{"key":"A","text":"绣球花香"},{"key":"B","text":"绣球花瓣数目"},{"key":"C","text":"绣球花色"},{"key":"D","text":"绣球植株高度"}],"answer":"C","explanation":"实验探究的是土壤条件对花色的影响，观察指标应是花色；A组花呈蓝色、C组花呈粉红色、B组两种花色皆有。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-microscope","stem":"显微镜的目镜是 10×，物镜是 40×，物像的放大倍数是","options":[{"key":"A","text":"40 倍"},{"key":"B","text":"4 倍"},{"key":"C","text":"400 倍"},{"key":"D","text":"50 倍"}],"answer":"C","explanation":"总放大倍数 = 目镜倍数 × 物镜倍数 = 10 × 40 = 400 倍，要用乘法。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-cell-structures","stem":"植物细胞有、而动物细胞没有的结构是","options":[{"key":"A","text":"细胞膜"},{"key":"B","text":"细胞核"},{"key":"C","text":"细胞质"},{"key":"D","text":"细胞壁"}],"answer":"D","explanation":"动、植物细胞都有细胞膜、细胞质、细胞核；植物细胞有细胞壁，许多还有液泡，部分有叶绿体。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-cell-to-organism","stem":"一片完整的叶，在结构层次上属于","options":[{"key":"A","text":"器官"},{"key":"B","text":"组织"},{"key":"C","text":"细胞"},{"key":"D","text":"系统"}],"answer":"A","explanation":"整片叶是器官，叶表皮是保护组织；植物体没有“系统”这一层次。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-germination-variables","stem":"探究“水分对种子萌发的影响”，下列做法正确的是","options":[{"key":"A","text":"不需要设置对照组"},{"key":"B","text":"只改变水分，其他条件相同且适宜"},{"key":"C","text":"同时改变水分和温度"},{"key":"D","text":"每组只放 1 粒种子"}],"answer":"B","explanation":"控制单一变量才能判断差异由谁造成；每组用多粒种子可以减小偶然性。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-fruit-and-seed","stem":"我们吃的桃肉属于果皮，它是由花的哪一部分发育来的","options":[{"key":"A","text":"受精卵"},{"key":"B","text":"花药"},{"key":"C","text":"子房壁"},{"key":"D","text":"胚珠"}],"answer":"C","explanation":"子房发育成果实，子房壁发育成果皮，胚珠发育成种子，受精卵发育成胚。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"动物体的结构层次：细胞→组织→____→系统→动物体；植物体没有____这一层次。","answer":["器官","系统"],"explanation":"植物体：细胞→组织→器官→植物体。"},{"type":"blank","stem":"血液由血浆和血细胞组成，血细胞中能运输氧气的是____，有止血和加速凝血作用的是____。","answer":["红细胞","血小板"],"explanation":"白细胞能吞噬病菌，有防御和保护作用。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据人教版七年级上册“绿色植物与生物圈中的碳—氧平衡”编写","kind":"简答题","material":"","stem":"比较光合作用和呼吸作用：分别写出场所、原料、产物和能量变化，并说明二者的关系。（8分）","points":[{"text":"光合作用：在叶绿体中，利用光能把二氧化碳和水合成有机物，释放氧气，储存能量","score":3},{"text":"呼吸作用：在线粒体中，利用氧气分解有机物，产生二氧化碳和水，释放能量","score":3},{"text":"关系：相互联系、相互依存；光合作用为呼吸作用提供有机物和氧气，呼吸作用为生命活动提供能量","score":2}],"score":8,"sample":"","explanation":"农业应用：合理密植、增加二氧化碳浓度（光合作用）；中耕松土、夜间降温、储存粮食时降低温度和含水量（呼吸作用）。"},{"type":"essay","tag":"综合题","source":"依据人教版七年级下册“输送血液的泵——心脏”编写","kind":"综合题","material":"","stem":"写出人体体循环和肺循环的途径，并说明经过体循环后血液成分的变化。（8分）","points":[{"text":"体循环：左心室→主动脉→各级动脉→全身毛细血管网→各级静脉→上、下腔静脉→右心房","score":3},{"text":"肺循环：右心室→肺动脉→肺部毛细血管网→肺静脉→左心房","score":3},{"text":"体循环后血液由动脉血变为静脉血","score":2}],"score":8,"sample":"","explanation":"心脏四个腔中左心室壁最厚，因为它要把血液泵向全身；房室瓣、动脉瓣保证血液只能单向流动。"}]}]},{"id":"xiaosimen-shengwu-6","group":"生物","subject":"生物","term":"九年级下册","title":"生物 · 九年级下册 冲刺卷","counts":{"choice":20,"fresh":5,"blank":2,"essay":2},"sections":[{"title":"一、选择题","note":"每题只有一个正确答案。","items":[{"type":"choice","tag":"Claude 精选","source":"改编自2025年四川省泸州市初中学业水平考试·生物第10题第(1)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"转基因的细菌与酵母菌在结构上最大的区别是前者（ ）。","options":[{"key":"A","text":"有成形的细胞核"},{"key":"B","text":"没有细胞壁"},{"key":"C","text":"没有成形的细胞核"},{"key":"D","text":"没有细胞质"}],"answer":"C","explanation":"细菌属于原核生物，没有成形的细胞核；酵母菌属于真核生物，有成形的细胞核。细菌和酵母菌都有细胞膜、细胞质和细胞壁等结构。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第7题","stem":"下列对我国生物多样性的叙述中，不正确的是（ ）。","options":[{"key":"A","text":"我国是生物种类最丰富的国家之一"},{"key":"B","text":"我国是裸子植物最丰富的国家"},{"key":"C","text":"鱼类、鸟类的种类都位于世界前列"},{"key":"D","text":"我国蕨类植物种类居世界第一位"}],"answer":"D","explanation":"我国是生物种类最丰富的国家之一，裸子植物种类占世界已知种数的26.7%、居世界第一，鱼类、鸟类种数都位于世界前列；蕨类植物种类居世界第三位，不是第一位。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第13题","stem":"艾滋病是由HIV引起的威胁人类健康的传染病。下列有关说法正确的是（ ）。","options":[{"key":"A","text":"HIV既是病原体又是传染源"},{"key":"B","text":"与艾滋病患者共同进餐易被感染"},{"key":"C","text":"目前可以通过计划免疫预防感染艾滋病"},{"key":"D","text":"HIV主要侵犯免疫系统而使患者免疫功能下降"}],"answer":"D","explanation":"HIV是引起艾滋病的病原体，传染源是艾滋病患者和HIV携带者；日常共同进餐、握手、拥抱不会感染HIV；艾滋病目前既无疫苗可预防，也无有效药物治疗；HIV主要侵犯免疫系统，使患者免疫功能下降。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第19题","stem":"遗传病会给家庭、社会造成极大不幸，下列措施中不能预防遗传病发生的是（ ）。","options":[{"key":"A","text":"禁止近亲结婚"},{"key":"B","text":"婚前检查"},{"key":"C","text":"遗传咨询"},{"key":"D","text":"吃保健药"}],"answer":"D","explanation":"预防遗传病的措施主要是禁止近亲结婚、婚前检查、遗传咨询、提倡适龄生育和产前诊断。吃保健药是环境因素，不改变胎儿的遗传物质，不能预防遗传病。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省各地中考生物四模试卷第23题","stem":"银杉数量减少的主要原因是（ ）。","options":[{"key":"A","text":"森林被伐，环境遭破坏"},{"key":"B","text":"很难繁殖"},{"key":"C","text":"过度开发"},{"key":"D","text":"自然灾害太多"}],"answer":"B","explanation":"银杉生长需要一定光照，容易被生长快的阔叶树遮蔽导致幼苗死亡，而且营养繁殖成活率低、嫁接繁殖仅少量成活，繁殖困难是其数量减少的主要原因。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025届福建省各地中考生物四模试卷第29题（原为非选择题填空，改为单选题）","stem":"将多个品种的三角梅经过人工处理，可形成五彩缤纷的一树多种“花”现象。这一现象采用的生物技术是（ ）。","options":[{"key":"A","text":"嫁接"},{"key":"B","text":"杂交"},{"key":"C","text":"克隆"},{"key":"D","text":"组织培养"}],"answer":"A","explanation":"嫁接是把一个植物体的芽或枝接在另一个植物体上，使结合的两部分长成一个完整的植物体。把多个品种的三角梅枝条嫁接到同一砧木上，就能一树开出多种颜色的花。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第6题","stem":"下列关于遗传病的说法，错误的是（ ）。","options":[{"key":"A","text":"遗传病主要是由遗传物质异常引起的疾病"},{"key":"B","text":"遗传物质的改变一定会导致遗传病的产生"},{"key":"C","text":"近亲结婚会增加后代遗传病的发病率"},{"key":"D","text":"色盲属于遗传病"}],"answer":"B","explanation":"遗传病是由遗传物质改变引起的疾病，但遗传物质的改变不一定导致遗传病。近亲带有相同隐性致病基因的可能性较大，近亲结婚会增加后代遗传病发病率；色盲是遗传病。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第14题","stem":"下列食品运用发酵技术的是（ ）。①葡萄酒 ②地瓜干 ③甜面酱 ④老酸奶 ⑤火腿肠 ⑥豆腐","options":[{"key":"A","text":"①③④"},{"key":"B","text":"③④⑤"},{"key":"C","text":"①②⑥"},{"key":"D","text":"②④⑥"}],"answer":"A","explanation":"酿制葡萄酒用到酵母菌，甜面酱用到霉菌，老酸奶用到乳酸菌，三者都运用了发酵技术；地瓜干、火腿肠、豆腐没有运用发酵技术。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第25题","stem":"在流行性感冒流行期间，班上不少同学患病，为了防止其他同学被传染，老师把患病的学生送回家治疗。这种做法属于传染病预防措施中的（ ）。","options":[{"key":"A","text":"控制传染源"},{"key":"B","text":"切断传播途径"},{"key":"C","text":"保护易感人群"},{"key":"D","text":"以上都不是"}],"answer":"A","explanation":"流感是呼吸道传染病，患病同学是传染源，把患病学生送回家治疗，是针对传染源采取的措施，属于控制传染源。"},{"type":"choice","tag":"Claude 精选","source":"2025届福建省福州十八中学中考生物模拟预测题第33题","stem":"悉尼奥运会期间，人们利用蚯蚓处理垃圾，这是利用了蚯蚓的哪种生理功能（ ）。","options":[{"key":"A","text":"运动"},{"key":"B","text":"食性"},{"key":"C","text":"呼吸"},{"key":"D","text":"昼伏夜出"}],"answer":"B","explanation":"蚯蚓吃进腐烂的有机物和大量土粒，经过消化形成粪便排出体外，粪便中含有丰富的氮、磷、钾等养分。利用蚯蚓处理垃圾，就是利用了蚯蚓取食腐烂有机物的食性。"},{"type":"choice","tag":"Claude 精选","source":"改编自2025届福建省福州十八中学中考生物模拟预测题第37题第(1)小题（原为非选择题填空，改为单选题）","stem":"引起甲流的微生物没有细胞结构，不能独立生活，寄生于呼吸道黏膜上皮细胞中，由此可以推断出此种生物是（ ）。","options":[{"key":"A","text":"病毒"},{"key":"B","text":"细菌"},{"key":"C","text":"真菌"},{"key":"D","text":"衣藻"}],"answer":"A","explanation":"病毒没有细胞结构，只有蛋白质外壳和内部的遗传物质，不能独立生活，必须寄生在活细胞内。细菌、真菌、衣藻都有细胞结构。"},{"type":"choice","tag":"Claude 精选","source":"2026年福建中考·生物第14题","stem":"齐氏罗非鱼耐污染、适应低氧环境，具有极强的资源掠夺与空间占据能力，已被列入我国《重点管理外来入侵物种名录》。下列关于齐氏罗非鱼的叙述，不合理的是（ ）。","options":[{"key":"A","text":"适应能力强"},{"key":"B","text":"影响本地鱼类"},{"key":"C","text":"威胁生态安全"},{"key":"D","text":"可随意放生"}],"answer":"D","explanation":"外来入侵物种不能随意放生，随意放生会危害本地物种和生态安全。齐氏罗非鱼适应能力强、会挤占本地鱼类的生存空间、威胁生态安全，这三项都合理。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第28题第(2)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"国家一级保护野生动物穿山甲体表覆盖角质鳞片、不具齿、胎生、哺乳，挖掘蚁穴、食蚁类。穿山甲属于脊椎动物中的（ ）。","options":[{"key":"A","text":"鱼类"},{"key":"B","text":"两栖动物"},{"key":"C","text":"爬行动物"},{"key":"D","text":"哺乳动物"}],"answer":"D","explanation":"胎生、哺乳是哺乳动物的特征；穿山甲虽体表覆盖角质鳞片，但胎生、哺乳，故为哺乳动物；鱼类用鳃呼吸、卵生，两栖动物幼体生活在水中、成体水陆两栖，爬行动物卵生、体温不恒定。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第30题第(2)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"番茄果实的红色由显性基因（A）控制，黄色由隐性基因（a）控制。若要判断一株红果番茄的基因组成，可将其与黄果番茄杂交。若子代番茄红果和黄果的比例接近1:1，则待测番茄的基因组成是（ ）。","options":[{"key":"A","text":"AA"},{"key":"B","text":"Aa"},{"key":"C","text":"aa"},{"key":"D","text":"A"}],"answer":"B","explanation":"黄果番茄基因组成为aa；待测红果为Aa时，与aa杂交，子代基因组成为Aa（红果）与aa（黄果）各占一半；若待测红果为AA，子代基因组成均为Aa、全部表现为红果。"},{"type":"choice","tag":"Claude 精选","source":"改编自2026年福建省初中学业水平考试·生物第33题第(3)小题（原为非选择题填空，改为单选题，选项为改编时补写）","stem":"接种甲型肝炎疫苗无法预防霍乱，是因为该疫苗无法刺激人体产生识别霍乱弧菌的（ ）。","options":[{"key":"A","text":"抗原"},{"key":"B","text":"抗体"},{"key":"C","text":"抗生素"},{"key":"D","text":"病原体"}],"answer":"B","explanation":"抗体具有特异性，一种抗体只能针对特定的抗原起作用；甲肝疫苗刺激人体产生的是识别甲肝病毒的抗体，不能识别霍乱弧菌，所以不能预防霍乱；疫苗本身进入人体相当于抗原，抗生素用来治疗细菌性疾病。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-reflex-arc","stem":"在反射弧中，执行反应的结构是","options":[{"key":"A","text":"感受器"},{"key":"B","text":"神经中枢"},{"key":"C","text":"传入神经"},{"key":"D","text":"效应器"}],"answer":"D","explanation":"反射弧依次是感受器、传入神经、神经中枢、传出神经、效应器；效应器执行反应。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-bones-and-muscles","stem":"屈肘时，肱二头肌和肱三头肌的状态是","options":[{"key":"A","text":"肱二头肌收缩，肱三头肌舒张"},{"key":"B","text":"肱二头肌舒张，肱三头肌收缩"},{"key":"C","text":"两者同时收缩"},{"key":"D","text":"两者同时舒张"}],"answer":"A","explanation":"肌肉只能牵拉骨；屈肘和伸肘时两块肌肉的收缩、舒张状态相反。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-hormone-regulation","stem":"能调节血糖浓度的激素是","options":[{"key":"A","text":"唾液淀粉酶"},{"key":"B","text":"胰岛素"},{"key":"C","text":"甲状腺激素"},{"key":"D","text":"生长激素"}],"answer":"B","explanation":"胰岛素调节血糖；唾液淀粉酶是消化酶，不是激素。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-sexual-asexual","stem":"下列繁殖方式属于无性生殖的是","options":[{"key":"A","text":"青蛙的受精卵发育成蝌蚪"},{"key":"B","text":"受精的鸡蛋孵出小鸡"},{"key":"C","text":"柳枝扦插长成新植株"},{"key":"D","text":"用种子繁殖小麦"}],"answer":"C","explanation":"无性生殖不经过两性生殖细胞结合；扦插、嫁接是常见例子。"},{"type":"choice","tag":"Claude 冲刺","kp":"shengwu-gene-dna-chromosome","stem":"基因是","options":[{"key":"A","text":"染色体的全部"},{"key":"B","text":"蛋白质分子"},{"key":"C","text":"细胞核"},{"key":"D","text":"有遗传效应的 DNA 片段"}],"answer":"D","explanation":"染色体主要由 DNA 和蛋白质组成，基因是有遗传效应的 DNA 片段，一条染色体上有多个基因。"}]},{"title":"二、填空速记","items":[{"type":"blank","stem":"生物分类单位从大到小依次是：界、门、纲、目、科、属、____，其中____是最基本的分类单位。","answer":["种","种"],"explanation":"分类单位越小，生物之间共同特征越多，亲缘关系越近。"},{"type":"blank","stem":"____是遗传物质的主要载体，____是包含遗传信息的DNA片段。","answer":["染色体","基因"],"explanation":"染色体由DNA和蛋白质组成。"}]},{"title":"三、主观题","note":"先自己写，再对照得分点给自己打分。","items":[{"type":"essay","tag":"简答题","source":"依据人教版八年级上册“保护生物的多样性”编写","kind":"简答题","material":"","stem":"生物多样性包括哪三个层次？生物多样性面临威胁的主要原因是什么？保护生物多样性最有效的措施是什么？（7分）","points":[{"text":"三个层次：生物种类（物种）多样性、基因（遗传）多样性、生态系统多样性","score":3},{"text":"主要原因：栖息地的破坏和丧失；此外还有乱砍滥伐、乱捕滥杀、环境污染、外来物种入侵","score":2},{"text":"最有效的措施：建立自然保护区（就地保护）","score":2}],"score":7,"sample":"","explanation":"生物种类多样性的实质是基因多样性。"},{"type":"essay","tag":"简答题","source":"依据人教版八年级下册“传染病及其预防”编写","kind":"简答题","material":"","stem":"传染病流行的三个基本环节是什么？预防传染病的措施有哪些？请以流感为例各举一例。（7分）","points":[{"text":"三个基本环节：传染源、传播途径、易感人群","score":3},{"text":"控制传染源：如隔离治疗流感病人","score":1},{"text":"切断传播途径：如戴口罩、开窗通风、消毒","score":2},{"text":"保护易感人群：如接种流感疫苗、加强体育锻炼","score":1}],"score":7,"sample":"","explanation":"传染病具有传染性和流行性；病原体是引起传染病的细菌、病毒、寄生虫等。"}]}]}];
